SDCARD = {"t": 0.0, "dev": "", "base": "", "part": "", "last_sec": None, "boot": "", "days": {}, "first_t": 0.0, "today_mb": 0.0,
		  "saved_t": 0.0, "ext4_err": None, "dmesg": None, "dmesg_t": 0.0, "dmesg_ok": None, "dmesg_last": "", "overlay": False,
		  "root_ro": False, "life": None, "logged_err": 0, "busy": False}
SD_SAMPLE_S = 600
SD_SAVE_S = 3600
SD_ERR_RX = re.compile(r"EXT4-fs (?:error|warning)|Buffer I/O error|I/O error, dev|blk_update_request: .*error|FAT-fs .*error"
					   r"|mmc\d+: .*(?:error|timeout|CRC)|Remounting filesystem read-only|EXT4-fs .*read-only", re.I)


def _sd_file():
	return os.path.join(DATA_DIR, "sdcard_wear.json")


def _sd_block_of(path):
	"""
"""
	try:
		st = os.stat(path)
		p = os.path.realpath("/sys/dev/block/%d:%d" % (os.major(st.st_dev), os.minor(st.st_dev)))
	except (OSError, AttributeError, ValueError):
		return "", ""
	if not os.path.isdir(p):
		return "", ""
	name = os.path.basename(p)
	if os.path.isfile(os.path.join(p, "partition")):
		return name, os.path.basename(os.path.dirname(p))
	return name, name


def _sd_find():
	""
	part, base = _sd_block_of(DATA_DIR if os.path.isdir(DATA_DIR) else "/")
	if not base:
		part, base = _sd_block_of("/")
	if not base and os.path.isfile("/sys/block/mmcblk0/stat"):
		part, base = "", "mmcblk0"
	return part, base


def _sd_read_int(p):
	try:
		with open(p) as f:
			return int(f.read().split()[0], 0)
	except (OSError, ValueError, IndexError):
		return None


def _sd_sectors(base):
	""
	try:
		with open(f"/sys/block/{base}/stat") as f:
			v = f.read().split()
		return int(v[6])
	except (OSError, ValueError, IndexError):
		return None


def _sd_mounts():
	""
	ov = ro = False
	try:
		with open("/proc/mounts") as f:
			for ln in f:
				x = ln.split()
				if len(x) >= 4 and x[1] == "/":
					ov = x[2] == "overlay" or ov
					ro = (x[2] != "overlay" and "ro" in x[3].split(","))
	except OSError:
		pass
	try:
		with open("/proc/cmdline") as f:
			ov = ov or "overlayroot=tmpfs" in f.read()
	except OSError:
		pass
	return ov, ro


def _sd_dmesg():
	""
	if not shutil.which("dmesg"):
		return None, ""
	try:
		r = subprocess.run(["dmesg"], capture_output=True, text=True, timeout=4)
	except (OSError, subprocess.SubprocessError):
		return None, ""
	if r.returncode != 0 or not r.stdout:
		return None, ""
	hits = [ln.strip() for ln in r.stdout.splitlines() if SD_ERR_RX.search(ln)]
	return len(hits), (hits[-1][-160:] if hits else "")


def _sd_boot_id():
	try:
		with open("/proc/sys/kernel/random/boot_id") as f:
			return f.read().strip()
	except OSError:
		return ""


def _sd_load():
	try:
		with open(_sd_file()) as f:
			d = json.load(f)
		if isinstance(d, dict):
			SDCARD["days"] = {k: float(v) for k, v in (d.get("days") or {}).items() if isinstance(v, (int, float))}
			if d.get("boot") == SDCARD["boot"] and isinstance(d.get("sec"), int):
				SDCARD["last_sec"] = d["sec"]
			SDCARD["first_t"] = float(d.get("first") or 0.0)
	except (OSError, ValueError, TypeError):
		pass


def _sd_save():
	days = dict(sorted(SDCARD["days"].items())[-21:])
	SDCARD["days"] = days
	try:
		tmp = _sd_file() + ".tmp"
		with open(tmp, "w") as f:
			json.dump({"days": {k: round(v, 1) for k, v in days.items()}, "boot": SDCARD["boot"], "sec": SDCARD["last_sec"],
					   "first": SDCARD["first_t"]}, f)
		os.replace(tmp, _sd_file())
		SDCARD["saved_t"] = time.time()
	except OSError:
		pass


def sdcard_tick(force=False):
	""
	now = time.time()
	if SDCARD["busy"] or (not force and now - SDCARD["t"] < SD_SAMPLE_S):
		return
	SDCARD["busy"] = True
	try:
		first = not SDCARD["t"]
		SDCARD["t"] = now
		if first:
			SDCARD["part"], SDCARD["base"] = _sd_find()
			SDCARD["boot"] = _sd_boot_id()
			_sd_load()
			if not SDCARD["first_t"]:
				SDCARD["first_t"] = now
			b = SDCARD["base"]
			if b:
				for nm in ("life_time", "pre_eol_info"):
					v = None
					try:
						with open(f"/sys/block/{b}/device/{nm}") as f:
							v = f.read().split()
					except OSError:
						pass
					if v and nm == "life_time":
						try:
							SDCARD["life"] = max(int(x, 16) for x in v)
						except ValueError:
							pass
		SDCARD["overlay"], SDCARD["root_ro"] = _sd_mounts()
		b = SDCARD["base"]
		if b:
			sec = _sd_sectors(b)
			if sec is not None:
				last = SDCARD["last_sec"]
				add = (sec - last) if (last is not None and sec >= last) else (0 if last is None else sec)
				SDCARD["last_sec"] = sec
				day = datetime.now().strftime("%Y-%m-%d")
				SDCARD["days"][day] = SDCARD["days"].get(day, 0.0) + add * 512 / 1e6
				SDCARD["today_mb"] = SDCARD["days"][day]
			part = SDCARD["part"] or b
			SDCARD["ext4_err"] = _sd_read_int(f"/sys/fs/ext4/{part}/errors_count")
		if force or now - SDCARD["dmesg_t"] > 1800:
			SDCARD["dmesg_t"] = now
			n, last_ = _sd_dmesg()
			SDCARD["dmesg_ok"] = n is not None
			SDCARD["dmesg"] = n
			SDCARD["dmesg_last"] = last_
		errs = int(SDCARD["ext4_err"] or 0) + int(SDCARD["dmesg"] or 0)
		if errs > SDCARD["logged_err"]:
			SDCARD["logged_err"] = errs
			log_event("sys", f"Memory card: {errs} file system / read error(s) found" + (f" - {SDCARD['dmesg_last']}" if SDCARD["dmesg_last"] else ""))
		if b and (now - SDCARD["saved_t"] > SD_SAVE_S or len(SDCARD["days"]) and max(SDCARD["days"]) != datetime.now().strftime("%Y-%m-%d")):
			_sd_save()
	except Exception as e:
		print(f"memory card check: {e}")
	finally:
		SDCARD["busy"] = False


def sdcard_rate():
	""
	today = datetime.now().strftime("%Y-%m-%d")
	full = [v for k, v in sorted(SDCARD["days"].items()) if k != today][-7:]
	if full:
		return sum(full) / len(full), True
	t0 = max(SDCARD["first_t"], datetime.now().replace(hour=0, minute=0, second=0, microsecond=0).timestamp())
	span = time.time() - t0
	if span < 1200:
		return None, False
	return SDCARD.get("today_mb", 0.0) * 86400.0 / span, False


def sdcard_state():
	sdcard_tick()
	r, full = sdcard_rate()
	return {"dev": SDCARD["base"], "part": SDCARD["part"], "mb_day": round(r, 1) if r is not None else None, "days_known": full,
			"today_mb": round(SDCARD.get("today_mb", 0.0), 1), "ext4_errors": SDCARD["ext4_err"], "dmesg_errors": SDCARD["dmesg"],
			"dmesg_readable": SDCARD["dmesg_ok"], "dmesg_last": SDCARD["dmesg_last"], "overlay": SDCARD["overlay"],
			"root_ro": SDCARD["root_ro"], "emmc_life": SDCARD["life"], "free_mb": (STATE.get("disk") or {}).get("free_mb")}


def sdcard_health_item(L):
	""
	T = lambda x: tr(x, L)
	s = sdcard_state()
	if not s["dev"] and not s["overlay"]:
		return {"id": "sdwear", "icon": "🪪", "title": T("Memory card health"), "level": "off", "text": T("not measurable on this computer"), "tip": "",
				"link": "/help#sdcard"}
	parts, level, tip = [], "ok", ""
	if s["mb_day"] is not None:
		mb = s["mb_day"]
		parts.append(trf("≈ {n} written per day", L, n=(f"{mb / 1000:.1f} GB" if mb >= 1000 else f"{mb:.0f} MB")))
	else:
		parts.append(T("write volume: measuring (20 min)"))
	if s["free_mb"] is not None:
		parts.append(f"{s['free_mb'] / 1024:.1f} GB " + T("free"))
	errs = int(s["ext4_errors"] or 0) + int(s["dmesg_errors"] or 0)
	if errs:
		parts.append(trf("{n} file system error(s)", L, n=errs))
		level = "bad"
		tip = "The memory card reports errors: copy the recordings, check the card on a PC (or replace it) and use the read-only protection during the season."
	elif s["dmesg_readable"] is False and s["ext4_errors"] is None:
		parts.append(T("errors: not readable"))
	else:
		parts.append(T("no file system errors"))
	if s["root_ro"]:
		level = "bad"
		parts.append(T("read-only after errors"))
		tip = "The system switched the card to read-only (errors). Restart; if it happens again, replace the card."
	if s["overlay"]:
		parts.append(T("read-only protection on"))
		try:
			rd = rec_dir() if os.path.isdir(rec_dir()) else ""
		except Exception:
			rd = ""
		if rd and not _sd_block_of(rd)[1] and level == "ok":
			level = "warn"
			tip = ("Read-only protection is on: recordings and changed settings stay only in the memory (RAM) and are gone after a restart. "
				   "Put the recordings on a USB drive / SSD (Settings → Recording).")
	elif level == "ok" and s["mb_day"] is not None and s["mb_day"] > 5000:
		level = "warn"
		tip = "A lot is written to the card: put the recordings on a USB drive / SSD, switch off continuous recording, or use the read-only protection during the season."
	if s["emmc_life"] is not None and s["emmc_life"] >= 0x08 and level != "bad":
		level = "warn"
		parts.append(trf("worn {p} %", L, p=min(100, s["emmc_life"] * 10)))
		tip = "The memory chip is quite worn: plan a replacement."
	return {"id": "sdwear", "icon": "🪪", "title": T("Memory card health"), "level": level, "text": " · ".join(parts), "tip": T(tip) if tip else "",
			"link": "/help#sdcard"}








def msglog_recent(n=4):
	""
	try:
		with MSGLOG["lock"]:
			items = list(_msglog_load()[-n:])
		return [[str(x.get("id", "")), round(float(x.get("t", 0.0)), 2), str(x.get("ev", "")), str(x.get("status", ""))] for x in items]
	except Exception:
		return []








I2C_SLAVE = 0x0703
SERVO_MOVE = {"t": 0.0}


class PCA9685:
	def __init__(self, addr, bus=1, freq=50.0):
		import fcntl
		self.addr, self.freq = addr, float(freq)
		self.fd = os.open(f"/dev/i2c-{bus}", os.O_RDWR)
		try:
			fcntl.ioctl(self.fd, I2C_SLAVE, addr)


			if self._r(0x01) & 0xE0 or self._r(0x05) != 0xE0:
				raise OSError(f"the chip at 0x{addr:02x} is not a PCA9685")
			pre = int(round(25e6 / (4096 * self.freq))) - 1
			self._w(0x00, 0x10)
			self._w(0xFE, pre)
			self._w(0x01, 0x04)
			self._w(0x00, 0x20)
			time.sleep(0.005)
			self._w(0x00, 0xA0)
			if self._r(0xFE) != pre:
				raise OSError("PCA9685 does not answer correctly")
			self.pre = pre
		except Exception:
			os.close(self.fd); raise

	def _w(self, reg, val):
		os.write(self.fd, bytes([reg, val & 0xFF]))

	def _r(self, reg):
		os.write(self.fd, bytes([reg]))
		return os.read(self.fd, 1)[0]

	def healthy(self):
		""
		return not (self._r(0x00) & 0x10) and self._r(0xFE) == getattr(self, "pre", self._r(0xFE))

	def _set(self, ch, on, off):
		os.write(self.fd, bytes([0x06 + 4 * ch, on & 0xFF, (on >> 8) & 0xFF, off & 0xFF, (off >> 8) & 0xFF]))

	def pulse_us(self, ch, us):
		self._set(ch, 0, max(0, min(4095, int(round(us * 4096 * self.freq / 1e6)))))

	def switch(self, ch, on):
		self._set(ch, 0x1000, 0) if on else self._set(ch, 0, 0x1000)

	def close(self):
		try:
			os.write(self.fd, bytes([0xFA, 0, 0, 0, 0x10]))
		except OSError:
			pass
		try:
			os.close(self.fd)
		except OSError:
			pass


def pca_present(addr, bus=1):
	try:
		p = PCA9685.__new__(PCA9685)
		import fcntl
		p.fd = os.open(f"/dev/i2c-{bus}", os.O_RDWR)
		try:
			fcntl.ioctl(p.fd, I2C_SLAVE, addr)
			return not (p._r(0x01) & 0xE0) and p._r(0x05) == 0xE0
		finally:
			os.close(p.fd)
	except Exception:
		return False









MOVER = {"test": False, "avail": False, "hw": False, "sim": False, "v": 0.0, "w": 0.0, "l": 0.0, "r": 0.0, "cmd_t": 0.0, "by": "", "msg": "off",
		 "move_t": 0.0}



MOVER_QUIET_S = 3.0
MOVER_RUN_MIN = 0.02


def mover_own_motion(now=None):
	""
	now = time.time() if now is None else now
	if abs(float(MOVER.get("l") or 0.0)) > MOVER_RUN_MIN or abs(float(MOVER.get("r") or 0.0)) > MOVER_RUN_MIN:
		return True
	return now - float(MOVER.get("move_t") or 0.0) < MOVER_QUIET_S
MOVER_MAP = {"adafruit": ((8, 10, 9), (13, 11, 12)),
			 "waveshare": ((0, 1, 2), (5, 3, 4))}
MOVERCTL = None


def mover_drive(v, w, who="web"):
	""
	try:
		v = max(-1.0, min(1.0, float(v))); w = max(-1.0, min(1.0, float(w)))
	except (TypeError, ValueError):
		return False
	if not MOVER["avail"]:
		return False
	if CFG.get("servo_estop"):
		return False
	MOVER.update(v=v, w=w, cmd_t=time.monotonic(), by=who)
	if abs(v) > 0.05 or abs(w) > 0.05:
		MOVER["move_t"] = time.time()
		MANUAL["until"] = time.time() + CFG["manual_hold"]
		mover_sim_wake()
	return True


_MOVER_WAKE = {"t": 0.0}


def _mover_pose(p):
	"""
"""
	if not isinstance(p, dict):
		return None
	try:
		out = {k: round(float(p[k]), 2) for k in ("x", "y", "yaw", "odo") if k in p and math.isfinite(float(p[k]))}
	except (TypeError, ValueError):
		return None
	if "blocked" in p:
		out["blocked"] = bool(p.get("blocked"))
	return out or None


def mover_sim_wake():
	""
	now = time.time()
	if not (CFG.get("sim_on") and SIM.get("ok")) or SIM.get("mover") or now - _MOVER_WAKE["t"] < 8.0:
		return
	_MOVER_WAKE["t"] = now

	def work():
		try:
			d = sim_control()
			if any(c.get("id") == "mover_on" for c in (d.get("controls") or [])):
				sim_control({"action": "set", "id": "mover_on", "value": True})
				log_event("sys", "Simulation: vehicle switched on in the simulator (driven with the second stick)")
		except Exception:
			pass
	threading.Thread(target=work, daemon=True, name="mover-wake").start()


def mover_choice_pairs(extra):
	if extra == "mover_mode":
		return [("auto", tr("automatic: on when the motor driver is found")), ("off", tr("off"))]
	if extra == "mover_driver":
		return [("adafruit", tr("Motor HAT (Adafruit or compatible): M1 left, M2 right")),
				("waveshare", tr("Waveshare Motor Driver HAT: A left, B right"))]
	if extra == "mover_addr":
		return [(f"0x{a:02x}", f"0x{a:02x}") for a in list(range(0x60, 0x70)) + list(range(0x40, 0x48))]
	return []


class MoverControl:
	def __init__(self):
		self.pca = None; self.addr = None; self.next_look = 0.0
		threading.Thread(target=self.loop, daemon=True, name="mover").start()

	def _close(self):
		if self.pca is not None:
			try:
				self.pca.close()
			except Exception:
				pass
		self.pca = None; self.addr = None

	def _find(self):
		""
		try:
			a = int(str(CFG["mover_addr"]), 16)
		except ValueError:
			a = 0x60
		if self.pca is not None and self.addr == a:
			return True
		self._close()
		try:
			if str(CFG.get("pca_address", "")).lower() == f"0x{a:02x}" and CFG.get("servo_driver") != "gpio":
				MOVER["msg"] = "the address is the one of the servo driver"; return False
		except Exception:
			pass
		if not pca_present(a):
			MOVER["msg"] = "no motor driver found"; return False
		try:
			self.pca = PCA9685(a, freq=1600.0); self.addr = a
			MOVER["msg"] = "motor driver found"
			return True
		except Exception as e:
			MOVER["msg"] = "motor driver: " + str(e)[:60]; self.pca = None
			return False

	def _motor(self, pins, s):
		pwm, in1, in2 = pins
		s = max(-1.0, min(1.0, s))
		if abs(s) < 0.02:
			self.pca.switch(in1, False); self.pca.switch(in2, False); self.pca._set(pwm, 0, 0x1000)
			return
		self.pca.switch(in1, s > 0); self.pca.switch(in2, s < 0)
		self.pca._set(pwm, 0, max(0, min(4095, int(abs(s) * 4095))))

	def stop_now(self):
		""
		MOVER.update(v=0.0, w=0.0, l=0.0, r=0.0)
		if self.pca is not None:
			try:
				pins = MOVER_MAP.get(CFG["mover_driver"], MOVER_MAP["adafruit"])
				self._motor(pins[0], 0.0); self._motor(pins[1], 0.0)
			except Exception:
				pass

	def loop(self):
		atexit.register(self.stop_now)
		while True:
			try:
				self._loop()
			except Exception as e:
				self.stop_now()
				log_event("sys", f"Mover error - motors stopped: {type(e).__name__}: {e}"[:200])
				time.sleep(2)

	def _loop(self):
		last = time.monotonic()
		while True:
			time.sleep(0.05)

			now = time.monotonic(); dt = max(0.0, min(0.2, now - last)); last = now
			sim = bool(CFG.get("sim_on"))
			if CFG["mover_mode"] == "off":
				self._close(); MOVER.update(avail=False, hw=False, test=False, msg="off")
			elif sim:
				self._close(); MOVER["hw"] = False
				real = bool(SIM.get("ok")) and bool(SIM.get("mover"))
				MOVER["avail"] = real or bool(CFG.get("mover_sim_show"))
				MOVER["test"] = MOVER["avail"] and not real
				MOVER["msg"] = "simulated" if real else ("stick shown for testing (the simulator has no mover)" if MOVER["avail"] else "the simulator has no mover")
			else:
				MOVER["test"] = False
				if self.pca is None and time.time() >= self.next_look:
					self.next_look = time.time() + 15.0
					self._find()
				MOVER["hw"] = self.pca is not None; MOVER["avail"] = MOVER["hw"]
			MOVER["sim"] = sim and MOVER["avail"]

			fresh = now - MOVER["cmd_t"] < 0.6
			tv = MOVER["v"] if fresh and MOVER["avail"] else 0.0
			tw = MOVER["w"] if fresh and MOVER["avail"] else 0.0
			sp = float(CFG["mover_speed"]) / 100.0; tu = float(CFG["mover_turn"]) / 100.0
			tl, trr = tv * sp + tw * tu, tv * sp - tw * tu
			m = max(1.0, abs(tl), abs(trr)); tl /= m; trr /= m
			ramp = float(CFG["mover_ramp"])
			k = 1.0 if ramp <= 0.01 else dt / ramp
			stop_fast = not fresh
			k2 = max(0.0, min(1.0, k * (4.0 if stop_fast else 1.0)))
			l = MOVER["l"] + max(-k2, min(k2, tl - MOVER["l"]))
			r = MOVER["r"] + max(-k2, min(k2, trr - MOVER["r"]))
			MOVER["l"], MOVER["r"] = round(l, 3), round(r, 3)
			if abs(l) > MOVER_RUN_MIN or abs(r) > MOVER_RUN_MIN:
				MOVER["move_t"] = time.time()
			if self.pca is not None and not sim:
				ml, mr = l, r
				if CFG["mover_swap"]:
					ml, mr = mr, ml
				if CFG["mover_inv_l"]:
					ml = -ml
				if CFG["mover_inv_r"]:
					mr = -mr
				pins = MOVER_MAP.get(CFG["mover_driver"], MOVER_MAP["adafruit"])
				try:
					self._motor(pins[0], ml); self._motor(pins[1], mr)
				except OSError as e:
					MOVER["msg"] = "motor driver: " + str(e)[:60]; self._close()







LIGHTS = {"alarm_t": 0.0, "dark": False, "dark_t": 0.0, "strobe_until": 0.0}



DISCO = {"on": False, "until": 0.0, "mode": "music", "bpm": 120, "avg": None, "last": 0.0, "flash_until": 0.0, "beats": 0, "t0": 0.0}


def disco_set(on, mode=None, bpm=None, minutes=None, who="web"):
	if mode in ("music", "tempo"):
		DISCO["mode"] = mode
	if bpm is not None:
		DISCO["bpm"] = int(max(60, min(170, int(bpm))))
	if on:
		DISCO.update(on=True, until=time.time() + 60 * max(5, min(480, int(minutes or 120))), avg=None, beats=0, t0=time.time())
		log_event("relay", f"Disco light on ({DISCO['mode']}, {who})")
	elif DISCO["on"]:
		DISCO["on"] = False
		log_event("relay", f"Disco light off ({who})")


def _disco_white(now):
	""
	if not DISCO["on"]:
		return None
	if now > DISCO["until"]:
		DISCO["on"] = False
		return None
	gap = 1.0 / 3.0
	if DISCO["mode"] == "tempo":
		per = max(gap, 60.0 / max(60, DISCO["bpm"]))
		ph = ((now - DISCO["t0"]) % per) / per
		return ph < 0.35
	lv = (STATE.get("audio") or {}).get("level")
	if lv is None:
		per = 60.0 / max(60, DISCO["bpm"])
		return ((now - DISCO["t0"]) % per) / per < 0.35
	a = DISCO["avg"]
	DISCO["avg"] = lv if a is None else a * 0.96 + lv * 0.04
	if a is not None and lv > a + 4.0 and now - DISCO["last"] > gap:
		DISCO["last"] = now; DISCO["flash_until"] = now + 0.14; DISCO["beats"] += 1
	return now < DISCO["flash_until"]


def disco_state():
	return {"on": DISCO["on"], "mode": DISCO["mode"], "bpm": DISCO["bpm"], "left": max(0, int(DISCO["until"] - time.time())) if DISCO["on"] else 0,
			"beats": DISCO["beats"], "mic": (STATE.get("audio") or {}).get("level") is not None, "white": bool(CFG.get("light_white_out")) or bool(CFG.get("sim_on"))}
LIGHT_MODES = ("off", "on", "auto")
LIGHT_NAMES = {"white": "White light", "ir": "Infrared light"}


def is_dark():
	if CFG.get("sim_on") and time.time() - SIM["t"] < 10:
		return bool(SIM["dark"])
	now = time.time()
	if now - LIGHTS["dark_t"] > 60:
		LIGHTS["dark_t"] = now
		try:
			d = datetime.now()
			st = sun_times(d.date(), float(CFG["latitude"]), float(CFG["longitude"]))
			if isinstance(st, str):
				LIGHTS["dark"] = st == "dark"
			else:
				m = d.hour * 60 + d.minute
				LIGHTS["dark"] = m < st[0] or m > st[1]
		except Exception:
			pass
	return LIGHTS["dark"]


def light_alarm():
	LIGHTS["alarm_t"] = time.time()


def lights_tick():
	now = time.time(); dark = is_dark()
	alarm = LIGHTS["alarm_t"] > 0 and now - LIGHTS["alarm_t"] < float(CFG["light_hold"])
	res = {}
	for n in ("white", "ir"):
		if PAUSING["on"]:
			res[n] = False; continue
		m, a = CFG["light_" + n], CFG[f"light_{n}_auto"]
		res[n] = (bool(CFG[f"light_{n}_out"]) or bool(CFG["sim_on"])) and (m == "on" or (m == "auto" and (
			(a == "dark" and dark) or (a == "alarm_dark" and alarm and dark) or (a == "alarm" and alarm))))
	strobe = now < LIGHTS.get("strobe_until", 0.0) and not PAUSING["on"]
	dw = _disco_white(now)
	disco = dw is not None and not alarm and not strobe and not PAUSING["on"] and (CFG["light_white_out"] or CFG["sim_on"])
	if disco:
		res["white"] = dw
	if strobe and CFG["light_white_out"]:
		res["white"] = int(now * 5) % 2 == 0
	prev = STATE.get("lights") or {}
	for n in ("white", "ir"):
		if bool(prev.get(n)) != res[n] and not ((strobe or disco) and n == "white"):
			log_event("relay", f"{LIGHT_NAMES[n]} {'ON' if res[n] else 'OFF'}")
	STATE["lights"] = dict(res, dark=dark)
	return res


def light_set(name, mode):
	if name not in ("white", "ir") or mode not in LIGHT_MODES:
		return False, "invalid value"
	CFG["light_" + name] = mode
	save_settings()
	return True, ""


def light_out_pairs(name):
	""
	other = CFG["light_ir_out" if name == "white" else "light_white_out"]
	pairs = [("", "– " + tr("not connected") + " –")]
	used_ch = {int(CFG["pca_pan_ch"]), int(CFG["pca_tilt_ch"])}
	pairs += [(f"pca:{c}", f"PCA9685 {tr('channel')} {c}") for c in range(16) if c not in used_ch and f"pca:{c}" != other]
	used = {r["gpio"] for r in RELAYS} | set(GPIO_RESERVED) | set(thermal_gpios())
	pairs += [(f"gpio:{g}", f"GPIO {g}") for g in sorted(FREE_GPIOS) if g not in used and f"gpio:{g}" != other]
	cur = CFG[f"light_{name}_out"]
	if cur and cur not in [p[0] for p in pairs]:
		pairs.append((cur, cur.replace("pca:", "PCA9685 ").replace("gpio:", "GPIO ")))
	return pairs


def thermal_gpios():
	""
	return (23, 24, 7) if str(CFG.get("thermal_source", "")).startswith("senxor") else ()




























for _k, _v in {"servo_vmax_pan": 120.0, "servo_vmax_tilt": 90.0, "servo_acc_pan": 360.0, "servo_acc_tilt": 300.0,
			   "servo_estop": False, "servo_estop_by": "", "servo_stop_btn": True, "servo_estop_park": False, "servo_uv_stop": True,
			   "servo_wd_s": 10.0}.items():
	CFG.setdefault(_k, _v)
	DEFAULTS.setdefault(_k, _v)
SRV = {"pos": None, "vel": [0.0, 0.0], "tgt": None, "scale": [(1.0, 1.0), (1.0, 1.0)], "cap": None, "moving": False, "arrive_t": 0.0,
	   "start_t": 0.0, "beat": 0.0, "inhibit": "", "inhibit_t": 0.0, "inhibit_log": {}, "fault": "", "fault_t": 0.0,
	   "io_err": 0, "io_t": 0.0, "wd_trip": False, "wd_log": 0.0, "limit_on": [False, False], "parked": False,
	   "estop_t": 0.0, "push_t": 0.0, "safety_t": 0.0, "test_uv": False, "trace": deque(maxlen=1500), "started": False}
SERVO_AXES = ("pan", "tilt")
SRV_FAULT_LOCK = ("i2c", "pca_reset")


def _srv_k(axis):
	""
	return 100.0 / (2.0 * servo_half(axis))


def srv_limits_pct():
	""
	try:
		return Hardware.limits()
	except Exception:
		return [(0.0, 100.0), (0.0, 100.0)]


def srv_clamp(pan, tilt):
	""
	out = []
	for v, (lo, hi) in zip((pan, tilt), srv_limits_pct()):
		try:
			v = float(v)
		except (TypeError, ValueError):
			return None
		if not math.isfinite(v):
			return None
		out.append(max(lo, min(hi, max(0.0, min(100.0, v)))))
	return out[0], out[1]


def srv_axis_limits(axis):
	""
	k = _srv_k(axis)
	try:
		vm = max(5.0, min(600.0, float(CFG.get("servo_vmax_" + axis) or 120.0)))
		am = max(20.0, min(5000.0, float(CFG.get("servo_acc_" + axis) or 300.0)))
	except (TypeError, ValueError):
		vm, am = 120.0, 300.0
	return vm * k, am * k


def srv_axis_step(p, v, tgt, vmax, amax, dt):
	"""



"""
	e = tgt - p
	h = amax * dt
	if abs(e) <= 1e-4 and abs(v) <= h:
		return tgt, 0.0
	s = 1.0 if e > 0 else -1.0
	d = abs(e); vt = v * s
	if 0.0 <= vt <= h * 1.0001 and d <= (vt + h * 0.5) * dt:
		return tgt, 0.0
	q = h * h / 4.0 + 2.0 * amax * d - h * vt
	vs = -h / 2.0 + math.sqrt(q) if q > 0 else 0.0
	vd = s * min(vmax, vs)
	v2 = v + max(-h, min(h, vd - v))
	if vt > 0.0 and v2 * s < 0.0:
		v2 = 0.0
	p2 = p + (v + v2) * 0.5 * dt
	if (tgt - p2) * s < 0.0 and abs(v2) <= h * 1.0001:
		return tgt, 0.0
	return p2, v2


def srv_trap_time(d, vmax, amax):
	""
	d = abs(d)
	if d <= 0:
		return 0.0
	if d >= vmax * vmax / amax:
		return d / vmax + vmax / amax
	return 2.0 * math.sqrt(d / amax)


def srv_sync_scale(dists, lims):
	"""

"""
	ts = [srv_trap_time(d, vm, am) for d, (vm, am) in zip(dists, lims)]
	out = [(1.0, 1.0), (1.0, 1.0)]
	if max(ts) <= 0:
		return out
	li = 0 if ts[0] >= ts[1] else 1
	oi = 1 - li
	dl, do = abs(dists[li]), abs(dists[oi])
	if dl > 1e-6 and do > 1e-6:
		r = do / dl
		vm_l, am_l = lims[li]; vm_o, am_o = lims[oi]
		out[oi] = (max(0.01, min(1.0, vm_l * r / vm_o)), max(0.01, min(1.0, am_l * r / am_o)))
	return out


def servo_pos():
	""
	p = SRV["pos"]
	if p is None:
		return float(CFG["pan"]), float(CFG["tilt"])
	return p[0], p[1]


def servo_pos_deg():
	p, t = servo_pos()
	return (p - 50.0) / 50.0 * servo_half("pan"), (t - 50.0) / 50.0 * servo_half("tilt")


def servo_arrived(tol=0.15):
	""
	p = SRV["pos"]
	if p is None:
		return True
	return (abs(p[0] - float(CFG["pan"])) <= tol and abs(p[1] - float(CFG["tilt"])) <= tol
			and abs(SRV["vel"][0]) < 0.05 and abs(SRV["vel"][1]) < 0.05)


def servo_blocked():
	""
	if CFG.get("servo_estop"):
		return "estop"
	if SRV["fault"]:
		return "fault"
	if SRV["inhibit"]:
		return "inhibit"
	return ""


def servo_blocked_text(lang=None):
	b = servo_blocked()
	if b == "estop":
		return tr("Emergency stop - press «Release» to move again", lang)
	if b == "fault":
		return tr("Servo fault", lang) + ": " + tr(SRV_FAULT_TEXT.get(SRV["fault"], SRV["fault"]), lang) + " - " + tr("press «Release» after checking", lang)
	if b == "inhibit":
		return tr("Servos stopped", lang) + ": " + tr(SRV_FAULT_TEXT.get(SRV["inhibit"], SRV["inhibit"]), lang) + " - " + tr("moves again by itself", lang)
	return ""


SRV_FAULT_TEXT = {"i2c": "I2C errors - the servo driver does not answer", "pca_reset": "the PCA9685 lost its settings (brown-out or reset)",
				  "uv": "under-voltage of the power supply", "wd_cam": "the camera loop hangs (watchdog)",
				  "wd_loop": "the servo loop hung (watchdog)", "estop": "emergency stop", "release": "released",
				  "limit": "software limit reached", "temp": "high temperature of the Pi", "throttle": "the Pi slows down (throttled)",
				  "no_driver": "no servo driver found"}


def servo_park_target():
	""
	try:
		tp = teach_point_by_name(CFG.get("kopf_park_point") or "")
	except NameError:
		tp = None
	if tp:
		return srv_clamp(tp[0], tp[1])
	return srv_clamp(CFG.get("kopf_park_pan", 50.0), CFG.get("kopf_park_tilt", 5.0))


def servo_stop_point():
	""
	p = list(servo_pos())
	for i, ax in enumerate(SERVO_AXES):
		_vm, am = srv_axis_limits(ax)
		v = SRV["vel"][i]
		p[i] = p[i] + v * abs(v) / (2.0 * am)
	return srv_clamp(p[0], p[1]) or servo_pos()


def servo_goto(pan, tilt, who="", speed=None, wait=True, stop=None, timeout=60.0):
	"""

"""
	if servo_blocked():
		return False
	c = srv_clamp(pan, tilt)
	if c is None:
		return False
	pan, tilt = c
	CFG["pan"], CFG["tilt"] = float(pan), float(tilt)
	SRV["cap"] = (float(speed), (round(pan, 3), round(tilt, 3))) if speed else None
	if not wait:
		return True
	if SRV["pos"] is None or not SRV.get("started"):
		return True
	end = time.time() + timeout
	while time.time() < end:
		if servo_blocked():
			return False
		if abs(float(CFG["pan"]) - pan) > 0.01 or abs(float(CFG["tilt"]) - tilt) > 0.01:
			return False
		if stop is not None:
			try:
				if stop():
					sp = servo_stop_point()
					CFG["pan"], CFG["tilt"] = sp[0], sp[1]; SRV["cap"] = None
					return False
			except Exception:
				return False
		if servo_arrived():
			return True
		time.sleep(0.02)
	return False


def servo_wait(timeout=15.0, settle=0.0):
	""
	end = time.time() + timeout
	while time.time() < end and SRV.get("started") and not servo_arrived():
		if servo_blocked():
			return False
		time.sleep(0.03)
	if settle > 0:
		time.sleep(settle)
	return servo_arrived()



def servo_plan_tick(dt):
	""
	now = time.time()
	SRV["beat"] = time.monotonic(); SRV["started"] = True
	dt = max(0.001, min(0.1, float(dt)))
	if SRV["pos"] is None:
		SRV["pos"] = [float(CFG["pan"]), float(CFG["tilt"])]; SRV["tgt"] = list(SRV["pos"])
	if now - SRV["safety_t"] >= 0.25:
		SRV["safety_t"] = now
		try:
			servo_safety_tick(now)
		except Exception as e:
			log_event("servo", f"Servo safety check: {type(e).__name__}: {e}"[:160])
	pos, vel = SRV["pos"], SRV["vel"]
	if SRV["wd_trip"]:
		SRV["wd_trip"] = False; vel[0] = vel[1] = 0.0
		CFG["pan"], CFG["tilt"] = pos[0], pos[1]
	blocked = servo_blocked()
	estop = blocked == "estop"
	if blocked:

		park = None
		if estop and CFG.get("servo_estop_park") and SRV["parked"] is not True:
			park = servo_park_target()
		if park is not None and SRV["parked"] == "go":
			for i, ax in enumerate(SERVO_AXES):
				vm, am = srv_axis_limits(ax)
				pos[i], vel[i] = srv_axis_step(pos[i], vel[i], park[i], min(vm, 15.0 * _srv_k(ax)), am, dt)
			if pos[0] == park[0] and pos[1] == park[1] and vel[0] == 0.0 and vel[1] == 0.0:
				SRV["parked"] = True
				log_event("servo", "Emergency stop: parked - holding")
		else:
			for i, ax in enumerate(SERVO_AXES):
				_vm, am = srv_axis_limits(ax)
				a2 = am * (2.0 if estop else 1.0) * dt
				v = vel[i]; v2 = v - math.copysign(min(abs(v), a2), v)
				pos[i] += (v + v2) * 0.5 * dt; vel[i] = v2
			if park is not None and vel[0] == 0.0 and vel[1] == 0.0:
				SRV["parked"] = "go"
		c = srv_clamp(pos[0], pos[1])
		if c:
			pos[0], pos[1] = c
		CFG["pan"], CFG["tilt"] = round(pos[0], 3), round(pos[1], 3)
		SRV["cap"] = None; SRV["tgt"] = list(pos)
	else:
		SRV["parked"] = False
		tgt = [float(CFG["pan"]), float(CFG["tilt"])]
		lims = [srv_axis_limits(ax) for ax in SERVO_AXES]
		if SRV["tgt"] is None or abs(tgt[0] - SRV["tgt"][0]) > 1e-3 or abs(tgt[1] - SRV["tgt"][1]) > 1e-3:
			SRV["tgt"] = list(tgt)
			rest = abs(vel[0]) < 0.5 and abs(vel[1]) < 0.5
			SRV["scale"] = srv_sync_scale([tgt[0] - pos[0], tgt[1] - pos[1]], lims) if rest else [(1.0, 1.0), (1.0, 1.0)]
		cap = SRV["cap"]
		capv = None
		if cap and abs(cap[1][0] - tgt[0]) < 0.01 and abs(cap[1][1] - tgt[1]) < 0.01:
			capv = max(1.0, cap[0])
		elif cap:
			SRV["cap"] = None
		dist = math.hypot(tgt[0] - pos[0], tgt[1] - pos[1])
		for i, ax in enumerate(SERVO_AXES):
			vm, am = lims[i]
			kv, ka = SRV["scale"][i]
			vm, am = vm * kv, am * ka
			if capv is not None and dist > 1e-6:
				vm = min(vm, max(0.2, capv * abs(tgt[i] - pos[i]) / dist)) if abs(vel[i]) < vm else min(vm, capv)
			p0 = pos[i]
			pos[i], vel[i] = srv_axis_step(pos[i], vel[i], tgt[i], vm, am, dt)
			if not math.isfinite(pos[i]) or not math.isfinite(vel[i]):
				pos[i], vel[i] = p0, 0.0
	moving = abs(vel[0]) > 0.01 or abs(vel[1]) > 0.01
	if moving and not SRV["moving"]:
		SRV["start_t"] = now
		servo_diag_move_start()
	if SRV["moving"] and not moving:
		SRV["arrive_t"] = now
	SRV["moving"] = moving
	servo_diag_count(dt, vel)
	if moving or len(SRV["trace"]) == 0 or now - SRV["trace"][-1][0] > 1.0:
		hp, ht = servo_half("pan"), servo_half("tilt")
		SRV["trace"].append((round(now, 3), round((pos[0] - 50) / 50 * hp, 3), round((pos[1] - 50) / 50 * ht, 3)))
	return pos[0], pos[1]


def servo_speed_deg():
	""
	return SRV["vel"][0] / _srv_k("pan"), SRV["vel"][1] / _srv_k("tilt")


def servo_outputs_off():
	""
	return SRV["fault"] in SRV_FAULT_LOCK






def servo_driver_note(who, what=""):
	if isinstance(who, (tuple, list)) and len(who) == 2:
		key, label = str(who[0])[:24], str(who[1])[:60]
	else:
		key = label = str(who or "?")[:60]
		if key == "window":
			label = tr("Window") + " (" + tr("this computer") + ")"
	d = SRV.get("drv") or {}
	now = time.time()
	if d.get("key") != key or now - float(d.get("t", 0)) > 10.0:
		SRV["drv_n"] = int(SRV.get("drv_n", 0)) + 1
		if d.get("key") != key:
			log_event("servo", f"The head is steered by: {label}")
	SRV["drv"] = {"key": key, "label": label, "t": now, "what": str(what)[:20], "n": SRV.get("drv_n", 0)}


def servo_driver(lang=None):
	""
	d = SRV.get("drv") or {}
	now = time.time()
	if d and now - float(d.get("t", 0)) <= 10.0:
		return {"kind": "manual", "key": d["key"], "label": d["label"], "ago": round(now - d["t"], 1), "n": d.get("n", 0)}
	try:
		own = kopf_owner()
	except Exception:
		own = ""
	names = {"manual": "by hand / tool", "alarm": "alarm / follow", "walktest": "walk test", "glance": "quick look at the valuables",
			 "round": "round (patrol)", "park": "parking"}
	if STATE.get("tracking"):
		own = "alarm"
	return {"kind": "auto" if own else "idle", "key": "", "label": tr(names.get(own, ""), lang) if own else "", "ago": None,
			"n": d.get("n", 0) if d else 0}



def servo_estop(by="web"):
	""
	if isinstance(by, (tuple, list)) and len(by) == 2:
		servo_driver_note(by, "estop"); by = by[1]
	first = not CFG.get("servo_estop")
	CFG["servo_estop"] = True; CFG["servo_estop_by"] = str(by)[:60]
	SRV["estop_t"] = time.time(); SRV["cap"] = None
	try:
		MOVER.update(v=0.0, w=0.0, cmd_t=0.0)
		if MOVERCTL is not None:
			MOVERCTL.stop_now()
	except Exception:
		pass
	if first:
		log_event("servo", f"EMERGENCY STOP ({by}): all movement stopped - «Release» needed")
		servo_diag_fault("estop", "warn", f"Emergency stop ({by})")
		save_settings()
	return True


def servo_release(by="web"):
	""
	if isinstance(by, (tuple, list)) and len(by) == 2:
		servo_driver_note(by, "release"); by = by[1]
	if SRV["inhibit"] == "uv":
		if SRV["test_uv"] or SRV.get("sim_uv") or ((STATE.get("supply") or {}).get("uv_now") and not CFG.get("sim_on")):
			return False, "under-voltage is still there - check the power supply first"
		SRV["inhibit"] = ""; SRV["uv_last"] = 0.0
	was = servo_blocked()
	if not was:
		return True, ""
	p = servo_pos()
	CFG["pan"], CFG["tilt"] = p[0], p[1]
	SRV["vel"] = [0.0, 0.0]; SRV["tgt"] = list(p); SRV["cap"] = None
	fault = SRV["fault"]
	CFG["servo_estop"] = False; CFG["servo_estop_by"] = ""
	SRV.update(fault="", fault_t=0.0, io_err=0, parked=False)
	if fault in SRV_FAULT_LOCK:
		HW_REINIT["want"] = True
	MANUAL["until"] = time.time() + 3.0
	log_event("servo", f"Servos released ({by})" + (f" after: {SRV_FAULT_TEXT.get(fault, fault)}" if fault else ""))
	servo_diag_fault("release", "info", f"Released ({by})" + (f" - {fault}" if fault else ""))
	save_settings()
	return True, ""


def servo_fault(code, text=""):
	""
	if SRV["fault"] == code:
		return
	SRV["fault"] = code; SRV["fault_t"] = time.time(); SRV["cap"] = None
	log_event("servo", f"SERVO FAULT: {SRV_FAULT_TEXT.get(code, code)}" + (f" - {text}" if text else "") + " - stopped, «Release» needed")
	servo_diag_fault(code, "error", text or SRV_FAULT_TEXT.get(code, code))
	_servo_push_once(tr("Servo fault") + ": " + tr(SRV_FAULT_TEXT.get(code, code)))


def _servo_push_once(text):
	""
	if time.time() - SRV["push_t"] < 3600:
		return
	SRV["push_t"] = time.time()
	w = WATCH_REF.get("w") if "WATCH_REF" in globals() else None
	if w is not None and not CFG.get("sim_on"):
		try:
			w.notifier.info(text, title="{name}: " + tr("Servos"))
		except Exception:
			pass


def servo_io_error(e):
	""
	now = time.time()
	SRV["io_err"] = SRV["io_err"] + 1 if now - SRV["io_t"] < 3.0 else 1
	SRV["io_t"] = now
	servo_diag_fault("i2c", "warn", f"{type(e).__name__}: {e}"[:120])
	if SRV["io_err"] >= 3:
		servo_fault("i2c", f"{type(e).__name__}: {e}"[:120])


def servo_io_ok():
	SRV["io_err"] = 0


def _servo_inhibit(code, on, now):
	if on and SRV["inhibit"] != code and not SRV["inhibit"]:
		SRV["inhibit"] = code; SRV["inhibit_t"] = now
		if now - SRV["inhibit_log"].get(code, 0.0) > 300:
			SRV["inhibit_log"][code] = now
			log_event("servo", f"Servos stopped: {SRV_FAULT_TEXT.get(code, code)} - they move again by themselves")
			servo_diag_fault(code, "warn", SRV_FAULT_TEXT.get(code, code))
			if code == "uv":
				_servo_push_once(tr("Servos stopped") + ": " + tr(SRV_FAULT_TEXT["uv"]))
	elif not on and SRV["inhibit"] == code:
		SRV["inhibit"] = ""
		log_event("servo", f"Servos may move again ({SRV_FAULT_TEXT.get(code, code)} is over)")


def servo_safety_tick(now):
	""
	sup = STATE.get("supply") or {}
	uv = (bool(sup.get("uv_now")) and not CFG.get("sim_on")) or SRV["test_uv"] or bool(SRV.get("sim_uv") and CFG.get("sim_on"))
	if uv:
		SRV["uv_last"] = now
	if CFG.get("servo_uv_stop", True):
		_servo_inhibit("uv", uv or (SRV["inhibit"] == "uv" and now - SRV.get("uv_last", 0.0) < 30.0), now)
	elif SRV["inhibit"] == "uv":
		_servo_inhibit("uv", False, now)

	wd = max(3.0, float(CFG.get("servo_wd_s") or 10.0))
	hb = now - float(HEART.get("t", now)) if "HEART" in globals() else 0.0
	idle = PAUSING.get("on") or toolmode_on() if "PAUSING" in globals() else True
	hang = hb > wd and not idle and now - START > 60 and WATCH_REF.get("w") is not None
	if SRV["inhibit"] in ("", "wd_cam"):
		_servo_inhibit("wd_cam", hang, now)
	t = STATE.get("cpu_temp")
	if isinstance(t, (int, float)) and t >= 82.0 and now - SRV.get("temp_t", 0.0) > 600:
		SRV["temp_t"] = now
		servo_diag_fault("temp", "warn", f"{t:.0f} °C")
	if sup.get("throttled") and now - SRV.get("thr_t", 0.0) > 600:
		SRV["thr_t"] = now
		servo_diag_fault("throttle", "warn", "vcgencmd get_throttled")
	if uv and now - SRV.get("uvd_t", 0.0) > 60:
		SRV["uvd_t"] = now
		servo_diag_count_uv()


def servo_limit_note(axis_i, hit):
	""
	if hit and not SRV["limit_on"][axis_i]:
		servo_diag_fault("limit", "info", ("pan" if axis_i == 0 else "tilt") + " " + tr("limit"))
	SRV["limit_on"][axis_i] = hit


def _servo_watchdog():
	""
	while True:
		time.sleep(0.25)
		try:
			b = SRV["beat"]
			if b and time.monotonic() - b > 1.5 and not SRV["wd_trip"]:
				SRV["wd_trip"] = True
				if time.time() - SRV["wd_log"] > 300:
					SRV["wd_log"] = time.time()
					log_event("servo", "Watchdog: the servo loop hung - the move is not continued")
					servo_diag_fault("wd_loop", "warn", f"{time.monotonic() - b:.1f} s")
		except Exception:
			pass


def servo_watchdog_start():
	if not SRV.get("wd_started"):
		SRV["wd_started"] = True
		threading.Thread(target=_servo_watchdog, daemon=True, name="servo-wd").start()


def servo_state(lang=None):
	""
	p, t = servo_pos()
	pd, td = servo_pos_deg()
	vp, vt = servo_speed_deg()
	(plo, phi), (tlo, thi) = srv_limits_pct()
	return {"pos": [round(p, 2), round(t, 2)], "deg": [round(pd, 1), round(td, 1)], "dps": [round(vp, 1), round(vt, 1)],
			"target": [round(float(CFG["pan"]), 2), round(float(CFG["tilt"]), 2)], "moving": SRV["moving"],
			"blocked": servo_blocked(), "text": servo_blocked_text(lang), "estop": bool(CFG.get("servo_estop")),
			"estop_by": CFG.get("servo_estop_by") or "", "fault": SRV["fault"], "inhibit": SRV["inhibit"],

			"stop_btn": bool(CFG.get("servo_stop_btn", True)) and bool(globals().get("live_has_head", lambda: True)()),
			"limits": [[round(plo, 1), round(phi, 1)], [round(tlo, 1), round(thi, 1)]],
			"limits_deg": [float(CFG["pan_limit"]), float(CFG["tilt_limit"])],
			"vmax": [float(CFG["servo_vmax_pan"]), float(CFG["servo_vmax_tilt"])], "acc": [float(CFG["servo_acc_pan"]), float(CFG["servo_acc_tilt"])],
			"backend": str(STATE.get("servo_backend") or ""), "driver": servo_driver(lang),
			"backend_note": tr(SERVO_GPIO_FALLBACK_TEXT, lang) if servo_gpio_fallback() else ""}


servo_planner_selftest = _zd_fn('072_servo_planer/servo_planner_selftest()')
















































for _k, _v in {"servo_service_h": 100.0}.items():
	CFG.setdefault(_k, _v)
	DEFAULTS.setdefault(_k, _v)
SVD = {"d": None, "dirty": False, "saved_t": 0.0, "fault_save_t": 0.0, "lock": threading.Lock(), "atexit": False}
SVD_SAVE_S = 900
SVD_MAX_FAULTS = 300
SVD_LEVELS = ("info", "warn", "error")


def _svd_file():
	return os.path.join(DATA_DIR, "servo_diag.json")


def _svd_axis():
	return {"deg": 0.0, "move_s": 0.0, "moves": 0}


def _svd_bucket():
	return {"on_s": 0.0, "uv_min": 0, "pan": _svd_axis(), "tilt": _svd_axis()}


def _svd_blank():
	return {"v": 1, "since": time.time(), "hw": _svd_bucket(), "sim": _svd_bucket(),
			"service": {"pan": 0.0, "tilt": 0.0, "t": 0.0}, "faults": []}


def servo_diag_data():
	if SVD["d"] is None:
		d = None
		try:
			with open(_svd_file()) as f:
				d = json.load(f)
		except (OSError, ValueError):
			d = None
		b = _svd_blank()
		if isinstance(d, dict):
			for k in ("hw", "sim"):
				if isinstance(d.get(k), dict):
					for kk in ("on_s", "uv_min"):
						if isinstance(d[k].get(kk), (int, float)):
							b[k][kk] = d[k][kk]
					for ax in SERVO_AXES:
						if isinstance(d[k].get(ax), dict):
							for kk in ("deg", "move_s", "moves"):
								if isinstance(d[k][ax].get(kk), (int, float)):
									b[k][ax][kk] = d[k][ax][kk]
			if isinstance(d.get("service"), dict):
				b["service"].update({k: float(v) for k, v in d["service"].items() if k in ("pan", "tilt", "t") and isinstance(v, (int, float))})
			if isinstance(d.get("since"), (int, float)):
				b["since"] = d["since"]
			b["faults"] = [x for x in (d.get("faults") or []) if isinstance(x, dict) and x.get("code")][-SVD_MAX_FAULTS:]
		SVD["d"] = b
		if not SVD["atexit"]:
			SVD["atexit"] = True
			atexit.register(lambda: servo_diag_save(True))
	return SVD["d"]


def servo_diag_save(force=False):
	d = SVD["d"]
	if d is None or not (SVD["dirty"] or force):
		return
	try:
		with SVD["lock"]:
			tmp = _svd_file() + ".tmp"
			with open(tmp, "w") as f:
				json.dump(d, f)
			os.replace(tmp, _svd_file())
		SVD["dirty"] = False; SVD["saved_t"] = time.time()
	except OSError:
		pass


def _svd_cur():
	sim = bool(CFG.get("sim_on")) or str(STATE.get("servo_backend") or "simulation").startswith("simulation")
	return servo_diag_data()["sim" if sim else "hw"]


def servo_diag_count(dt, vel):
	""
	b = _svd_cur()
	if not servo_outputs_off():
		b["on_s"] += dt
	for i, ax in enumerate(SERVO_AXES):
		v = abs(vel[i])
		if v > 0.01:
			b[ax]["deg"] += v * dt / _srv_k(ax)
			b[ax]["move_s"] += dt
	SVD["dirty"] = True
	if time.time() - SVD["saved_t"] > SVD_SAVE_S:
		SVD["saved_t"] = time.time()
		threading.Thread(target=servo_diag_save, daemon=True, name="servodiag-save").start()


def servo_diag_move_start():
	b = _svd_cur()
	for i, ax in enumerate(SERVO_AXES):
		if abs(SRV["vel"][i]) > 0.01:
			b[ax]["moves"] += 1


def servo_diag_count_uv():
	_svd_cur()["uv_min"] += 1


def servo_diag_fault(code, level="warn", text=""):
	""
	d = servo_diag_data()
	now = time.time()
	level = level if level in SVD_LEVELS else "warn"
	text = str(text or "")[:160]
	with SVD["lock"]:
		for f in reversed(d["faults"][-20:]):
			if f.get("code") == code and f.get("text") == text and now - float(f.get("last", 0)) < 600:
				f["n"] = int(f.get("n", 1)) + 1; f["last"] = round(now, 1)
				break
		else:
			d["faults"].append({"t": round(now, 1), "last": round(now, 1), "code": code, "level": level, "text": text, "n": 1,
								"sim": bool(CFG.get("sim_on"))})
			del d["faults"][:-SVD_MAX_FAULTS]
	SVD["dirty"] = True
	if level == "error" and now - SVD["fault_save_t"] > 60:
		SVD["fault_save_t"] = now
		threading.Thread(target=servo_diag_save, daemon=True, name="servodiag-save").start()


def servo_diag_clear_faults(by="web"):
	d = servo_diag_data()
	with SVD["lock"]:
		d["faults"] = []
	SVD["dirty"] = True; servo_diag_save(True)
	log_event("servo", f"Servo fault memory cleared ({by})")


def servo_diag_service_done(axis="", by="web"):
	""
	d = servo_diag_data()
	for ax in SERVO_AXES:
		if axis in ("", ax):
			d["service"][ax] = d["hw"][ax]["move_s"]
	d["service"]["t"] = time.time()
	SVD["dirty"] = True; servo_diag_save(True)
	log_event("servo", f"Servo maintenance done ({axis or 'both axes'}, {by})")
	servo_diag_fault("service", "info", f"maintenance done: {axis or 'pan + tilt'}")


def _h(s):
	return round(float(s) / 3600.0, 2)


def servo_diag_hints(lang=None):
	""
	d = servo_diag_data()
	out = []
	T = lambda x: tr(x, lang)
	lim = max(5.0, float(CFG.get("servo_service_h") or 100.0))
	for ax, name in (("pan", "Pan servo"), ("tilt", "Tilt servo")):
		h = _h(d["hw"][ax]["move_s"] - float(d["service"].get(ax) or 0.0))
		if h >= lim:
			out.append(("warn", trf("{axis} (MG90S): {h} h moved since the last check - check it now: play in the gears, noise, does it hold the position?", lang, axis=T(name), h=f"{h:.1f}")))
		elif h >= lim * 0.8:
			out.append(("info", trf("{axis} (MG90S): {h} h moved - check after about {lim} h (play, noise).", lang, axis=T(name), h=f"{h:.1f}", lim=f"{lim:.0f}")))
	cnt = {}
	week = time.time() - 7 * 86400
	for f in d["faults"]:
		if float(f.get("last", 0)) >= week and not f.get("sim"):
			cnt[f["code"]] = cnt.get(f["code"], 0) + int(f.get("n", 1))
	if cnt.get("uv") or cnt.get("pca_reset") or d["hw"]["uv_min"] > 0 and cnt.get("uv"):
		out.append(("warn", T("Under-voltage / brown-out: give the servos their own 5 V supply (BEC, at least 2 A), put a 470–1000 µF capacitor at V+ of the PCA9685 and use a short, thick cable.")))
	if cnt.get("i2c"):
		out.append(("warn", T("I2C errors: check the 4 wires to the PCA9685 (short, firmly plugged), the address 0x41 and that I2C is on (raspi-config).")))
	if cnt.get("limit", 0) >= 20:
		out.append(("info", T("The head often runs into the software limit: widen the limit (Camera / Servos) or move the taught points a little inwards.")))
	if cnt.get("temp") or cnt.get("throttle"):
		out.append(("info", T("The Pi gets hot or slows down: shade, air holes in the housing, a heat sink.")))
	if cnt.get("wd_cam") or cnt.get("wd_loop"):
		out.append(("info", T("The watchdog stopped the servos: the computer was too busy - see the log; fewer AI pictures or the AI helper on the PC help.")))
	if d["hw"]["on_s"] < 60 and (d["sim"]["on_s"] > 0):
		out.append(("info", T("Only the simulation so far - the counters of the real servos start with the hardware.")))
	return out


def servo_diag_state(lang=None):
	d = servo_diag_data()
	lim = max(5.0, float(CFG.get("servo_service_h") or 100.0))

	def bucket(b, service=None):
		ax = {}
		for a in SERVO_AXES:
			x = b[a]
			ax[a] = {"deg": int(round(x["deg"])), "move_h": _h(x["move_s"]), "moves": int(x["moves"]),
					 "turns": round(x["deg"] / 360.0, 1)}
			if service is not None:
				ax[a]["service_h"] = _h(x["move_s"] - float(service.get(a) or 0.0))
				ax[a]["service_pct"] = int(min(100, round(ax[a]["service_h"] / lim * 100)))
		return {"on_h": _h(b["on_s"]), "uv_min": int(b["uv_min"]), "axes": ax}
	faults = []
	for f in reversed(d["faults"][-100:]):
		faults.append({"t": f["t"], "last": f.get("last", f["t"]), "code": f["code"], "level": f.get("level", "warn"), "n": int(f.get("n", 1)),
					   "what": tr(SRV_FAULT_TEXT.get(f["code"], f["code"]), lang), "text": f.get("text", ""), "sim": bool(f.get("sim"))})
	return {"since": d["since"], "hw": bucket(d["hw"], d["service"]), "sim": bucket(d["sim"]), "service_t": d["service"].get("t") or 0,
			"service_h": lim, "faults": faults, "n_faults": len(d["faults"]),
			"hints": [{"level": l, "text": t} for l, t in servo_diag_hints(lang)]}


def servo_diag_export(fmt="json", lang=None):
	""
	stamp = datetime.now().strftime("%Y%m%d_%H%M")
	st = {"app": "MoveEye", "version": APP_VERSION, "device": CFG.get("device_name") or "MoveEye", "t": datetime.now().isoformat(timespec="seconds"),
		  "servo": servo_state(lang), "diag": servo_diag_state(lang), "points": teach_list(lang),
		  "settings": {k: CFG.get(k) for k in ("servo_driver", "pca_address", "pca_pan_ch", "pca_tilt_ch", "servo_min_us", "servo_max_us",
											   "servo_range", "pan_servo_range", "servo_kind", "pan_limit", "tilt_limit", "invert_pan", "invert_tilt",
											   "servo_vmax_pan", "servo_vmax_tilt", "servo_acc_pan", "servo_acc_tilt", "servo_estop_park",
											   "servo_uv_stop", "servo_wd_s", "servo_service_h")}}
	if fmt == "csv":
		lines = ["time;last;code;level;count;sim;what;text"]
		for f in st["diag"]["faults"]:
			ts = lambda x: datetime.fromtimestamp(float(x)).strftime("%Y-%m-%d %H:%M:%S")
			lines.append(";".join([ts(f["t"]), ts(f["last"]), f["code"], f["level"], str(f["n"]), "1" if f["sim"] else "0",
								   f["what"].replace(";", ","), str(f["text"]).replace(";", ",")]))
		lines.append("")
		for k in ("hw", "sim"):
			b = st["diag"][k]
			lines.append(f"{k};on_h;{b['on_h']};uv_min;{b['uv_min']}")
			for a in SERVO_AXES:
				x = b["axes"][a]
				lines.append(f"{k};{a};deg;{x['deg']};move_h;{x['move_h']};moves;{x['moves']}")
		return ("\n".join(lines) + "\n").encode("utf-8-sig"), "text/csv", f"moveeye_servo_{stamp}.csv"
	return json.dumps(st, ensure_ascii=False, indent=1).encode("utf-8"), "application/json", f"moveeye_servo_{stamp}.json"


servo_diag_selftest = _zd_fn('074_servo_diagnose/servo_diag_selftest()')



























for _k, _v in {"kopf_park_point": "", "kopf_home_point": ""}.items():
	CFG.setdefault(_k, _v)
	DEFAULTS.setdefault(_k, _v)
TEACH_MAX = 50


def wp_name(w):
	return str(w[2]) if isinstance(w, (list, tuple)) and len(w) >= 3 and w[2] else ""


def wp_patrol(w):
	""
	return not (isinstance(w, (list, tuple)) and len(w) >= 4 and not w[3])


def _wp_make(pan, tilt, name="", patrol=True):
	pan = round(max(0.0, min(100.0, float(pan))), 2); tilt = round(max(0.0, min(100.0, float(tilt))), 2)
	name = re.sub(r"[\x00-\x1f<>\"]", "", str(name or "")).strip()[:30]
	if not name and patrol:
		return [pan, tilt]
	return [pan, tilt, name] if patrol else [pan, tilt, name, 0]


def wp_clean(w):
	""
	if isinstance(w, (int, float)) and not isinstance(w, bool):
		return None
	if not isinstance(w, (list, tuple)) or not 2 <= len(w) <= 4:
		return None
	if not all(isinstance(x, (int, float)) and not isinstance(x, bool) and math.isfinite(float(x)) for x in w[:2]):
		return None
	name = w[2] if len(w) >= 3 and isinstance(w[2], str) else ""
	return _wp_make(w[0], w[1], name, not (len(w) >= 4 and not w[3]))


def teach_list(lang=None):
	hp, ht = servo_half("pan"), servo_half("tilt")
	out = []
	for i, w in enumerate(WAYPOINTS):
		out.append({"i": i, "name": wp_name(w), "pan": float(w[0]), "tilt": float(w[1]), "patrol": wp_patrol(w),
					"deg": [round((float(w[0]) - 50) / 50 * hp, 1), round((float(w[1]) - 50) / 50 * ht, 1)],
					"park": bool(wp_name(w)) and wp_name(w) == CFG.get("kopf_park_point"),
					"home": bool(wp_name(w)) and wp_name(w) == CFG.get("kopf_home_point")})
	return out


def teach_point_by_name(name):
	if not name:
		return None
	for w in WAYPOINTS:
		if wp_name(w) == name:
			return float(w[0]), float(w[1])
	return None


def _teach_i(i):
	try:
		i = int(i)
	except (TypeError, ValueError):
		return None
	return i if 0 <= i < len(WAYPOINTS) else None


def _teach_unique(name, skip=None):
	base = name; n = 2
	while any(wp_name(w) == name for j, w in enumerate(WAYPOINTS) if j != skip):
		name = f"{base} {n}"; n += 1
	return name


def teach_add(name="", who="web", pan=None, tilt=None, patrol=True):
	""
	if len(WAYPOINTS) >= TEACH_MAX:
		return False, "at most 50 points", None
	if pan is None or tilt is None:
		pan, tilt = servo_pos()
	w = _wp_make(pan, tilt, name, patrol)
	if len(w) >= 3 and w[2]:
		w[2] = _teach_unique(w[2])
	WAYPOINTS.append(w)
	save_settings()
	log_event("patrol", f"Point taught ({who}): «{wp_name(w) or len(WAYPOINTS)}» pan {w[0]:.1f} % / tilt {w[1]:.1f} %")
	return True, "", len(WAYPOINTS) - 1


def teach_edit(op, i, value=None, who="web"):
	""
	i = _teach_i(i)
	if i is None:
		return False, "no such point"
	w = list(WAYPOINTS[i])
	if op == "rename":
		nm = re.sub(r"[\x00-\x1f<>\"]", "", str(value or "")).strip()[:30]
		old = wp_name(w)
		nm = _teach_unique(nm, i) if nm else ""
		WAYPOINTS[i] = _wp_make(w[0], w[1], nm, wp_patrol(w))
		for k in ("kopf_park_point", "kopf_home_point"):
			if old and CFG.get(k) == old:
				CFG[k] = nm
	elif op == "delete":
		nm = wp_name(w)
		WAYPOINTS.pop(i)
		for k in ("kopf_park_point", "kopf_home_point"):
			if nm and CFG.get(k) == nm:
				CFG[k] = ""
	elif op in ("up", "down"):
		j = i - 1 if op == "up" else i + 1
		if not 0 <= j < len(WAYPOINTS):
			return False, "already at the end"
		WAYPOINTS[i], WAYPOINTS[j] = WAYPOINTS[j], WAYPOINTS[i]
	elif op == "patrol":
		WAYPOINTS[i] = _wp_make(w[0], w[1], wp_name(w) or (tr("Point") + f" {i + 1}" if not value else ""), bool(value))
	elif op == "update":
		p, t = servo_pos()
		WAYPOINTS[i] = _wp_make(p, t, wp_name(w), wp_patrol(w))
	elif op in ("park", "home"):
		k = "kopf_park_point" if op == "park" else "kopf_home_point"
		nm = wp_name(w)
		if not nm:
			nm = _teach_unique(tr("Parking position") if op == "park" else tr("Home position"))
			WAYPOINTS[i] = _wp_make(w[0], w[1], nm, wp_patrol(w))
		CFG[k] = "" if CFG.get(k) == nm and value is not True else nm
	else:
		return False, "unknown"
	save_settings()
	log_event("patrol", f"Taught point {op} ({who}): «{wp_name(w) or i + 1}»")
	return True, ""


def teach_goto(i, who="web", wait=False):
	""
	i = _teach_i(i)
	if i is None:
		return False, "no such point"
	if servo_blocked():
		return False, servo_blocked_text() or "stopped"
	w = WAYPOINTS[i]
	MANUAL["until"] = time.time() + max(10.0, float(CFG.get("manual_hold") or 10))
	servo_driver_note(who, "goto")
	ok = servo_goto(float(w[0]), float(w[1]), "teach", wait=wait)
	log_event("servo", f"To the taught point «{wp_name(w) or i + 1}» (pan {float(w[0]):.1f} % / tilt {float(w[1]):.1f} %)")
	return ok, "" if ok else "interrupted"


def teach_from_place(who="web"):
	""
	try:
		items = kopf_items()
	except Exception:
		items = []
	n = 0
	for it in items:
		if it["kind"] == "ignore" or len(WAYPOINTS) >= TEACH_MAX:
			continue
		nm = str(it.get("name") or "")[:30]
		if any(wp_name(w) == nm for w in WAYPOINTS):
			continue
		p, t = round(float(it["pan"]), 1), round(float(it["tilt"]), 1)
		same = next((j for j, w in enumerate(WAYPOINTS) if abs(float(w[0]) - p) < 0.15 and abs(float(w[1]) - t) < 0.15), None)
		if same is not None:
			if not wp_name(WAYPOINTS[same]):
				WAYPOINTS[same] = _wp_make(p, t, nm, wp_patrol(WAYPOINTS[same])); n += 1
			continue
		WAYPOINTS.append(_wp_make(p, t, nm, it["kind"] in ("tent", "access", "public_path"))); n += 1
	if n:
		save_settings()
		log_event("patrol", f"{n} points taken over from «Platz einrichten» ({who})")
	return n


def teach_choice_pairs():
	return [("", "– " + tr("none") + " –")] + [(wp_name(w), wp_name(w)) for w in WAYPOINTS if wp_name(w)]


