	k = dict(CFG.get("net_known") or {})
	if name is None:
		k.pop(mac, None)
	else:
		k[mac] = str(name)[:40] or "?"
	CFG["net_known"] = k; save_settings()
	for d_ in TOOLS["net"]["devices"]:
		if d_["mac"] == mac:
			d_["known"] = k.get(mac); d_["new"] = False
	return True


