def sim_latest_check(force=False):
	"""
"""
	if SIMLATEST["busy"] or (not force and time.time() - SIMLATEST["t"] < 3600):
		return
	SIMLATEST["busy"] = True; SIMLATEST["t"] = time.time()

	def work():
		try:
			src = CFG["update_url"].strip()
			base = src.rsplit("/", 1)[0] + "/" if src.startswith("https://") else SIM3D_BASE
			for key, path in (("3d", "simulator3d/version.json"), ("py", "simulator_python/MotionWatchSimulator.json")):
				try:
					with urllib.request.urlopen(_upd_request(base + path), timeout=15) as r:
						d = json.loads(r.read(65536))

					SIMLATEST[key] = {"version": str(d.get("ver") or d.get("version") or "")[:20], "notes": str(d.get("notes") or "")[:400]}
					ah = d.get("anhang") if key == "3d" and isinstance(d.get("anhang"), dict) else None
					if ah and VER_RE.match(str(ah.get("ver") or "")) and (sim_vkey(ah["ver"]) or (0,)) > (sim_vkey(SIMLATEST[key]["version"]) or (0,)):
						SIMLATEST[key] = {"version": str(ah["ver"]), "notes": str(ah.get("notes") or "")[:400]}
					SIMLATEST["err"] = ""
				except Exception as e:
					SIMLATEST["err"] = _upd_error(e)[:120] if "_upd_error" in globals() else str(e)[:120]
		finally:
			SIMLATEST["busy"] = False
	threading.Thread(target=work, daemon=True, name="simlatest").start()


SIM_LEGACY_SHIFT = 2


def sim_vkey(v):
	"""
"""
	s = str(v or "")
	m = re.search(r"3D-(\d+)\.(\d+)(?:\.(\d+))?", s)
	if m:
		return (int(m.group(1)) - SIM_LEGACY_SHIFT, int(m.group(2)), int(m.group(3) or 0))
	m = re.search(r"(\d+)\.(\d+)(?:\.(\d+))?", s)
	return tuple(int(x or 0) for x in m.groups()) if m else None


def sim_vlegacy(v):
	""
	s = str(v or "").strip()
	if "3D-" in s or not re.match(r"^\d+\.\d+\.\d+$", s):
		return s
	a, b, c = (int(x) for x in s.split("."))
	return "3D-%d.%d.%d" % (a + SIM_LEGACY_SHIFT, b, c)


def sim_vlabel(v):
	""
	s = str(v or "").strip()
	return ("MoveEye Sim · 3D " if "3D-" in s else "MoveEye Sim ") + s




