_TESTOPT_LOCK = threading.Lock()


def _clean_report(rep):
	""
	if not isinstance(rep, dict):
		return {}
	def n(x, hi=1000000):
		try:
			v = float(x)
		except (TypeError, ValueError):
			return 0
		return int(max(0, min(hi, v))) if math.isfinite(v) else 0
	out = dict(rep); ph = []
	for p in (rep.get("phases") if isinstance(rep.get("phases"), list) else [])[:60]:
		if not isinstance(p, dict):
			continue
		q = dict(p)
		for k in ("persons", "persons_detected", "false_alarms", "animals_as_person"):
			q[k] = n(p.get(k, 0))
		q["persons_detected"] = min(q["persons_detected"], q["persons"])
		q["name"] = str(p.get("name", ""))[:80]; q["dark"] = bool(p.get("dark"))
		mw_ = p.get("missed_why") if isinstance(p.get("missed_why"), dict) else {}
		q["missed_why"] = {str(k)[:20]: n(v) for k, v in list(mw_.items())[:20]}
		ph.append(q)
	out["phases"] = ph
	for k in ("persons", "persons_detected", "false_alarms"):
		out[k] = n(rep.get(k, 0))
	try:
		r_ = float(rep.get("rate") or 0); out["rate"] = max(0.0, min(100.0, r_)) if math.isfinite(r_) else 0.0
	except (TypeError, ValueError):
		out["rate"] = 0.0
	try:
		l_ = rep.get("latency_s"); out["latency_s"] = max(0.0, min(600.0, float(l_))) if l_ is not None and math.isfinite(float(l_)) else None
	except (TypeError, ValueError):
		out["latency_s"] = None
	for k in ("false_list", "missed_list"):
		out[k] = [x for x in (rep.get(k) if isinstance(rep.get(k), list) else []) if isinstance(x, dict)][:500]
	return out


def _opt_trial_file():
	return os.path.join(DATA_DIR, "opt_trial.json")


def _opt_trial_mark(cfg):
	""
	try:
		with open(_opt_trial_file(), "w") as f:
			json.dump({"cfg": cfg, "t": time.time(), "sim": bool(CFG.get("sim_on"))}, f)
	except OSError:
		pass


def _opt_trial_end():
	try:
		os.remove(_opt_trial_file())
	except OSError:
		pass


def testopt_recover():
	""
	try:
		with open(_opt_trial_file()) as f:
			d = json.load(f)
	except (OSError, ValueError):
		return
	if isinstance(d, dict) and isinstance(d.get("cfg"), dict):
		if bool(d.get("sim", False)) != bool(CFG.get("sim_on")):
			log_event("sys", "Automatic optimization was interrupted (restart) - other profile, nothing restored")
			_opt_trial_end()
			return
		opt_restore(d["cfg"], "automatic optimization was interrupted")
		log_event("sys", "Automatic optimization was interrupted (restart) - the settings from before the trial are back")
	_opt_trial_end()


def testopt_load():
	try:
		with open(os.path.join(DATA_DIR, "testruns.json")) as f:
			d = json.load(f)
		TESTOPT["runs"] = [r for r in d.get("runs", []) if isinstance(r, dict)][-30:]
		TESTOPT["undo"] = d.get("undo") if isinstance(d.get("undo"), dict) else None
		if TESTOPT["runs"]:
			TESTOPT["sugg"] = opt_suggest(_clean_report(TESTOPT["runs"][-1].get("report") or {}))
	except Exception:
		pass
	try:
		testopt_recover()
	except Exception:
		pass


def testopt_save():
	try:
		keep = {str(int(r["t"])) for r in TESTOPT["runs"][-30:]}
		if os.path.isdir(_testopt_dir()):
			for n_ in os.listdir(_testopt_dir()):
				if n_.isdigit() and n_ not in keep:
					shutil.rmtree(os.path.join(_testopt_dir(), n_), ignore_errors=True)
	except OSError:
		pass
	try:
		dst = os.path.join(DATA_DIR, "testruns.json"); tmp = dst + ".tmp"
		with open(tmp, "w") as f:
			json.dump({"runs": TESTOPT["runs"][-30:], "undo": TESTOPT["undo"]}, f)
		os.replace(tmp, dst)
	except OSError:
		pass


def opt_snapshot():
	return {k: CFG[k] for k in OPT_KEYS if k in CFG}


def opt_score(rep):
	"""
"""
	if not rep or not rep.get("persons"):
		return None
	lat = float(rep.get("latency_s") if rep.get("latency_s") is not None else -1)
	asp = sum(int(p.get("animals_as_person", 0)) for p in rep.get("phases", []))
	sc = float(rep.get("rate", 0)) - 12.0 * int(rep.get("false_alarms", 0)) - 4.0 * max(0.0, lat - 1.5) - 4.0 * asp
	return round(sc, 1)


def _clampv(k, v):
	sp = web_specs().get(k) or {}
	if sp.get("type") == "bool":
		return bool(v)
	v = max(sp.get("min", v), min(sp.get("max", v), v))
	st = sp.get("step") or 1
	v = round(round(v / st) * st, 2)
	return int(round(v)) if isinstance(CFG.get(k), int) and not isinstance(CFG.get(k), bool) else float(v)


def opt_suggest(rep):
	"""
"""
	if not rep or not rep.get("phases"):
		return []
	C = CFG; out = []
	def add(id_, title, why, changes, prio, n=0):
		ch = []
		for k, v in changes:
			if k not in C:
				continue
			nv = _clampv(k, v)
			if nv != C[k]:
				ch.append([k, C[k], nv])
		if ch:
			out.append({"id": id_, "title": title, "why": why, "n": n, "changes": ch, "prio": prio})
	causes = {}
	for f in rep.get("false_list", []):
		c = str(f.get("cause", ""))
		key = ("animal" if c.startswith("Tier") else {"Insekten am Licht": "insects", "Wind (Bäume, Büsche)": "wind", "Regen": "rain",
			   "Spinnennetz": "web", "Gegenlicht": "glare", "Scheinwerfer": "headlights", "Tropfen auf der Linse": "drops",
			   "Wolkenschatten": "shadows", "Schnee": "snow", "Nebel": "fog"}.get(c, "other"))
		causes[key] = causes.get(key, 0) + 1
	fa = int(rep.get("false_alarms", 0))
	ph = rep.get("phases", [])
	miss_day = sum(p["persons"] - p["persons_detected"] for p in ph if not p.get("dark"))
	miss_night = sum(p["persons"] - p["persons_detected"] for p in ph if p.get("dark"))
	why = {k: sum(int((p.get("missed_why") or {}).get(k, 0)) for p in ph) for k in ("dark", "small", "fast", "crouch")}
	asp = sum(int(p.get("animals_as_person", 0)) for p in ph)
	lat = float(rep.get("latency_s") if rep.get("latency_s") is not None else -1)
	tune_off = []

	if causes.get("wind", 0) + causes.get("shadows", 0):
		n = causes.get("wind", 0) + causes.get("shadows", 0)
		add("wind", "Calm down wind and cloud shadows",
			"{n} false alarms from moving branches or cloud shadows: the wind filter reacts earlier and moving areas must be bigger.",
			[("wind_auto", True), ("wind_threshold", C["wind_threshold"] - 0.1), ("wind_boost_max", C["wind_boost_max"] + 1.5),
			 ("min_area", C["min_area"] * 1.25)] + tune_off, 30 + 8 * n, n)
	if causes.get("insects", 0) + causes.get("web", 0):
		n = causes.get("insects", 0) + causes.get("web", 0)
		add("insects", "AI confirms every person",
			"{n} false alarms from insects or a spider web in the light: a person only counts when the AI sees it.",
			[("ai_require", True), ("ai_conf", max(C["ai_conf"], 0.55))], 35 + 8 * n, n)
	if causes.get("rain", 0) + causes.get("drops", 0) + causes.get("snow", 0):
		n = causes.get("rain", 0) + causes.get("drops", 0) + causes.get("snow", 0)
		add("rain", "Stronger rain and snow filter",
			"{n} false alarms from rain, snow or drops on the lens: the rain filter switches on earlier.",
			[("rain_auto", True), ("rain_threshold", C["rain_threshold"] - 0.1), ("min_area", C["min_area"] * 1.15)] + tune_off, 28 + 8 * n, n)
	if causes.get("glare", 0) + causes.get("headlights", 0) + causes.get("fog", 0):
		n = causes.get("glare", 0) + causes.get("headlights", 0) + causes.get("fog", 0)
		add("light", "Ignore changes of the light",
			"{n} false alarms from low sun, headlights or fog: the shadow filter and the AI check what moves.",
			[("shadow_filter", True), ("ai_require", True), ("car_filter", True), ("sensitivity", C["sensitivity"] - 8)] + tune_off, 26 + 8 * n, n)
	if causes.get("animal", 0) or asp:
		n = causes.get("animal", 0) + asp
		add("animals", "Do not take animals for persons",
			"{n} times an animal was reported as a person: the AI must be surer and small moving things count less.",
			[("ai_require", True), ("ai_conf", C["ai_conf"] + 0.1), ("min_area", C["min_area"] * 1.2)] + tune_off, 30 + 8 * n, n)
	if causes.get("other", 0) >= 2:
		n = causes.get("other", 0)
		add("calm", "Less sensitive",
			"{n} false alarms without a clear cause: a bit less sensitive.",
			[("sensitivity", C["sensitivity"] - 10), ("ai_conf", C["ai_conf"] + 0.05)] + tune_off, 18 + 5 * n, n)

	if miss_night and why["dark"]:
		add("night", "See better in the dark",
			"{n} persons were missed at night: brighten the picture earlier and let the AI accept less sure persons.",
			[("lowlight_auto", True), ("lowlight_threshold", C["lowlight_threshold"] + 20), ("ai_conf", C["ai_conf"] - 0.1),
			 ("ai_require", False if not causes.get("insects") else C["ai_require"])], 40 + 10 * miss_night, miss_night)
	if why["small"] or why["crouch"]:
		n = why["small"] + why["crouch"]
		add("small", "Find small and crouching persons",
			"{n} persons were far away, small or crouching and were missed: smaller moving areas count too.",
			[("min_area", C["min_area"] * 0.7), ("sensitivity", C["sensitivity"] + 8), ("ai_conf", C["ai_conf"] - 0.05)] + tune_off, 38 + 10 * n, n)
	if why["fast"]:
		add("fast", "Catch fast persons",
			"{n} fast persons (joggers) were missed: fewer pictures needed to recognise walking, the AI looks at every picture.",
			[("walk_frames", C["walk_frames"] - 2), ("ai_every", 1), ("speed_consistency", C["speed_consistency"] - 0.05)] + tune_off,
			32 + 10 * why["fast"], why["fast"])
	unexplained = miss_day - min(miss_day, why["small"] + why["crouch"] + why["fast"])
	if unexplained > 0:
		miss_day = unexplained
		add("day", "More sensitive by day",
			"{n} persons were missed by day: more sensitive and the AI accepts less sure persons.",
			[("sensitivity", C["sensitivity"] + 10), ("ai_conf", C["ai_conf"] - 0.1)] + tune_off, 36 + 10 * miss_day, miss_day)

	if lat > 2.0:
		add("speed", "React faster",
			"MoveEye needed {n} s on average: the AI looks at every picture and walking is recognised sooner.",
			[("ai_every", 1), ("walk_frames", C["walk_frames"] - 1)], 20 + int(6 * (lat - 2.0)), round(lat, 1))

	ids = {x["id"] for x in out}
	if ids & {"night", "small", "day"} and ids & {"wind", "calm", "animals"}:
		for x in out:
			x["conflict"] = True
	return sorted(out, key=lambda x: -x["prio"])


def opt_apply(changes, why="test run"):
	""
	before = opt_snapshot()
	for k, _old, new in changes:
		if k in CFG:
			CFG[k] = _clampv(k, new); sched_user_changed(k)
	if CFG.get("sim_on"):
		so = dict(CFG.get("simprof_opt") or {})
		for k, _old, _new in changes:
			if k in CFG:
				so[k] = CFG[k]
		CFG["simprof_opt"] = so
	save_settings()
	log_event("sys", "Optimization (" + why + "): " + ", ".join(f"{k} {o} -> {CFG[k]}" for k, o, _n in changes))
	return before


def opt_restore(snap, why="undo"):
	for k, v in (snap or {}).items():
		if k == "auto_tune":
			continue
		if k in CFG and isinstance(v, type(CFG[k])) or (k in CFG and isinstance(CFG[k], float) and isinstance(v, int)):
			CFG[k] = v; sched_user_changed(k)
	save_settings()
	log_event("sys", f"Optimization: settings restored ({why})")


def _simtest(action, **kw):
	try:
		r = sim_control(dict(action=action, **kw))
		return r if isinstance(r, dict) else {}
	except Exception as e:
		return {"ok": False, "error": str(e)[:120]}


def _testopt_dir(run_id=None):
	d = os.path.join(DATA_DIR, "testruns")
	return os.path.join(d, str(int(run_id))) if run_id is not None else d


def _testopt_frames(stop, frames, t0):
	""
	while not stop.is_set():
		w = WATCH_REF.get("w")
		f = getattr(w, "frame_out", None) if w is not None else None
		if f is not None:
			try:
				h, wd = f.shape[:2]; sc = 360.0 / max(1, wd)
				ok, buf = cv2.imencode(".jpg", cv2.resize(f, (360, int(h * sc))), [cv2.IMWRITE_JPEG_QUALITY, 62])
				if ok:
					frames.append((time.time() - t0, buf.tobytes()))
			except Exception:
				pass
		stop.wait(1.5)


def _testopt_pics(run, frames):
	""
	rep_ = run["report"]; out = []
	want = [("false", f) for f in rep_.get("false_list", [])] + [("missed", m) for m in rep_.get("missed_list", [])]
	if not want or not frames:
		return out
	d = _testopt_dir(run["t"]); os.makedirs(d, exist_ok=True)
	for i, (kind, e) in enumerate(want[:24]):
		t = float(e.get("t", 0))
		best = min(frames, key=lambda x: abs(x[0] - t))
		if abs(best[0] - t) > 6:
			continue
		name = f"{kind[0]}{i:02d}.jpg"
		try:
			with open(os.path.join(d, name), "wb") as f_:
				f_.write(best[1])
		except OSError:
			continue
		ph = rep_.get("phases", [])
		pn = ph[int(e.get("phase", 0))]["name"] if 0 <= int(e.get("phase", 0)) < len(ph) else ""
		out.append({"kind": kind, "t": round(t, 1), "phase": pn, "why": e.get("cause") if kind == "false" else ", ".join(e.get("why") or []) or "?",
					"what": e.get("kind", ""), "file": name})
	return out


def testopt_run(plan):
	""
	r = _simtest("test_start", plan=plan)
	if not r.get("ok"):
		TESTOPT["msg"] = str(r.get("error") or "the simulator does not answer (3D-3.27 or newer needed)")
		return None
	TESTOPT["sim"] = r
	frames = []; stop_ = threading.Event()
	threading.Thread(target=_testopt_frames, args=(stop_, frames, time.time()), daemon=True).start()
	try:
		return _testopt_wait(plan, r, frames)
	finally:
		stop_.set()


def _testopt_wait(plan, r, frames):
	t_end = time.time() + max(120, int(r.get("total_s") or 600) * 2)
	seen_running = True
	while time.time() < t_end:
		if TESTOPT["stop"]:
			_simtest("test_stop")
			TESTOPT["msg"] = "stopped"
			return None
		time.sleep(2.0)
		st = _simtest("test_report")
		if not st:
			continue
		TESTOPT["sim"] = st
		if st.get("running"):
			continue
		rep = _clean_report(st.get("report") or {})
		if not rep or rep.get("plan") != plan:
			TESTOPT["msg"] = str(st.get("info") or "test run ended without report")
			return None
		run = {"t": time.time(), "plan": plan, "report": rep, "score": opt_score(rep), "cfg": opt_snapshot(),
			   "mw": APP_VERSION, "sim": str(rep.get("simulator") or "")}
		try:
			run["pics"] = _testopt_pics(run, frames)
		except Exception as e:
			run["pics"] = []; log_event("sys", f"Test run pictures: {e}"[:150])
		with _TESTOPT_LOCK:
			TESTOPT["runs"].append(run); TESTOPT["runs"] = TESTOPT["runs"][-30:]
			TESTOPT["sugg"] = opt_suggest(rep)
			testopt_save()
		log_event("sys", f"Test run «{plan}» finished: persons {rep.get('persons_detected')}/{rep.get('persons')}, "
						 f"false alarms {rep.get('false_alarms')}, score {run['score']}")
		return run
	TESTOPT["msg"] = "the test run takes too long - stopped"
	_simtest("test_stop")
	return None


def _testopt_thread(kind, plan, tries=4):
	try:
		TESTOPT["stop"] = False; TESTOPT["msg"] = ""
		if kind == "run":
			TESTOPT["busy"] = "run"
			testopt_run(plan)
			return

		TESTOPT["busy"] = "auto"
		A = {"plan": plan, "step": 0, "tries": tries, "log": [], "start_cfg": opt_snapshot(), "base": None, "best": None, "kept": []}
		TESTOPT["auto"] = A
		base = testopt_run(plan)
		if base is None or base["score"] is None:
			A["log"].append({"what": "base", "ok": False}); return
		A["base"] = A["best"] = base["score"]
		tried = set()
		_opt_trial_mark(A["start_cfg"])
		while A["step"] < tries and not TESTOPT["stop"]:
			sug = [x for x in opt_suggest(base["report"] if not A["kept"] else TESTOPT["runs"][-1]["report"]) if x["id"] not in tried]
			if not sug:
				break
			x = sug[0]; tried.add(x["id"]); A["step"] += 1
			A["now"] = x["title"]
			before = opt_apply(x["changes"], "automatic, try " + x["id"])
			run = testopt_run(plan)
			if run is None or run["score"] is None:
				opt_restore(before, "automatic, no result"); break
			better = run["score"] >= A["best"] + 3.0
			A["log"].append({"id": x["id"], "title": x["title"], "changes": x["changes"], "score": run["score"], "kept": better})
			if better:
				A["best"] = run["score"]; A["kept"].append(x["id"]); _opt_trial_mark(opt_snapshot())
			else:
				opt_restore(before, "automatic, not better")
		A["now"] = ""
		if A["kept"]:
			TESTOPT["undo"] = {"cfg": A["start_cfg"], "t": time.time(), "what": "auto"}
			testopt_save()
		log_event("sys", f"Automatic optimization finished: score {A['base']} -> {A['best']}, kept: {', '.join(A['kept']) or 'nothing'}")
		_opt_trial_end()
	except Exception as e:
		log_event("sys", f"Optimization stopped by an error: {type(e).__name__}: {e}"[:200])
		try:
			testopt_recover()
		except Exception:
			pass
	finally:
		TESTOPT["busy"] = ""


def testopt_compare():
	""
	runs = TESTOPT["runs"]
	if not runs:
		return None
	L = runs[-1]
	prev = next((r for r in reversed(runs[:-1]) if r.get("plan") == L.get("plan") and r.get("mw") and r.get("mw") != L.get("mw")), None)
	if prev is None or L.get("score") is None or prev.get("score") is None:
		return None
	ph = []
	pp = {p["name"]: p for p in prev["report"].get("phases", [])}
	for p in L["report"].get("phases", []):
		q = pp.get(p["name"])
		if not q:
			continue
		d_found = p["persons_detected"] - q["persons_detected"]; d_fa = p["false_alarms"] - q["false_alarms"]
		if d_found or d_fa:
			ph.append({"name": p["name"], "found": d_found, "fa": d_fa})
	return {"from": prev.get("mw"), "to": L.get("mw"), "score": round(L["score"] - prev["score"], 1), "phases": ph}


def testopt_nightly_loop():
	"""
"""
	done = ""
	while True:
		time.sleep(60)
		try:
			if not CFG.get("testopt_nightly"):
				continue
			now = datetime.now(); day = now.strftime("%Y-%m-%d")
			if now.hour != int(CFG.get("testopt_hour", 3)) or done == day or simtask_busy() or is_armed():
				continue
			if not (CFG["sim_on"] and SIM["ok"] and time.time() - SIM["t"] < 5):
				continue
			if now.weekday() == 6 and CFG.get("weekcheck_on"):
				continue
			done = day
			plan = CFG.get("testopt_plan") if CFG.get("testopt_plan") in ("standard", "quick", "hard", "night", "spielwege") else "quick"
			prev = next((r for r in reversed(TESTOPT["runs"]) if r.get("plan") == plan and r.get("night")), None)
			TESTOPT["busy"] = "night"; TESTOPT["stop"] = False
			try:
				run = testopt_run(plan)
			finally:
				TESTOPT["busy"] = ""
			if run is None:
				continue
			run["night"] = True; testopt_save()
			if prev and prev.get("score") is not None and run.get("score") is not None and run["score"] <= prev["score"] - 10:
				w = WATCH_REF.get("w")
				if w is not None:
					w.notifier.info(trf("Night test run: score {a} instead of {b} - the recognition got worse. Details: tab Simulator.",
										a=run["score"], b=prev["score"]), title="{name}: " + tr("Test run"))
		except Exception as e:
			log_event("sys", f"Night test run: {e}"[:150])


def testopt_state():
	runs = TESTOPT["runs"]
	small = [{"t": r["t"], "plan": r["plan"], "score": r["score"], "rate": r["report"].get("rate"), "fa": r["report"].get("false_alarms"),
			  "lat": r["report"].get("latency_s"), "persons": r["report"].get("persons"), "found": r["report"].get("persons_detected"),
			  "cfg": r.get("cfg"), "mw": r.get("mw", ""), "night": bool(r.get("night"))} for r in runs[-12:]]
	return {"busy": TESTOPT["busy"], "msg": TESTOPT["msg"], "sim": TESTOPT["sim"], "runs": small,
			"last": runs[-1] if runs else None, "sugg": TESTOPT["sugg"], "undo": bool(TESTOPT["undo"]),
			"auto": TESTOPT["auto"], "connected": bool(CFG["sim_on"] and SIM["ok"] and time.time() - SIM["t"] < 5),
			"keys": {k: CFG[k] for k in OPT_KEYS if k in CFG}, "compare": testopt_compare(),
			"nightly": {"on": bool(CFG.get("testopt_nightly")), "hour": int(CFG.get("testopt_hour", 3)), "plan": CFG.get("testopt_plan", "quick")}}















TUNEA = {"busy": False, "step": "", "depth": "", "plans": [], "i": 0, "stop": False, "t0": 0.0, "start_cfg": None, "last": None}
TUNEA_KEYS = ("auto_tune", "train_night_on", "weekcheck_on", "fa_learn_auto")


def autotune_paused():
	"""
"""
	try:
		if TESTOPT.get("busy") or ABT.get("busy") or TRAIN.get("busy") or TUNEA.get("busy"):
			return True
		for ref in ("AUTOTH", "FALEARN", "BLIND"):
			d = globals().get(ref)
			if isinstance(d, dict) and d.get("busy"):
				return True
	except Exception:
		return False
	return False


def _tunea_plans(depth):
	return [("quick", 3)] if depth == "quick" else [("quick", 4), ("night", 4)]


def tune_assist_check(L=None):
	""
	T = lambda x: tr(x, L)
	miss = []
	if not CFG.get("sim_on"):
		miss.append({"id": "sim", "text": T("The simulation is off - switch it on in the tab Simulator (a 3D simulator on a PC is needed)."), "fix": "/sim"})
	elif not sim_ready():
		miss.append({"id": "sim", "text": T("No simulator answers - start the 3D simulator on the PC."), "fix": "/sim"})
	if is_armed():
		miss.append({"id": "armed", "text": T("Protection is on - the test needs it off (a test person would give a real alarm)."), "fix": "/protect"})
	b = simtask_busy("improve assistant")
	if b:
		miss.append({"id": "busy", "text": trf("The simulator is busy: {what}", L, what=tr(b, L)), "fix": ""})
	return miss


def tune_assist_start(depth="quick"):
	if TUNEA["busy"]:
		return False, "already running"
	miss = tune_assist_check()
	if miss:
		return False, miss[0]["text"]
	depth = "thorough" if depth == "thorough" else "quick"
	TUNEA.update(busy=True, step="measure", depth=depth, plans=[], i=0, stop=False, t0=time.time(), start_cfg=opt_snapshot())
	threading.Thread(target=_tunea_thread, args=(depth,), daemon=True, name="tune-assist").start()
	log_event("sys", f"Improve detection: started ({depth})")
	return True, ""


def _tunea_thread(depth):
	res = []
	try:
		for i, (plan, tries) in enumerate(_tunea_plans(depth)):
			if TUNEA["stop"]:
				break
			TUNEA.update(i=i, step=plan)
			_sim_free()
			_testopt_thread("auto", plan, tries)
			A = TESTOPT.get("auto") or {}
			res.append({"plan": plan, "base": A.get("base"), "best": A.get("best"),
						"kept": [{"id": x["id"], "title": x["title"]} for x in A.get("log", []) if x.get("kept")]})
			TUNEA["plans"] = list(res)
	except Exception as e:
		log_event("sys", f"Improve detection: {type(e).__name__}: {e}"[:160])
	finally:
		start = TUNEA.get("start_cfg") or {}
		changed = [[k, start[k], CFG[k]] for k in start if k in CFG and CFG[k] != start[k]]
		TUNEA.update(busy=False, step="", last={"t": time.time(), "depth": depth, "plans": res, "changed": changed,
												"stopped": bool(TUNEA["stop"]), "start_cfg": start, "min": round((time.time() - TUNEA["t0"]) / 60.0, 1),
												"msg": str(TESTOPT.get("msg") or "")})
		_tunea_autotune_base()
		log_event("sys", "Improve detection: done - " + ("; ".join(f"{r['plan']} {r['base']} -> {r['best']}" for r in res) or "no result")
				  + (f", {len(changed)} value(s) changed" if changed else ", nothing changed"))


def _tunea_autotune_base():
	""
	w = WATCH_REF.get("w")
	tu = getattr(w, "tuner", None) if w is not None else None
	if tu is not None:
		try:
			tu.calibrated = True; tu.base_min_area = float(CFG["min_area"]); tu.last_eval = time.time()
		except Exception:
			pass
	try:
		autotune_base_set("assistant")
	except Exception as e:
		log_event("sys", f"Auto-tune base: {e}"[:120])


def tune_assist_stop():
	TUNEA["stop"] = True; TESTOPT["stop"] = True
	try:
		_simtest("test_stop")
	except Exception:
		pass
	return True, ""


def tune_assist_undo():
	""
	if TUNEA["busy"]:
		return False, "the assistant is still running"
	last = TUNEA.get("last") or {}
	snap = last.get("start_cfg")
	if not snap:
		return False, "nothing to undo"
	opt_restore(snap, "improve detection: undo")
	last["undone"] = True; last["changed"] = []
	_tunea_autotune_base()
	return True, ""


def tune_assist_set(key, on):
	if key not in TUNEA_KEYS:
		return False, "unknown setting"
	CFG[key] = bool(on)
	sched_user_changed(key)
	save_settings()
	log_event("sys", f"Improve detection: {key} {'on' if on else 'off'}")
	return True, ""


def tune_assist_state(lang=None):
	L = norm_lang(lang) if lang else cur_lang()
	A = TESTOPT.get("auto") or {}
	run = TESTOPT.get("sim") or {}
	last = TUNEA.get("last")
	if last:
		last = {k: v for k, v in last.items() if k != "start_cfg"}
		last["can_undo"] = bool((TUNEA.get("last") or {}).get("start_cfg")) and not last.get("undone") and bool(last.get("changed"))
	runs = [r for r in TESTOPT.get("runs", []) if r.get("score") is not None]
	return {"ok": True, "busy": TUNEA["busy"], "step": TUNEA["step"], "depth": TUNEA["depth"], "i": TUNEA["i"],
			"n": len(_tunea_plans(TUNEA["depth"] or "quick")), "plans": TUNEA["plans"],
			"now": {"try": A.get("step", 0), "tries": A.get("tries", 0), "what": A.get("now", ""), "base": A.get("base"), "best": A.get("best"),
					"running": bool(isinstance(run, dict) and run.get("running")), "left": run.get("left_s") if isinstance(run, dict) else None,
					"total": run.get("total_s") if isinstance(run, dict) else None},
			"missing": tune_assist_check(L), "last": last, "score": runs[-1]["score"] if runs else None,
			"keys": {k: bool(CFG.get(k)) for k in TUNEA_KEYS}, "train_hour": int(CFG.get("train_hour", 1)),
			"auto_status": str(STATE.get("auto_status") or ""), "simple": page_simple("sim"), "sim_on": bool(CFG.get("sim_on"))}



TUNE_CSS = _zd('312_erkennung_assistent/TUNE_CSS', "")

TUNE_JS = _zd('312_erkennung_assistent/TUNE_JS', "")


def tune_head():
	return "<style>" + TUNE_CSS + "</style><script>" + TUNE_JS + "</script>"




REFSCAN = {"busy": "", "step": 0, "n": 0, "msg": "", "stop": False, "t": 0.0, "last": None, "next_t": 0.0}
_REFSCAN_LOCK = threading.Lock()


def refscan_dir(*p):
	d = os.path.join(DATA_DIR, "refscan", *p)
	return d


def refscan_positions():
	""
	n = max(1, min(12, int(CFG.get("refscan_pan_steps", 6))))
	a, b = float(CFG.get("refscan_pan_from", 10)), float(CFG.get("refscan_pan_to", 90))
	pans = [round((a + b) / 2.0, 1)] if n == 1 else [round(a + (b - a) * i / (n - 1), 1) for i in range(n)]
	m = max(1, min(3, int(CFG.get("refscan_tilt_steps", 1))))
	sp = float(CFG.get("refscan_tilt_span", 16))
	c = float(CFG.get("refscan_tilt_mid", 50))
	tilts = [round(c, 1)] if m == 1 else [round(c - sp / 2.0 + sp * j / (m - 1), 1) for j in range(m)]
	out = []
	for j, t in enumerate(tilts):
		row = pans if j % 2 == 0 else list(reversed(pans))
		out += [(p, t) for p in row]
	return out


def refscan_is_dark():
	if CFG.get("sim_on") and SIM.get("ok"):
		return bool(SIM.get("dark"))
	return bool(LIGHTS.get("dark"))


REFSCAN_KINDS = {"day": "ref", "night": "ref_night"}


def refscan_meta(kind=None):
	""
	order = [kind] if kind else (["night", "day"] if refscan_is_dark() else ["day", "night"])
	for k in order:
		try:
			with open(refscan_dir(REFSCAN_KINDS[k], "meta.json"), encoding="utf-8") as f:
				d = json.load(f)
			if isinstance(d, dict):
				d["_kind"] = k
				return d
		except (OSError, ValueError, KeyError):
			continue
	return None


def refscan_save_meta(meta):
	m = {k: v for k, v in meta.items() if not k.startswith("_")}
	with open(refscan_dir(REFSCAN_KINDS[meta["_kind"]], "meta.json"), "w", encoding="utf-8") as f:
		json.dump(m, f)


def refscan_set_watch(kind, items):
	""
	meta = refscan_meta(kind)
	if not meta:
		return False
	out = []
	np_ = len(meta.get("positions") or [])
	for it in (items or [])[:30]:
		try:
			i = int(it.get("pos")); x, y, w_, h_ = (max(0.0, min(1.0, float(it.get(k)))) for k in ("x", "y", "w", "h"))
		except (TypeError, ValueError):
			continue
		if 0 <= i < np_ and w_ > 0.005 and h_ > 0.005:
			out.append({"pos": i, "x": round(x, 4), "y": round(y, 4), "w": round(w_, 4), "h": round(h_, 4),
						"name": re.sub(r"[\x00-\x1f<>]", "", str(it.get("name") or ""))[:40] or tr("Thing")})
	meta["watch"] = out
	refscan_save_meta(meta)
	log_event("sys", f"Reference scan: {len(out)} things to guard")
	return True


def _refscan_move(pan, tilt):
	MANUAL["until"] = time.time() + 60
	servo_goto(max(0.0, min(100.0, float(pan))), max(0.0, min(100.0, float(tilt))), "refscan", timeout=20.0)


def _refscan_next(w, after, end):
	""
	while time.time() < end and not REFSCAN["stop"]:
		w.raw_until = time.time() + 20
		fr = w.frame_raw
		t0 = float(getattr(w, "_last_t0", 0) or 0)
		if fr is not None and t0 > after:
			return t0, fr.copy()
		time.sleep(0.04)
	return None, None


def _refscan_small(img):
	return cv2.cvtColor(cv2.resize(img, (160, 90), interpolation=cv2.INTER_AREA), cv2.COLOR_BGR2GRAY).astype(np.float32)


def _refscan_grab(w, settle, count):
	"""
"""
	time.sleep(settle)
	end = time.time() + 15 + count * 2
	t_last, prev = _refscan_next(w, time.time() - 0.01, end)
	stable = 0
	while prev is not None and stable < 2 and time.time() < end:
		t_last, cur = _refscan_next(w, t_last, end)
		if cur is None:
			break
		d = float(np.mean(cv2.absdiff(_refscan_small(prev), _refscan_small(cur))))
		stable = stable + 1 if d < 3.0 else 0
		prev = cur
	if prev is None:
		return None
	pics = [prev]
	while len(pics) < count and time.time() < end:
		t_last, cur = _refscan_next(w, t_last, end)
		if cur is None:
			break
		pics.append(cur)
	if len(pics) == 1:
		return pics[0]
	try:
		return np.median(np.stack(pics[:5]), axis=0).astype(np.uint8)
	except ValueError:
		return pics[-1]


def _refscan_settle():
	return max(0.3, float(CFG.get("refscan_settle", 1.5))) + (1.5 if CFG.get("sim_on") else 0.0)


def refscan_start(op, reason="by hand", kind=None):
	""
	with _REFSCAN_LOCK:
		if REFSCAN["busy"] or (globals().get("PLACE") or {}).get("busy"):
			return False, "a scan is already running"
		if WATCH_REF.get("w") is None:
			return False, "no camera"
		if op == "compare" and not refscan_meta(kind):
			return False, "no reference yet - scan first"
		REFSCAN.update(busy=op, step=0, n=len(refscan_positions()) if op == "scan" else len((refscan_meta(kind) or {}).get("positions") or []),
					   msg="", stop=False, t=time.time())
	threading.Thread(target=_refscan_run, args=(op, reason, kind), daemon=True, name="refscan").start()
	log_event("sys", f"Reference scan: {'scan' if op == 'scan' else 'compare'} started ({reason})")
	return True, ""


def refscan_stop():
	REFSCAN["stop"] = True


def _refscan_run(op, reason, kind=None):
	w = WATCH_REF.get("w")
	old = (CFG["pan"], CFG["tilt"])
	try:
		if op == "scan":
			_refscan_do_scan(w)
		else:
			_refscan_do_compare(w, reason, kind)
	except Exception as e:
		REFSCAN["msg"] = "error: " + str(e)[:120]
		log_event("sys", f"Reference scan failed: {e}")
	finally:
		_refscan_move(*old)
		MANUAL["until"] = time.time() + 2
		REFSCAN["busy"] = ""; REFSCAN["stop"] = False


def _refscan_do_scan(w):
	pos = refscan_positions()
	tmp = refscan_dir("ref_new")
	shutil.rmtree(tmp, ignore_errors=True); os.makedirs(tmp, exist_ok=True)
	kind = "night" if refscan_is_dark() else "day"
	old = refscan_meta(kind) or {}
	meta = {"t": time.time(), "positions": [], "source": STATE.get("source_label", ""), "sim": bool(CFG.get("sim_on")),
			"dark": kind == "night", "photos": int(CFG.get("refscan_photos", 2)), "kind": kind,
			"watch": old.get("watch") if len(old.get("positions") or []) == len(refscan_positions()) else []}
	for i, (p, t) in enumerate(pos):
		if REFSCAN["stop"]:
			REFSCAN["msg"] = "stopped"; shutil.rmtree(tmp, ignore_errors=True); return
		REFSCAN["step"] = i + 1
		_refscan_move(p, t)
		img = _refscan_grab(w, _refscan_settle() if i else _refscan_settle() + 1.0, max(1, min(5, int(CFG.get("refscan_photos", 2)))))
		if img is None:
			REFSCAN["msg"] = "no picture from the camera"; shutil.rmtree(tmp, ignore_errors=True); return
		fn = f"pos_{i:02d}.jpg"
		cv2.imwrite(os.path.join(tmp, fn), img, [cv2.IMWRITE_JPEG_QUALITY, 90])
		meta["positions"].append({"i": i, "pan": p, "tilt": t, "file": fn})
	with open(os.path.join(tmp, "meta.json"), "w", encoding="utf-8") as f:
		json.dump(meta, f)
	shutil.rmtree(refscan_dir(REFSCAN_KINDS[kind]), ignore_errors=True)
	os.replace(tmp, refscan_dir(REFSCAN_KINDS[kind]))
	REFSCAN["msg"] = "night reference saved" if kind == "night" else "reference saved"
	log_event("sys", f"Reference scan: {len(pos)} directions saved as the reference")


def _refscan_prep(img, width=640):
	h, w_ = img.shape[:2]
	s = width / float(w_)
	g = cv2.cvtColor(cv2.resize(img, (width, int(h * s)), interpolation=cv2.INTER_AREA), cv2.COLOR_BGR2GRAY)
	g = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(8, 8)).apply(g)
	return cv2.GaussianBlur(g, (3, 3), 0), s


def refscan_compare_images(ref, cur):
	""
	a, _ = _refscan_prep(ref)
	b, _ = _refscan_prep(cur)
	if a.shape != b.shape:
		b = cv2.resize(b, (a.shape[1], a.shape[0]))
	H, W = a.shape
	try:
		win = cv2.createHanningWindow((W, H), cv2.CV_32F)
		(dx, dy), _r = cv2.phaseCorrelate(a.astype(np.float32), b.astype(np.float32), win)
		if abs(dx) < W * 0.12 and abs(dy) < H * 0.12:
			b = cv2.warpAffine(b, np.float32([[1, 0, -dx], [0, 1, -dy]]), (W, H), borderMode=cv2.BORDER_REPLICATE)
	except cv2.error:
		dx = dy = 0.0

	af, bf = a.astype(np.float32), b.astype(np.float32)
	bf = (bf - bf.mean()) / max(1.0, bf.std()) * max(1.0, af.std()) + af.mean()
	d1 = cv2.absdiff(af, bf)
	ga = cv2.magnitude(cv2.Sobel(af, cv2.CV_32F, 1, 0), cv2.Sobel(af, cv2.CV_32F, 0, 1))
	gb = cv2.magnitude(cv2.Sobel(bf, cv2.CV_32F, 1, 0), cv2.Sobel(bf, cv2.CV_32F, 0, 1))
	d2 = cv2.absdiff(cv2.GaussianBlur(ga, (9, 9), 0), cv2.GaussianBlur(gb, (9, 9), 0)) * 0.5
	d = cv2.GaussianBlur(0.55 * d1 + 0.45 * d2, (7, 7), 0)
	sens = max(5.0, min(100.0, float(CFG.get("refscan_sens", 50))))
	thr = 52.0 - sens * 0.45
	m = (d > thr).astype(np.uint8) * 255
	bx = int(W * 0.03); by = int(H * 0.03)
	m[:by, :] = 0; m[-by:, :] = 0; m[:, :bx] = 0; m[:, -bx:] = 0
	m = cv2.morphologyEx(m, cv2.MORPH_CLOSE, np.ones((15, 15), np.uint8))
	m = cv2.morphologyEx(m, cv2.MORPH_OPEN, np.ones((3, 3), np.uint8))
	cnts, _ = cv2.findContours(m, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
	min_a = W * H * max(0.05, float(CFG.get("refscan_min_area", 0.6))) / 100.0
	out = []
	for c in cnts:
		if cv2.contourArea(c) < min_a:
			continue
		x, y, w_, h_ = cv2.boundingRect(c)
		ea = float(ga[y:y + h_, x:x + w_].mean()); eb = float(gb[y:y + h_, x:x + w_].mean())
		kind = "missing" if ea > eb * 1.3 + 2 else ("new" if eb > ea * 1.3 + 2 else "changed")
		out.append({"x": round(x / W, 4), "y": round(y / H, 4), "w": round(w_ / W, 4), "h": round(h_ / H, 4), "kind": kind,
					"score": round(float(d[y:y + h_, x:x + w_].mean()), 1)})
	out.sort(key=lambda r: -r["w"] * r["h"])
	return out[:12], (round(float(dx), 1), round(float(dy), 1)), (d, thr)


def _refscan_watch_check(it, dmap, changes):
	""
	d, thr = dmap
	H, W = d.shape
	x0, y0 = int(it["x"] * W), int(it["y"] * H)
	x1, y1 = max(x0 + 2, int((it["x"] + it["w"]) * W)), max(y0 + 2, int((it["y"] + it["h"]) * H))
	part = d[y0:y1, x0:x1]
	frac = float(np.mean(part > thr * 0.8)) if part.size else 0.0
	over = 0.0
	for c in changes:
		ix = max(0.0, min(it["x"] + it["w"], c["x"] + c["w"]) - max(it["x"], c["x"]))
		iy = max(0.0, min(it["y"] + it["h"], c["y"] + c["h"]) - max(it["y"], c["y"]))
		if c["kind"] != "new":
			over = max(over, ix * iy / max(1e-6, it["w"] * it["h"]))
	return frac > 0.22 or over > 0.35, round(max(frac, over), 2)


def _ascii(t):
	""
	for a, b in (("ä", "ae"), ("ö", "oe"), ("ü", "ue"), ("Ä", "Ae"), ("Ö", "Oe"), ("Ü", "Ue"), ("é", "e"), ("è", "e"), ("à", "a"), ("ç", "c")):
		t = t.replace(a, b)
	return t.encode("ascii", "replace").decode()


REFSCAN_COLORS = {"missing": (60, 60, 255), "new": (255, 160, 60), "changed": (40, 170, 255)}


def _refscan_mark(img, changes):
	out = img.copy(); H, W = out.shape[:2]
	lab = {"missing": tr("missing"), "new": tr("new"), "changed": tr("changed")}
	for c in changes:
		x, y, w_, h_ = int(c["x"] * W), int(c["y"] * H), int(c["w"] * W), int(c["h"] * H)
		col = REFSCAN_COLORS.get(c["kind"], (255, 255, 255))
		cv2.rectangle(out, (x, y), (x + w_, y + h_), col, max(2, W // 320))
		txt = _ascii(lab.get(c["kind"], c["kind"]))
		cv2.putText(out, txt, (x + 4, max(18, y - 6)), cv2.FONT_HERSHEY_SIMPLEX, max(0.5, W / 1400), col, 2, cv2.LINE_AA)
	return out


def _refscan_mark_watch(img, items):
	H, W = img.shape[:2]
	for it in items:
		x, y, w_, h_ = int(it["x"] * W), int(it["y"] * H), int(it["w"] * W), int(it["h"] * H)
		col = (40, 40, 255) if it["gone"] else (80, 210, 80)
		for k in range(0, w_, 12):
			cv2.line(img, (x + k, y), (x + min(w_, k + 6), y), col, 2); cv2.line(img, (x + k, y + h_), (x + min(w_, k + 6), y + h_), col, 2)
		for k in range(0, h_, 12):
			cv2.line(img, (x, y + k), (x, y + min(h_, k + 6)), col, 2); cv2.line(img, (x + w_, y + k), (x + w_, y + min(h_, k + 6)), col, 2)
		txt = _ascii(str(it["name"]) + (" !" if it["gone"] else " ok"))
		cv2.putText(img, txt, (x + 4, y + h_ - 6), cv2.FONT_HERSHEY_SIMPLEX, max(0.5, W / 1400), col, 2, cv2.LINE_AA)
	return img


def _refscan_do_compare(w, reason, kind=None):
	meta = refscan_meta(kind) or {}
	stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
	rd = refscan_dir("reports", stamp)
	os.makedirs(rd, exist_ok=True)
	rep = {"id": stamp, "t": time.time(), "reason": reason, "ref_t": meta.get("t"), "positions": [], "missing": 0, "new": 0, "changed": 0,
		   "ref_kind": meta.get("_kind", "day"), "dark_now": refscan_is_dark(), "watch": []}
	for k, p in enumerate(meta.get("positions") or []):
		if REFSCAN["stop"]:
			REFSCAN["msg"] = "stopped"; break
		REFSCAN["step"] = k + 1
		ref = cv2.imread(refscan_dir(REFSCAN_KINDS[meta.get("_kind", "day")], p["file"]))
		_refscan_move(p["pan"], p["tilt"])
		cur = _refscan_grab(w, _refscan_settle() if k else _refscan_settle() + 1.0, max(1, min(5, int(CFG.get("refscan_photos", 2)))))
		if ref is None or cur is None:
			continue
		if cur.shape != ref.shape:
			cur = cv2.resize(cur, (ref.shape[1], ref.shape[0]))
		ch, sh, dmap = refscan_compare_images(ref, cur)
		for c in ch:
			rep[c["kind"]] += 1
		for it in [x for x in (meta.get("watch") or []) if int(x.get("pos", -1)) == int(p["i"])]:
			gone, sc = _refscan_watch_check(it, dmap, ch)
			rep["watch"].append({"name": it["name"], "pos": p["i"], "gone": gone, "score": sc, "x": it["x"], "y": it["y"], "w": it["w"], "h": it["h"]})
		wl = [x for x in rep["watch"] if x["pos"] == p["i"]]
		cv2.imwrite(os.path.join(rd, f"cur_{p['i']:02d}.jpg"), _refscan_mark_watch(_refscan_mark(cur, ch), wl), [cv2.IMWRITE_JPEG_QUALITY, 82])
		cv2.imwrite(os.path.join(rd, f"ref_{p['i']:02d}.jpg"), _refscan_mark(ref, [c for c in ch if c["kind"] != "new"]), [cv2.IMWRITE_JPEG_QUALITY, 82])
		rep["positions"].append({"i": p["i"], "pan": p["pan"], "tilt": p["tilt"], "changes": ch, "shift": sh})
	with open(os.path.join(rd, "report.json"), "w", encoding="utf-8") as f:
		json.dump(rep, f)
	_refscan_trim()
	REFSCAN["last"] = refscan_summary(rep)
	REFSCAN["msg"] = "report ready"
	n = rep["missing"] + rep["new"] + rep["changed"]
	log_event("sys", f"Reference scan compared ({reason}): {rep['missing']} missing, {rep['new']} new, {rep['changed']} changed")
	gone = [x["name"] for x in rep["watch"] if x["gone"]]
	if gone:
		txt = trf("Guarded thing missing: {names}", names=", ".join(gone))
		log_event("alarm", "Reference scan: guarded thing missing: " + ", ".join(gone))
		push_alert("refscan", txt)
		try:
			img = cv2.imread(os.path.join(rd, f"cur_{int([x for x in rep['watch'] if x['gone']][0]['pos']):02d}.jpg"))
			w.notifier.alert("{name}: " + tr("Reference scan"), txt, img)
		except Exception:
			pass
	if n and CFG.get("refscan_push", True) and (rep["missing"] or CFG.get("refscan_push_all", False)) and w is not None:
		try:
			w.notifier.info(trf("Reference scan: {m} missing, {n} new, {c} changed - see the report", m=rep["missing"], n=rep["new"], c=rep["changed"]),
							title="{name}: " + tr("Reference scan"))
		except Exception:
			pass


def _refscan_trim(keep=20):
	try:
		ids = sorted(os.listdir(refscan_dir("reports")))
		for x in ids[:-keep]:
			shutil.rmtree(refscan_dir("reports", x), ignore_errors=True)
	except OSError:
		pass


def refscan_report(rid):
	if not re.fullmatch(r"\d{8}_\d{6}", str(rid or "")):
		return None
	try:
		with open(refscan_dir("reports", rid, "report.json"), encoding="utf-8") as f:
			return json.load(f)
	except (OSError, ValueError):
		return None


def refscan_summary(rep):
	return {"id": rep["id"], "t": rep["t"], "reason": rep.get("reason", ""), "missing": rep["missing"], "new": rep["new"], "changed": rep["changed"],
			"positions": len(rep.get("positions") or []), "ref_kind": rep.get("ref_kind", "day"), "dark_now": rep.get("dark_now", False),
			"gone": [x["name"] for x in rep.get("watch") or [] if x.get("gone")], "watched": len(rep.get("watch") or [])}


def refscan_reports():
	out = []
	try:
		for x in sorted(os.listdir(refscan_dir("reports")), reverse=True)[:20]:
			r = refscan_report(x)
			if r:
				out.append(refscan_summary(r))
	except OSError:
		pass
	return out


def refscan_state():
	meta = refscan_meta()
	one = lambda m: {"t": m.get("t"), "n": len(m.get("positions") or []), "sim": m.get("sim"), "kind": m.get("_kind"),
					 "dir": REFSCAN_KINDS[m.get("_kind", "day")], "positions": m.get("positions"), "watch": m.get("watch") or []} if m else None
	return {"busy": REFSCAN["busy"], "step": REFSCAN["step"], "n": REFSCAN["n"], "msg": REFSCAN["msg"], "dark": refscan_is_dark(),
			"ref": one(meta), "refs": {"day": one(refscan_meta("day")), "night": one(refscan_meta("night"))},
			"plan": len(refscan_positions()), "reports": refscan_reports(), "next_t": REFSCAN["next_t"] or None}


def refscan_status_text():
	st = refscan_state()
	if st["busy"]:
		return trf("{what}: direction {i} of {n} …", what=tr("Scanning") if st["busy"] == "scan" else tr("Comparing"), i=st["step"], n=st["n"])
	s = (trf("Reference: {n} directions, {t}", n=st["ref"]["n"], t=datetime.fromtimestamp(st["ref"]["t"]).strftime("%d.%m. %H:%M"))
		 if st["ref"] else tr("No reference yet"))
	if st["reports"]:
		r = st["reports"][0]
		s += " · " + trf("last check: {m} missing, {n} new, {c} changed", m=r["missing"], n=r["new"], c=r["changed"])
	return s


def refscan_on_armed():
	""
	if CFG.get("refscan_on_arm") and refscan_meta() and not REFSCAN["busy"]:
		refscan_start("compare", "armed")


def refscan_tick():
	""
	every = float(CFG.get("refscan_every", 0) or 0)
	if every <= 0 or not CFG.get("armed") or STATE.get("arm_state") != "armed" or not refscan_meta():
		REFSCAN["next_t"] = 0.0
		return
	now = time.time()
	if not REFSCAN["next_t"]:
		REFSCAN["next_t"] = now + every * 60
	if now >= REFSCAN["next_t"] and not REFSCAN["busy"] and STATE.get("persons", 0) == 0:
		REFSCAN["next_t"] = now + every * 60
		refscan_start("compare", "every %d min" % int(every))


def _refscan_loop():
	while True:
		time.sleep(20)
		try:
			refscan_tick()
		except Exception:
			pass


threading.Thread(target=_refscan_loop, daemon=True, name="refscantick").start()






PANO = {"busy": False, "day": "", "msg": ""}
PANO_COL = {"missing": (60, 60, 230), "new": (80, 200, 60), "changed": (40, 160, 245)}


def pano_dir(*p):
	return refscan_dir("panorama", *p)


def _pano_reports(since, until):
	out = []
	try:
		for x in sorted(os.listdir(refscan_dir("reports"))):
			r = refscan_report(x)
			if r and since <= float(r.get("t", 0)) <= until:
				out.append(r)
	except OSError:
		pass
	return out


def _pano_track(reps):
	""
	marks = []
	for r in reps:
		seen_now = set()
		for p in r.get("positions") or []:
			for c in p.get("changes") or []:
				if c["w"] * c["h"] > 0.45:
					continue
				cx, cy = c["x"] + c["w"] / 2.0, c["y"] + c["h"] / 2.0
				hit = None
				for m in marks:
					if m["pos"] == p["i"] and m["kind"] == c["kind"] and abs(m["cx"] - cx) < 0.08 and abs(m["cy"] - cy) < 0.08:
						hit = m
						break
				if hit is None:
					hit = {"pos": p["i"], "kind": c["kind"], "cx": cx, "cy": cy, "box": [c["x"], c["y"], c["w"], c["h"]], "first": r["t"], "last": r["t"],
						   "back": None, "name": ""}
					marks.append(hit)
				hit["last"] = r["t"]
				hit["back"] = None
				seen_now.add(id(hit))
		for w_ in r.get("watch") or []:
			if w_.get("gone"):
				for m in marks:
					if m["pos"] == w_["pos"] and abs(m["cx"] - (w_["x"] + w_["w"] / 2)) < 0.12 and abs(m["cy"] - (w_["y"] + w_["h"] / 2)) < 0.12:
						m["name"] = w_["name"]
		for m in marks:
			if id(m) not in seen_now and m["back"] is None and m["last"] < r["t"]:
				m["back"] = r["t"]
	return marks


def pano_canvas(pos, load, tw=320, head=0, foot=0, geo=None):
	"""





"""
	if geo is None:
		pans = sorted({p["pan"] for p in pos})
		tilts = sorted({p["tilt"] for p in pos}, reverse=True)
		th = None
		tiles = {}
		for p in pos:
			im = load(p)
			if im is None:
				continue
			h = int(round(im.shape[0] * tw / im.shape[1]))
			th = th or h
			tiles[p["i"]] = (cv2.resize(im, (tw, th)), pans.index(p["pan"]), tilts.index(p["tilt"]))
		if not tiles:
			return None, {}
		W, H = tw * len(pans), th * len(tilts) + head + foot
		can = np.full((H, W, 3), 22, np.uint8)
		cells = {}
		for i, (im, cx, cy) in tiles.items():
			can[head + cy * th: head + (cy + 1) * th, cx * tw: (cx + 1) * tw] = im
			cells[i] = {"col": cx, "row": cy, "tw": tw, "th": th, "x0": cx * tw, "y0": head + cy * th, "x1": (cx + 1) * tw, "y1": head + (cy + 1) * th}
		return can, cells
	hf, vf, hp, ht = float(geo["hf"]), float(geo["vf"]), float(geo["hp"]), float(geo["ht"])
	wrap = bool(geo.get("wrap"))
	k = tw / hf
	azs = sorted({(float(p["pan"]) - 50.0) / 50.0 * hp for p in pos})
	els = sorted({(float(p["tilt"]) - 50.0) / 50.0 * ht for p in pos}, reverse=True)

	def bounds(cs, fov, wrap_):
		out = []
		for j, c in enumerate(cs):
			if wrap_ and len(cs) > 1:
				prev = cs[j - 1] if j > 0 else cs[-1] - 360.0
				nxt = cs[j + 1] if j + 1 < len(cs) else cs[0] + 360.0
				lo, hi = (prev + c) / 2.0, (nxt + c) / 2.0
			else:
				lo = (cs[j - 1] + c) / 2.0 if j > 0 else c - fov / 2.0
				hi = (cs[j + 1] + c) / 2.0 if j + 1 < len(cs) else c + fov / 2.0
			out.append((max(lo, c - fov / 2.0), min(hi, c + fov / 2.0)))
		return out
	ab = bounds(azs, hf, wrap)
	eb = [(b, a) for a, b in bounds(sorted(els), vf, False)][::-1]
	eb = [(hi, lo) for (hi, lo) in eb]
	a0 = float(geo.get("a0", ab[0][0])); a1 = float(geo.get("a1", ab[-1][1]))
	e_top = float(geo.get("e0", max(x[0] for x in eb))); e_bot = float(geo.get("e1", min(x[1] for x in eb)))
	seam = min(hf / 2.0, 360.0 - (a1 - a0) + hf / 2.0) if wrap else 0.0
	W = max(8, int(round((a1 - a0 + seam) * k))); H = max(8, int(round((e_top - e_bot) * k))) + head + foot
	can = np.full((H, W, 3), 22, np.uint8)
	th_, tv_ = math.tan(math.radians(hf / 2.0)), math.tan(math.radians(vf / 2.0))
	cells = {}
	for p in pos:
		az = (float(p["pan"]) - 50.0) / 50.0 * hp; el = (float(p["tilt"]) - 50.0) / 50.0 * ht
		ci = min(range(len(azs)), key=lambda q: abs(azs[q] - az)); ri = min(range(len(els)), key=lambda q: abs(els[q] - el))
		im = load(p)
		if im is None:
			continue
		ih, iw = im.shape[:2]
		(lo, hi), (top, bot) = ab[ci], eb[ri]
		u0 = int(round((0.5 + math.tan(math.radians(lo - az)) / (2 * th_)) * iw)); u1 = int(round((0.5 + math.tan(math.radians(hi - az)) / (2 * th_)) * iw))
		v0 = int(round((0.5 - math.tan(math.radians(top - el)) / (2 * tv_)) * ih)); v1 = int(round((0.5 - math.tan(math.radians(bot - el)) / (2 * tv_)) * ih))
		u0, u1 = max(0, min(iw - 1, u0)), max(1, min(iw, u1)); v0, v1 = max(0, min(ih - 1, v0)), max(1, min(ih, v1))
		cw = int(round((hi - a0) * k)) - int(round((lo - a0) * k)); chh = int(round((e_top - bot) * k)) - int(round((e_top - top) * k))
		if u1 - u0 < 2 or v1 - v0 < 2 or cw < 2 or chh < 2:
			continue
		part = cv2.resize(im[v0:v1, u0:u1], (cw, chh), interpolation=cv2.INTER_AREA)
		for off in ((0.0, 360.0) if wrap else (0.0,)):
			x = int(round((lo + off - a0) * k)); y = head + int(round((e_top - top) * k))
			if x >= W or x + cw <= 0 or y >= H:
				continue
			xs, xe = max(0, x), min(W, x + cw); ys, ye = max(0, y), min(H - foot, y + chh)
			if xe > xs and ye > ys:
				can[ys:ye, xs:xe] = part[ys - y:ye - y, xs - x:xe - x]
			if off == 0.0:
				cells[p["i"]] = {"col": ci, "row": ri, "tw": cw, "th": chh, "x0": x, "y0": y, "x1": x + cw, "y1": y + chh}
	if not cells:
		return None, {}
	cells["_geo"] = {"a0": round(a0, 3), "a1": round(a1, 3), "e_top": round(e_top, 3), "e_bot": round(e_bot, 3), "k": round(k, 5), "head": head,
					 "w": W, "h": H, "wrap": wrap, "seam": round(seam, 3), "hf": hf, "vf": vf, "hp": hp, "ht": ht}
	return can, cells


def pano_build(since=None, until=None, label=""):
	""
	now = time.time()
	until = until or now
	if since is None:
		y = datetime.now() - timedelta(days=1)
		since = y.replace(hour=18, minute=0, second=0, microsecond=0).timestamp()
	reps = _pano_reports(since, until)
	kind = reps[-1].get("ref_kind") if reps else None
	meta = refscan_meta("day") or refscan_meta(kind)
	if not meta or not meta.get("positions"):
		return None, "no reference yet - scan first"
	pos = meta["positions"]
	head = 54
	can, cells = pano_canvas(pos, lambda p: cv2.imread(refscan_dir(REFSCAN_KINDS[meta["_kind"]], p["file"])), head=head, foot=30)
	if can is None:
		return None, "no reference yet - scan first"
	H, W = can.shape[:2]
	tiles = {i: (None, c["col"], c["row"]) for i, c in cells.items()}
	tw, th = cells[next(iter(cells))]["tw"], cells[next(iter(cells))]["th"]
	marks = _pano_track(reps)
	fmt = lambda t: datetime.fromtimestamp(t).strftime("%H:%M")
	for m in marks:
		if m["pos"] not in tiles:
			continue
		_im, cx, cy = tiles[m["pos"]]
		x0 = cx * tw + int(m["box"][0] * tw); y0 = head + cy * th + int(m["box"][1] * th)
		x1 = x0 + max(6, int(m["box"][2] * tw)); y1 = y0 + max(6, int(m["box"][3] * th))
		col = PANO_COL.get(m["kind"], (200, 200, 200))
		cv2.rectangle(can, (x0, y0), (x1, y1), col, 3 if m["back"] is None else 1, cv2.LINE_AA)
		txt = {"missing": tr("gone"), "new": tr("new"), "changed": tr("changed")}.get(m["kind"], "")
		txt = (m["name"] + " " if m["name"] else "") + txt + " " + fmt(m["first"]) + (" - " + tr("back") + " " + fmt(m["back"]) if m["back"] else "")
		txt = _ascii(txt)
		(tw_, th_), _b = cv2.getTextSize(txt, cv2.FONT_HERSHEY_SIMPLEX, 0.42, 1)
		ty = y0 - 4 if y0 - 4 - th_ > head else y1 + th_ + 4
		cv2.rectangle(can, (x0, ty - th_ - 3), (x0 + tw_ + 4, ty + 3), col, -1)
		cv2.putText(can, txt, (x0 + 2, ty), cv2.FONT_HERSHEY_SIMPLEX, 0.42, (255, 255, 255), 1, cv2.LINE_AA)

	title = _ascii("%s - %s %s - %s" % (CFG.get("device_name") or "MoveEye", tr("Missing things"), datetime.fromtimestamp(since).strftime("%d.%m. %H:%M"),
										 datetime.fromtimestamp(until).strftime("%d.%m. %H:%M")))
	cv2.putText(can, title, (10, 24), cv2.FONT_HERSHEY_SIMPLEX, 0.62, (255, 255, 255), 1, cv2.LINE_AA)
	lx = 10
	for k, n in (("missing", tr("gone")), ("new", tr("new")), ("changed", tr("changed"))):
		cv2.rectangle(can, (lx, 34), (lx + 14, 46), PANO_COL[k], -1)
		cv2.putText(can, _ascii(n), (lx + 20, 45), cv2.FONT_HERSHEY_SIMPLEX, 0.45, (230, 230, 230), 1, cv2.LINE_AA)
		lx += 110
	foot = _ascii(trf("{n} checks in this time, {m} changes", n=len(reps), m=len(marks)) if reps else tr("no comparison in this time"))
	cv2.putText(can, foot, (10, H - 10), cv2.FONT_HERSHEY_SIMPLEX, 0.45, (200, 200, 200), 1, cv2.LINE_AA)
	os.makedirs(pano_dir(), exist_ok=True)
	name = datetime.fromtimestamp(until).strftime("%Y%m%d_%H%M") + ".jpg"
	path = pano_dir(name)
	cv2.imwrite(path, can, [cv2.IMWRITE_JPEG_QUALITY, 85])
	js = [{"kind": m["kind"], "name": m["name"], "pos": m["pos"], "first": m["first"], "back": m["back"]} for m in marks]
	with open(path[:-4] + ".json", "w", encoding="utf-8") as f:
		json.dump({"since": since, "until": until, "checks": len(reps), "marks": js}, f)
	try:
		fs = sorted(x for x in os.listdir(pano_dir()) if x.endswith(".jpg"))
		for x in fs[:-14]:
			for e in (x, x[:-4] + ".json"):
				try:
					os.remove(pano_dir(e))
				except OSError:
					pass
	except OSError:
		pass
	log_event("sys", f"Panorama report: {len(marks)} changes from {len(reps)} checks")
	return path, js


def pano_list():
	out = []
	try:
		for x in sorted((x for x in os.listdir(pano_dir()) if x.endswith(".jpg")), reverse=True)[:14]:
			d = {}
			try:
				with open(pano_dir(x[:-4] + ".json"), encoding="utf-8") as f:
					d = json.load(f)
			except (OSError, ValueError):
				pass
			out.append({"file": x, "checks": d.get("checks", 0), "marks": d.get("marks", []), "since": d.get("since"), "until": d.get("until")})
	except OSError:
		pass
	return out


def pano_send(path, js):
	w = WATCH_REF.get("w")
	if w is None or not path:
		return
	gone = [m for m in js if m["kind"] == "missing" and not m["back"]]
	new = [m for m in js if m["kind"] == "new" and not m["back"]]
	txt = trf("Missing things: {g} gone, {n} new, {c} changes in all", g=len(gone), n=len(new), c=len(js))
	try:
		with open(path, "rb") as f:
			jpg = f.read()
		if morning_add("🧭 " + txt, jpg):
			return
		w.notifier.info(txt, title="{name}: " + tr("Missing things"), jpg=jpg, fname="panorama.jpg")
	except Exception:
		pass


def pano_tick():
	""
	if not CFG.get("refscan_pano_on") or PANO["busy"]:
		return
	d = datetime.now()
	day = d.strftime("%Y-%m-%d")
	if d.hour < int(CFG.get("report_hour", 7)) or PANO["day"] == day or CFG.get("refscan_pano_day") == day:
		return
	PANO["day"] = day
	CFG["refscan_pano_day"] = day
	save_settings()
	PANO["busy"] = True
	try:
		path, js = pano_build()
		if path:
			pano_send(path, js)
		else:
			PANO["msg"] = js
	finally:
		PANO["busy"] = False


def _pano_loop():
	while True:
		time.sleep(60)
		try:
			pano_tick()
		except Exception as e:
			PANO["msg"] = str(e)[:100]


threading.Thread(target=_pano_loop, daemon=True, name="panorama").start()














