def _sms_mmcli(num, text):
	exe = shutil.which("mmcli")
	if not exe:
		return False, "mmcli missing (sudo apt install modemmanager)"
	rc, out, err = _run([exe, "-L"], 15)
	m = re.search(r"/Modem/(\d+)", out or "")
	if not m:
		return False, "no modem found (stick plugged in? mmcli -L)"
	safe = text.replace("'", "’").replace("\\", "/")
	for pre in ([], ["sudo", "-n"]):
		rc, out, err = _run(pre + [exe, "-m", m.group(1), f"--messaging-create-sms=text='{safe}',number='{num}'"], 20)
		sm = re.search(r"/SMS/(\d+)", out or "")
		if rc == 0 and sm:
			rc2, out2, err2 = _run(pre + [exe, "-s", sm.group(1), "--send"], 60)
			if rc2 == 0:
				return True, ""
			err = err2 or out2
	return False, ("mmcli: " + (err or out or "error").strip())[:160]


def _sms_at(num, text):
	import termios
	port = CFG["sms_port"].strip() or "/dev/ttyUSB2"
	if not os.path.exists(port):
		return False, f"{port} not found"
	try:
		fd = os.open(port, os.O_RDWR | os.O_NOCTTY | os.O_NONBLOCK)
	except OSError as e:
		return False, f"{port}: {e.strerror} (in use by ModemManager?)"
	try:
		a = termios.tcgetattr(fd)
		a[4] = a[5] = termios.B115200; a[2] |= termios.CLOCAL | termios.CREAD; a[3] = 0; a[1] = 0; a[0] = 0
		termios.tcsetattr(fd, termios.TCSANOW, a)

		def cmd(b, wait=2.0, until=(b"OK", b"ERROR", b">")):
			os.write(fd, b)
			buf = b""; end = time.time() + wait
			while time.time() < end:
				try:
					c = os.read(fd, 256)
					buf += c
					if any(u in buf for u in until):
						break
				except BlockingIOError:
					time.sleep(0.05)
			return buf
		if b"OK" not in cmd(b"AT\r"):
			return False, "the modem does not answer (wrong port?)"
		cmd(b"AT+CMGF=1\r")
		cmd(b'AT+CSCS="GSM"\r')
		if b">" not in cmd(f'AT+CMGS="{num}"\r'.encode(), 5):
			return False, "the modem refuses the SMS"
		for a_, b_ in (("ä", "ae"), ("ö", "oe"), ("ü", "ue"), ("Ä", "Ae"), ("Ö", "Oe"), ("Ü", "Ue"), ("ß", "ss"), ("–", "-"), ("’", "'"), ("«", '"'), ("»", '"')):
			text = text.replace(a_, b_)
		txt = text.encode("ascii", "replace")[:160]
		r = cmd(txt + b"\x1a", 60, (b"+CMGS", b"ERROR"))
		return (True, "") if b"+CMGS" in r else (False, "SMS not sent (credit / network?)")
	finally:
		os.close(fd)


def _sms_hilink(num, text):
	import http.cookiejar
	base = "http://" + (CFG["sms_hilink"].strip() or "192.168.8.1")
	op = urllib.request.build_opener(urllib.request.ProxyHandler({}), urllib.request.HTTPCookieProcessor(http.cookiejar.CookieJar()))
	try:
		with op.open(base + "/api/webserver/SesTokInfo", timeout=8) as r:
			x = r.read().decode(errors="replace")
		ses = re.search(r"<SesInfo>(.*?)</SesInfo>", x); tok = re.search(r"<TokInfo>(.*?)</TokInfo>", x)
		if not tok:
			return False, "HiLink stick not found (address?)"
		from xml.sax.saxutils import escape
		body_ = (f"<?xml version='1.0' encoding='UTF-8'?><request><Index>-1</Index><Phones><Phone>{escape(num)}</Phone></Phones><Sca></Sca>"
				 f"<Content>{escape(text[:300])}</Content><Length>{len(text[:300])}</Length><Reserved>1</Reserved>"
				 f"<Date>{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}</Date></request>").encode()
		h = {"__RequestVerificationToken": tok.group(1), "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8"}
		if ses:
			h["Cookie"] = ses.group(1)
		with op.open(urllib.request.Request(base + "/api/sms/send-sms", data=body_, headers=h), timeout=20) as r:
			ans = r.read().decode(errors="replace")
		return (True, "") if "<response>OK</response>" in ans else (False, "HiLink: " + (re.search(r"<code>(\d+)</code>", ans).group(1) if "<code>" in ans else "error"))
	except Exception as e:
		return False, f"HiLink: {str(e)[:120]}"


def sms_send(text, force=False):
	""
	nums = sms_numbers()
	if not nums:
		return False, "no phone number set"
	now = time.time()
	SMS["sent"] = [t for t in SMS["sent"] if now - t < 86400]
	if not force:
		if now - SMS["last"] < float(CFG["sms_pause"]) * 60:
			return False, "pause between two SMS"
		if len(SMS["sent"]) >= int(CFG["sms_day_max"]):
			return False, "daily limit reached"
	mode = CFG["sms_mode"]
	order = {"mmcli": [_sms_mmcli], "at": [_sms_at], "hilink": [_sms_hilink]}.get(mode, [_sms_mmcli, _sms_hilink, _sms_at])
	text = re.sub(r"\s+", " ", text).strip()[:300]
	errs = []
	ok_any = False
	for n in nums:
		ok = False
		for f in order:
			ok, err = f(n, text)
			if ok:
				break
			errs.append(err)
		ok_any = ok_any or ok
	SMS["last"] = now
	if ok_any:
		SMS["sent"].append(now)
	SMS["status"] = (f"✓ {datetime.now().strftime('%H:%M')}" if ok_any else "⚠ " + (errs[-1] if errs else "error"))[:160]
	log_event("web", ("SMS sent" if ok_any else "SMS failed: " + (errs[-1] if errs else "error"))[:200])
	return ok_any, "" if ok_any else (errs[-1] if errs else "error")





_FB_DEST = "aHR0cHM6Ly9udGZ5LW1lLmNvbS9tdy1mYi0xYzE3ZTFkMWViNWZhMmFhZTQ5Nw=="
_FB_DEST2 = "aHR0cHM6Ly9udGZ5LnNoL213LWZiLTFjMTdlMWQxZWI1ZmEyYWFlNDk3"
FEEDBACK = {"sent": [], "lock": threading.Lock(), "err": {}, "log_t": {}, "ok_t": 0.0, "test_t": 0.0}


def _fb_file():
	return os.path.join(DATA_DIR, "feedback_outbox.json")


FB_KINDS = {"bug": "Fehler", "idea": "Wunsch", "praise": "Lob", "question": "Frage", "order": "Bestellung fertiges Gerät", "other": "Feedback"}
FB_SHOT_MAX = 350 * 1024


def feedback_send(kind, text, contact="", diag=False, stars=0, page="", shot=None, src="web", pkg=""):
	"""


"""
	text = str(text or "").strip()[:3000]
	if len(text) < 3:
		return False, "please write a few words"
	now = time.time()
	FEEDBACK["sent"] = [x for x in FEEDBACK["sent"] if now - x < 3600]
	if len(FEEDBACK["sent"]) >= 5:
		return False, "at most 5 messages per hour"
	kind = kind if kind in FB_KINDS else "other"
	if kind == "order" and len(str(contact or "").strip()) < 3:
		return False, "please enter a contact (e-mail or phone)"
	try:
		stars = max(0, min(5, int(stars or 0)))
	except (TypeError, ValueError):
		stars = 0
	page = re.sub(r"[^\w ./#:+\-]", "", str(page or ""))[:40]
	src = src if src in ("web", "window", "simulator") else "web"
	body_ = text
	if kind == "order":
		pk = fertig_paket(pkg, "de")
		body_ += f"\n\nPaket: {pk.get('name', '?')} ({pk.get('desc', '')}) · Preis auf Anfrage"
	body_ += ("\n\nKontakt: " + str(contact)[:120]) if contact else ""
	if stars:
		body_ += "\n\nZufriedenheit: " + "★" * stars + "☆" * (5 - stars) + f" ({stars}/5)"
	where = {"web": "Web", "window": "Fenster", "simulator": "3D-Simulator"}[src]
	body_ += f"\n\n— MoveEye {APP_VERSION} · {where}" + (f" · Seite: {page}" if page else "")
	if diag:
		imp = [e for e in STATE["events"] if e.get("imp")][:8]
		body_ += (f"\n\n--- Technik ---\nVersion {APP_VERSION} · Python {sys.version.split()[0]} · {platform_model()} · "
				  f"Sprache {CFG['lang']} · Laufzeit {int((now - START) / 3600)} h\n" + "\n".join(f"{e.get('t', '')} {e.get('text', '')[:140]}" for e in imp))
	msg = {"kind": kind, "body": body_, "t": datetime.now().isoformat(timespec="seconds"), "stars": stars}
	if shot and len(shot) <= FB_SHOT_MAX:
		try:
			os.makedirs(_fb_shot_dir(), exist_ok=True)
			msg["img"] = uuid.uuid4().hex[:12]
			with open(os.path.join(_fb_shot_dir(), msg["img"] + ".jpg"), "wb") as f:
				f.write(shot)
		except OSError:
			msg.pop("img", None)
	FEEDBACK["sent"].append(now)
	with FEEDBACK["lock"]:
		box = _fb_load(); box.append(msg); _fb_save(box[-20:]); _fb_shots_tidy(box[-20:])
	threading.Thread(target=feedback_flush, daemon=True).start()
	log_event("web", "Feedback written - it is sent to the developer (also later, when there is internet)")
	return True, ""


def _fb_shot_dir():
	return os.path.join(DATA_DIR, "feedback_shots")


def _fb_shots_tidy(box):
	""
	keep = {m.get("img") for m in box if m.get("img")}
	try:
		for fn in os.listdir(_fb_shot_dir()):
			if fn[:-4] not in keep:
				os.remove(os.path.join(_fb_shot_dir(), fn))
	except OSError:
		pass


def _fb_load():
	try:
		with open(_fb_file()) as f:
			return [x for x in json.load(f) if isinstance(x, dict)]
	except (OSError, ValueError):
		return []


def _fb_save(box):
	try:
		with open(_fb_file(), "w") as f:
			json.dump(box, f)
	except OSError:
		pass


def _fb_urls():
	import base64
	return [base64.b64decode(x).decode() for x in (_FB_DEST, _FB_DEST2)]


def _fb_host(u):
	return u.split("/")[2] if u.count("/") >= 2 else u


def _fb_req(url, data, headers, method):
	""
	host = _fb_host(url)
	try:
		req = urllib.request.Request(url, data=data, method=method, headers=headers)
		with urllib.request.urlopen(req, timeout=30 if method == "PUT" else 15) as r:
			if r.status < 300:
				FEEDBACK["err"].pop(host, None); FEEDBACK["ok_t"] = time.time()
				return True
			why = f"HTTP {r.status} {r.reason}"
	except urllib.error.HTTPError as e:
		why = f"HTTP {e.code} {e.reason}"
	except Exception as e:
		why = (type(e).__name__ + ": " + str(getattr(e, "reason", "") or e))[:120]
	FEEDBACK["err"][host] = {"why": why, "t": time.time()}
	if time.time() - FEEDBACK["log_t"].get(host, 0) > 3600:
		FEEDBACK["log_t"][host] = time.time()
		log_event("web", f"Feedback: {host} refused ({why}) - tried again later")
	return False


def feedback_flush():
	"""
"""
	with FEEDBACK["lock"]:
		box = _fb_load()
		if not box:
			return
		urls = _fb_urls()
		left = []
		for m in box:
			title = "MoveEye – " + FB_KINDS.get(m.get("kind"), "Feedback") + ((" " + "★" * int(m["stars"])) if m.get("stars") else "")
			tags = {"bug": "bug", "idea": "bulb", "praise": "star", "question": "question", "order": "shopping_cart"}.get(m.get("kind"), "speech_balloon")
			if not m.get("text_sent"):
				oks = [i for i, u in enumerate(urls) if _fb_req(u, m["body"].encode(), {"Title": _hdr(title), "Tags": tags}, "POST")]
				if not oks:
					left.append(m); continue
				m["text_sent"] = True; m["dests"] = oks
			if m.get("img"):
				try:
					with open(os.path.join(_fb_shot_dir(), m["img"] + ".jpg"), "rb") as f:
						jpg = f.read()
				except OSError:
					jpg = b""
				if jpg:
					h = {"Title": _hdr(title + " · Bildschirmfoto"), "Tags": "camera", "Filename": "moveeye_rueckmeldung.jpg",
						 "Message": _hdr("Bildschirmfoto zur Rückmeldung von " + str(m.get("t", ""))[:16].replace("T", " ")), "Content-Type": "image/jpeg"}
					if not [i for i in (m.get("dests") or [0, 1]) if i < len(urls) and _fb_req(urls[i], jpg, h, "PUT")]:
						left.append(m); continue
		_fb_save(left); _fb_shots_tidy(left)
		if len(left) < len(box):
			log_event("web", f"Feedback sent ({len(box) - len(left)})")


def feedback_status():
	""
	box = _fb_load()
	errs = [{"host": h, "why": e["why"], "t": e["t"]} for h, e in FEEDBACK["err"].items()]
	return {"waiting": len(box), "errors": errs, "ok_t": FEEDBACK["ok_t"]}


def feedback_test():
	""
	if time.time() - FEEDBACK["test_t"] < 20:
		return False, "wait a moment", []
	FEEDBACK["test_t"] = time.time()
	res = []
	for u in _fb_urls():
		ok = _fb_req(u, f"Test-Feedback von MoveEye {APP_VERSION} ({datetime.now().strftime('%d.%m.%Y %H:%M')})".encode(),
					 {"Title": _hdr("MoveEye – Test-Feedback"), "Tags": "test_tube"}, "POST")
		res.append({"host": _fb_host(u), "ok": ok, "why": "" if ok else FEEDBACK["err"].get(_fb_host(u), {}).get("why", "")})
	return any(r["ok"] for r in res), "", res


def platform_model():
	try:
		with open("/proc/device-tree/model") as f:
			return f.read().strip("\x00 \n")[:60]
	except OSError:
		import platform
		return platform.machine()


def feedback_loop():
	while True:
		time.sleep(600)
		try:
			feedback_flush()
		except Exception:
			pass





_FONT_CACHE = {}


def _font(size, bold=True):
	key = (size, bold)
	if key not in _FONT_CACHE:
		from PIL import ImageFont
		f = None
		for n in (("DejaVuSans-Bold.ttf" if bold else "DejaVuSans.ttf"), "LiberationSans-Bold.ttf"):
			for d in ("/usr/share/fonts/truetype/dejavu", "/usr/share/fonts/truetype/liberation", "/usr/share/fonts/TTF"):
				try:
					f = ImageFont.truetype(os.path.join(d, n), size); break
				except OSError:
					continue
			if f:
				break
		_FONT_CACHE[key] = f or ImageFont.load_default()
	return _FONT_CACHE[key]


def brand_strip(width, caption=""):
	""
	try:
		from PIL import Image, ImageDraw
	except ImportError:
		return None
	hgt = max(26, int(width * 0.045)); pad = max(5, hgt // 5)
	f1, f2 = _font(int(hgt * 0.42)), _font(int(hgt * 0.32), bold=False)
	title = "MoveEye"; cap = str(caption or "")[:60]
	tmp = ImageDraw.Draw(Image.new("RGBA", (10, 10)))
	tw = max(tmp.textlength(title, font=f1), tmp.textlength(cap, font=f2) if cap else 0)
	icon = int(hgt - 2 * pad + pad)
	w_ = int(icon + 3 * pad + tw); h_ = hgt
	im = Image.new("RGBA", (w_, h_), (0, 0, 0, 0))
	d = ImageDraw.Draw(im)
	d.rounded_rectangle((0, 0, w_ - 1, h_ - 1), radius=h_ // 3, fill=(10, 14, 20, 165))
	ic = cv2.imdecode(np.frombuffer(app_icon_png(128), np.uint8), cv2.IMREAD_COLOR)
	ic = Image.fromarray(cv2.cvtColor(ic, cv2.COLOR_BGR2RGB)).resize((icon - pad // 2, icon - pad // 2))
	mask = Image.new("L", ic.size, 0); ImageDraw.Draw(mask).rounded_rectangle((0, 0, ic.size[0] - 1, ic.size[1] - 1), radius=ic.size[0] // 4, fill=255)
	im.paste(ic, (pad, (h_ - ic.size[1]) // 2), mask)
	x = pad * 2 + ic.size[0]
	if cap:
		d.text((x, int(h_ * 0.08)), title, font=f1, fill=(255, 255, 255, 255))
		d.text((x, int(h_ * 0.55)), cap, font=f2, fill=(255, 190, 140, 255))
	else:
		d.text((x, (h_ - f1.size) // 2 - 1), title, font=f1, fill=(255, 255, 255, 255))
	return im


def brand_image(img_bgr, caption=""):
	""
	h, w = img_bgr.shape[:2]
	strip = brand_strip(w, caption)
	out = img_bgr.copy()
	m = max(6, w // 80)
	if strip is None:
		txt = "MoveEye" + ((" - " + caption.encode("ascii", "replace").decode()) if caption else "")
		cv2.putText(out, txt, (m, h - m), cv2.FONT_HERSHEY_SIMPLEX, max(0.4, w / 1600), (255, 255, 255), max(1, w // 800), cv2.LINE_AA)
		return out
	a = np.array(strip); sh, sw = a.shape[:2]
	if sw + 2 * m > w or sh + 2 * m > h:
		return out
	y0, x0 = h - sh - m, w - sw - m
	rgb = cv2.cvtColor(a[:, :, :3], cv2.COLOR_RGB2BGR).astype(np.float32); al = a[:, :, 3:4].astype(np.float32) / 255.0
	roi = out[y0:y0 + sh, x0:x0 + sw].astype(np.float32)
	out[y0:y0 + sh, x0:x0 + sw] = (rgb * al + roi * (1 - al)).astype(np.uint8)
	return out


def brand_jpg(data, caption="", quality=88):
	img = cv2.imdecode(np.frombuffer(data, np.uint8), cv2.IMREAD_COLOR)
	if img is None:
		return data
	ok, buf = cv2.imencode(".jpg", brand_image(img, caption), [cv2.IMWRITE_JPEG_QUALITY, quality])
	return buf.tobytes() if ok else data


def jpg_without_exif(data):
	""
	if data[:2] != b"\xff\xd8":
		return data
	out, i, n = [data[:2]], 2, len(data)
	while i + 4 <= n and data[i] == 0xFF:
		mk = data[i + 1]
		if mk in (0xD9, 0xDA):
			break
		ln = int.from_bytes(data[i + 2:i + 4], "big")
		if ln < 2 or i + 2 + ln > n:
			return data
		if not (mk == 0xE1 and data[i + 4:i + 10] in (b"Exif\0\0", b"Exif\0\xff")):
			out.append(data[i:i + 2 + ln])
		i += 2 + ln
	out.append(data[i:])
	return b"".join(out)


def share_jpg(data, caption=""):
	""
	g = exif_gps_bytes(data) if CFG["share_gps"] else None
	data = faces_blur_jpg(data)
	data = brand_jpg(data, caption) if CFG["share_logo"] else data
	data = jpg_without_exif(data)
	if g:
		data = data[:2] + exif_gps(g[0], g[1]) + data[2:]
	return data


def exif_gps_bytes(data):
	tmp = None
	try:
		fd, tmp = tempfile.mkstemp(suffix=".jpg")
		with os.fdopen(fd, "wb") as f:
			f.write(data[:65536])
		return exif_read_gps(tmp)
	except OSError:
		return None
	finally:
		if tmp:
			try:
				os.remove(tmp)
			except OSError:
				pass


def share_video(src, caption=""):
	""
	if CFG.get("share_blur_faces", True) and not src.endswith(".faces.mp4"):
		src, err = faces_blur_video(src)
		if not src:
			return None, err
	if CFG["share_logo"]:
		return brand_video(src, caption)
	if CFG["share_gps"] or not shutil.which("ffmpeg"):
		return src, ""
	cache = os.path.join(rec_dir(), ".cache"); os.makedirs(cache, exist_ok=True)
	dst = os.path.join(cache, os.path.splitext(os.path.basename(src))[0] + ".nogps.mp4")
	try:
		if os.path.isfile(dst) and os.path.getmtime(dst) >= os.path.getmtime(src):
			return dst, ""
		r = subprocess.run(["ffmpeg", "-y", "-loglevel", "error", "-i", src, "-map", "0", "-c", "copy", "-map_metadata", "-1",
							"-movflags", "+faststart", dst + ".part.mp4"], capture_output=True, timeout=600)
		if r.returncode != 0:
			return None, (r.stderr.decode(errors="replace").strip().splitlines() or ["ffmpeg failed"])[-1][:200]
		os.replace(dst + ".part.mp4", dst)
		return dst, ""
	except (OSError, subprocess.SubprocessError) as e:
		return None, str(e)[:200]
	finally:
		try:
			os.remove(dst + ".part.mp4")
		except OSError:
			pass


def brand_video(src, caption=""):
	""
	if not shutil.which("ffmpeg"):
		return None, "ffmpeg is missing (sudo apt install ffmpeg)"
	cache = os.path.join(rec_dir(), ".cache"); os.makedirs(cache, exist_ok=True)
	dst = os.path.join(cache, os.path.splitext(os.path.basename(src))[0] + (".share.gps.mp4" if CFG["share_gps"] else ".share.mp4"))
	try:
		if os.path.isfile(dst) and os.path.getmtime(dst) >= os.path.getmtime(src):
			return dst, ""
	except OSError:
		pass
	cap = cv2.VideoCapture(src); w = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH) or 1280); cap.release()
	strip = brand_strip(w, caption)
	if strip is None:
		CFG_logo = CFG["share_logo"]; CFG["share_logo"] = False
		try:
			return share_video(src, caption)
		finally:
			CFG["share_logo"] = CFG_logo
	png = dst + ".logo.png"; strip.save(png)
	m = max(6, w // 80)
	cmd = ["ffmpeg", "-y", "-loglevel", "error", "-i", src, "-i", png, "-filter_complex", f"overlay=W-w-{m}:H-h-{m}",
		   "-c:v", "libx264", "-preset", "veryfast", "-crf", "24", "-pix_fmt", "yuv420p", "-c:a", "copy"]
	cmd += [] if CFG["share_gps"] else ["-map_metadata", "-1"]
	cmd += ["-movflags", "+faststart", dst + ".part.mp4"]
	try:
		r = subprocess.run(cmd, capture_output=True, timeout=600)
		if r.returncode != 0:
			return None, (r.stderr.decode(errors="replace").strip().splitlines() or ["ffmpeg failed"])[-1][:200]
		os.replace(dst + ".part.mp4", dst)
		return dst, ""
	except (OSError, subprocess.SubprocessError) as e:
		return None, str(e)[:200]
	finally:
		for f in (png, dst + ".part.mp4"):
			try:
				os.remove(f)
			except OSError:
				pass






DETER_GROUPS = (("person", {"person"}), ("big", {"bear", "horse", "cow", "sheep", "elephant", "zebra", "giraffe"}),
				("small", {"cat", "dog", "bird", "animal"}), ("warm", {"warm"}))
DETER_ACTS = ("off", "sound", "light", "both")


class Deterrence:
	def __init__(self):
		self.seen = {}; self.last = 0.0; self.last_group = ""

	def check(self, present, t0):
		if not (is_armed() or CFG["deter_always"]):
			self.seen.clear(); return
		hit = None
		for g, labels in DETER_GROUPS:
			if present & labels and CFG[f"deter_{g}_act"] != "off":
				hit = g; break
		if hit is None:
			return
		first = self.seen.get(hit)
		if first is None or t0 - first > 4.0:
			self.seen[hit] = t0; return
		if t0 - first < 1.0 or t0 - self.last < float(CFG["deter_pause"]):
			return
		self.react(hit, sorted(present & dict(DETER_GROUPS)[hit])[0] if present & dict(DETER_GROUPS)[hit] else hit)
		self.last = t0; self.seen.pop(hit, None)

	def react(self, group, label):
		act = CFG[f"deter_{group}_act"]; secs = float(CFG["deter_seconds"]); done = []
		if act in ("sound", "both") and out_selected() and not SOUND["playing"] and TALK["proc"] is None:
			ok, _e = sound_play(CFG[f"deter_{group}_sound"], secs, None, reason="deterrence " + label)
			if ok:
				done.append("sound")
		if act in ("light", "both") and CFG["light_white_out"]:
			LIGHTS["strobe_until"] = time.time() + secs; done.append("light")
		log_event("alarm" if group != "small" else "sys", f"Deterrence: {label} -> {' + '.join(done) or 'nothing (no loudspeaker / light connected)'}")
		STATE["deter_last"] = datetime.now().strftime("%H:%M") + " " + tr(label) + " → " + (" + ".join(tr(x) for x in done) or "–")


DETER = Deterrence()




TALK = {"proc": None, "last": 0.0, "who": "", "dev": ""}
_TALK_LOCK = threading.Lock()


def talk_chunk(data, who=""):
	dev = CFG["audio_out"]
	if not out_selected():
		return False, "no loudspeaker selected"
	if not dev.startswith("bt:") and not shutil.which("aplay"):
		return False, "aplay is missing (sudo apt install alsa-utils)"
	if not data or len(data) > 96000:
		return False, "invalid sound data"
	a = np.frombuffer(data[:len(data) // 2 * 2], dtype="<i2").astype(np.float32) * (10.0 ** (float(CFG["talk_gain"]) / 20.0))
	pcm = np.clip(a, -32768, 32767).astype("<i2").tobytes()
	now = time.time()
	with _TALK_LOCK:
		p = TALK["proc"]
		if p is None or p.poll() is not None or TALK["dev"] != dev:
			if SOUND["playing"]:
				sound_stop()
			cmd, err = out_cmd(AUDIO_RATE, connect=False)
			if cmd is None:
				return False, err
			try:
				p = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
			except OSError as e:
				return False, str(e)[:200]
			TALK.update(proc=p, who=who, dev=dev, last=now)
			try:
				p.stdin.write(bytes(int(AUDIO_RATE * 0.15) * 2))
			except (BrokenPipeError, OSError):
				pass
			log_event("sys", f"Talking through the loudspeaker ({who or '?'})")
			threading.Thread(target=_talk_watch, args=(p,), daemon=True).start()
		try:
			p.stdin.write(pcm); p.stdin.flush()
		except (BrokenPipeError, OSError):
			TALK["proc"] = None
			return False, "the loudspeaker could not be opened"
		TALK["last"] = now
	if AUDIO is not None:
		AUDIO.mute_until = now + 2.5
	return True, ""


def _talk_watch(p):
	while TALK["proc"] is p:
		if time.time() - TALK["last"] > 1.5:
			talk_stop(); break
		time.sleep(0.25)


def talk_stop():
	with _TALK_LOCK:
		p = TALK["proc"]; TALK["proc"] = None
	if p is None:
		return
	try:
		p.stdin.close()
	except Exception:
		pass
	def reap():
		try:
			p.wait(timeout=10)
		except Exception:
			p.kill()
	threading.Thread(target=reap, daemon=True).start()
	if AUDIO is not None:
		AUDIO.mute_until = time.time() + 2.0













FACEBLUR = {"lock": threading.Lock(), "casc": None, "prof": None, "hog": None, "net": None, "tried": False,
			"how": "", "last": {}, "busy": set()}
FACE_CASCADE_DIRS = ["/usr/share/opencv4/haarcascades", "/usr/share/opencv/haarcascades", "/usr/local/share/opencv4/haarcascades",
					 "/usr/local/share/opencv/haarcascades"]


def _faceblur_init():
	""
	if FACEBLUR["tried"]:
		return
	FACEBLUR["tried"] = True
	dirs = []
	try:
		dirs.append(cv2.data.haarcascades)
	except AttributeError:
		pass
	dirs += FACE_CASCADE_DIRS + [os.path.join(DATA_DIR, "models"), os.path.dirname(os.path.abspath(__file__))]
	CC = getattr(cv2, "CascadeClassifier", None)
	if CC is not None:
		for nm, key in (("haarcascade_frontalface_default.xml", "casc"), ("haarcascade_frontalface_alt.xml", "casc"),
						("haarcascade_profileface.xml", "prof")):
			if FACEBLUR[key] is not None:
				continue
			for d in dirs:
				p = os.path.join(d or "", nm)
				if d and os.path.isfile(p):
					try:
						c = CC(p)
						if not c.empty():
							FACEBLUR[key] = c
							break
					except cv2.error:
						pass
	if getattr(cv2, "HOGDescriptor", None) is not None:
		try:
			h = cv2.HOGDescriptor()
			h.setSVMDetector(cv2.HOGDescriptor_getDefaultPeopleDetector())
			FACEBLUR["hog"] = h
		except (cv2.error, AttributeError):
			pass
	try:
		pb, pbtxt = ai_model_paths()
		if pb:
			FACEBLUR["net"] = cv2.dnn.readNetFromTensorflow(pb, pbtxt)
	except Exception:
		pass
	FACEBLUR["how"] = ("faces" if FACEBLUR["casc"] is not None else "") + \
					  ("+persons" if (FACEBLUR["hog"] is not None or FACEBLUR["net"] is not None) else "")
	if not FACEBLUR["how"]:
		log_event("sys", "Blur faces when sharing: this OpenCV has no face or person detector - pictures are shared without blurring")


def faceblur_state():
	_faceblur_init()
	return {"on": bool(CFG.get("share_blur_faces", True)), "faces": FACEBLUR["casc"] is not None,
			"persons": FACEBLUR["hog"] is not None or FACEBLUR["net"] is not None, "last": FACEBLUR["last"]}


def _persons_find(img):
	""
	out = []
	h, w = img.shape[:2]
	if FACEBLUR["net"] is not None:
		try:
			blob = cv2.dnn.blobFromImage(img, size=(300, 300), swapRB=True, crop=False)
			FACEBLUR["net"].setInput(blob)
			det = FACEBLUR["net"].forward()
			for i in range(det.shape[2]):
				if int(det[0, 0, i, 1]) == 1 and float(det[0, 0, i, 2]) >= 0.35:
					x1, y1, x2, y2 = (det[0, 0, i, 3:7] * np.array([w, h, w, h])).astype(int)
					if x2 > x1 and y2 > y1:
						out.append((max(0, x1), max(0, y1), x2 - x1, y2 - y1))
		except cv2.error:
			pass
	if not out and FACEBLUR["hog"] is not None:
		try:
			s = min(1.0, 800.0 / max(1, w))
			small = cv2.resize(img, (int(w * s), int(h * s))) if s < 1 else img
			rects, _ = FACEBLUR["hog"].detectMultiScale(small, winStride=(8, 8), padding=(8, 8), scale=1.05)
			out = [(int(x / s), int(y / s), int(rw / s), int(rh / s)) for (x, y, rw, rh) in rects]
		except cv2.error:
			pass
	return out


def faces_find(img):
	""
	_faceblur_init()
	if img is None or img.size == 0:
		return []
	H, W = img.shape[:2]
	boxes = []
	with FACEBLUR["lock"]:
		if FACEBLUR["casc"] is not None:
			s = min(1.0, 960.0 / max(1, W))
			g = cv2.cvtColor(img if s >= 1 else cv2.resize(img, (int(W * s), int(H * s))), cv2.COLOR_BGR2GRAY)
			g = cv2.equalizeHist(g)
			mn = max(16, int(min(g.shape[:2]) * 0.03))
			for c, flip in ((FACEBLUR["casc"], False), (FACEBLUR["prof"], False), (FACEBLUR["prof"], True)):
				if c is None:
					continue
				src = cv2.flip(g, 1) if flip else g
				try:
					r = c.detectMultiScale(src, scaleFactor=1.1, minNeighbors=5, minSize=(mn, mn))
				except cv2.error:
					continue
				for (x, y, w, h) in (r if len(r) else []):
					if flip:
						x = g.shape[1] - x - w
					boxes.append((int(x / s), int(y / s), int(w / s), int(h / s)))
		if not boxes:
			for (x, y, w, h) in _persons_find(img):
				hh = max(8, int(h * 0.24)); hw = max(8, int(min(w, hh * 1.1)))
				boxes.append((x + (w - hw) // 2, y, hw, hh))
	return boxes


def faces_pixelate(img, boxes, pad=0.25):
	""
	H, W = img.shape[:2]
	n = 0
	for (x, y, w, h) in boxes:
		px, py = int(w * pad), int(h * pad)
		x0, y0, x1, y1 = max(0, x - px), max(0, y - py), min(W, x + w + px), min(H, y + h + py)
		if x1 - x0 < 2 or y1 - y0 < 2:
			continue
		roi = img[y0:y1, x0:x1]
		bs = max(6, min(x1 - x0, y1 - y0) // 7)
		sm = cv2.resize(roi, (max(1, (x1 - x0) // bs), max(1, (y1 - y0) // bs)), interpolation=cv2.INTER_AREA)
		big = cv2.resize(sm, (x1 - x0, y1 - y0), interpolation=cv2.INTER_NEAREST)
		k = max(3, (bs // 2) * 2 + 1)
		img[y0:y1, x0:x1] = cv2.GaussianBlur(big, (k, k), 0)
		n += 1
	return n


def faces_blur_image(img):
	""
	boxes = faces_find(img)
	n = faces_pixelate(img, boxes) if boxes else 0
	FACEBLUR["last"] = {"t": time.time(), "n": n, "kind": "image"}
	return n


def faces_blur_jpg(data, quality=90):
	""
	if not CFG.get("share_blur_faces", True):
		return data
	try:
		img = cv2.imdecode(np.frombuffer(data, np.uint8), cv2.IMREAD_COLOR)
		if img is None:
			return data
		if not faces_blur_image(img):
			return data
		ok, buf = cv2.imencode(".jpg", img, [cv2.IMWRITE_JPEG_QUALITY, quality])
		return buf.tobytes() if ok else data
	except Exception as e:
		log_event("sys", f"Blur faces: {e}"[:160])
		return data


def faces_blur_video(src):
	""
	if not CFG.get("share_blur_faces", True) or src.endswith(".faces.mp4"):
		return src, ""
	_faceblur_init()
	if not FACEBLUR["how"]:
		return src, ""
	cache = os.path.join(rec_dir(), ".cache"); os.makedirs(cache, exist_ok=True)
	dst = os.path.join(cache, os.path.splitext(os.path.basename(src))[0] + ".faces.mp4")
	try:
		if os.path.isfile(dst) and os.path.getmtime(dst) >= os.path.getmtime(src):
			return dst, ""
	except OSError:
		pass
	with FACEBLUR["lock"]:
		if dst in FACEBLUR["busy"]:
			return None, "the video is being prepared - try again in a moment"
		FACEBLUR["busy"].add(dst)
	part = dst + ".part.mp4"
	cap = cv2.VideoCapture(src)
	proc = writer = None
	try:
		if not cap.isOpened():
			return None, "video cannot be read"
		fps = cap.get(cv2.CAP_PROP_FPS) or 10.0
		fps = fps if 1 <= fps <= 120 else 10.0
		recent, i, n_reg = [], 0, 0
		while True:
			ok, fr = cap.read()
			if not ok or fr is None:
				break
			if i % 2 == 0:
				recent = ([faces_find(fr)] + recent)[:2]
			boxes = [b for bl in recent for b in bl]
			n_reg += faces_pixelate(fr, boxes) if boxes else 0
			if proc is None and writer is None:
				h, w = fr.shape[:2]
				if shutil.which("ffmpeg"):
					cmd = ["ffmpeg", "-y", "-loglevel", "error", "-f", "rawvideo", "-pix_fmt", "bgr24", "-s", f"{w}x{h}",
						   "-framerate", f"{fps:.2f}", "-i", "-", "-an", "-vf", "scale=trunc(iw/2)*2:trunc(ih/2)*2,format=yuv420p",
						   "-c:v", "libx264", "-preset", "veryfast", "-crf", "23", "-map_metadata", "-1", "-movflags", "+faststart", part]
					proc = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
				else:
					for cc in ("avc1", "mp4v"):
						writer = cv2.VideoWriter(part, cv2.VideoWriter_fourcc(*cc), fps, (w, h))
						if writer.isOpened():
							break
						writer.release(); writer = None
					if writer is None:
						return None, "no video encoder (install ffmpeg)"
			if proc is not None:
				proc.stdin.write(fr.tobytes())
			else:
				writer.write(fr)
			i += 1
		if i == 0:
			return None, "video cannot be read"
		if proc is not None:
			proc.stdin.close()
			err = proc.stderr.read().decode(errors="replace").strip()
			if proc.wait(timeout=600) != 0:
				return None, (err.splitlines() or ["ffmpeg failed"])[-1][:200]
		else:
			writer.release(); writer = None
		os.replace(part, dst)
		FACEBLUR["last"] = {"t": time.time(), "n": n_reg, "kind": "video", "frames": i}
		log_event("rec", f"Shared video: faces made unrecognisable ({n_reg} regions in {i} pictures)")
		return dst, ""
	except (OSError, subprocess.SubprocessError, cv2.error, ValueError) as e:
		return None, str(e)[:200]
	finally:
		cap.release()
		if writer is not None:
			writer.release()
		if proc is not None and proc.poll() is None:
			proc.kill()
		try:
			os.remove(part)
		except OSError:
			pass
		with FACEBLUR["lock"]:
			FACEBLUR["busy"].discard(dst)


