_ENC = {"hw": None}


def _ffmpeg_hw_ok():
	if _ENC["hw"] is None:
		try:
			r = subprocess.run(["ffmpeg", "-hide_banner", "-loglevel", "error", "-f", "lavfi", "-i", "testsrc=size=320x240:rate=10",
								"-frames:v", "5", "-c:v", "h264_v4l2m2m", "-pix_fmt", "yuv420p", "-f", "null", "-"],
							   capture_output=True, timeout=20)
			_ENC["hw"] = r.returncode == 0
		except Exception:
			_ENC["hw"] = False
	return _ENC["hw"]


class FfmpegWriter:
	"""
"""
	def __init__(self, path, fps, size, hw):
		w, h = size
		enc = ["-c:v", "h264_v4l2m2m", "-b:v", "4M"] if hw else ["-c:v", "libx264", "-preset", "ultrafast", "-crf", "25"]
		cmd = ["ffmpeg", "-y", "-loglevel", "error", "-f", "rawvideo", "-pix_fmt", "bgr24", "-s", f"{w}x{h}", "-framerate", f"{fps:.2f}",
			   "-i", "-", "-an", "-vf", "scale=trunc(iw/2)*2:trunc(ih/2)*2,format=yuv420p"] + enc + \
			  ["-movflags", "+frag_keyframe+empty_moov+default_base_moof", path]
		if shutil.which("nice"):
			cmd = ["nice", "-n", "5"] + cmd
		self.size = (w, h); self.failed = False; self.dropped = 0; self.hw = hw; self.t_open = time.time()
		self.proc = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
		self.q = queue.Queue(maxsize=max(4, min(60, int(150e6 / max(1, w * h * 3)))))
		self.th = threading.Thread(target=self._pump, daemon=True); self.th.start()

	def _pump(self):
		while True:
			item = self.q.get()
			if item is None:
				break
			try:
				self.proc.stdin.write(item)
			except (BrokenPipeError, OSError, ValueError):
				self.failed = True
				break
		try:
			self.proc.stdin.close()
		except Exception:
			pass

	def isOpened(self):
		return self.proc.poll() is None and not self.failed

	def write(self, frame):
		if self.failed or self.proc.poll() is not None:
			self.failed = True; return
		try:
			self.q.put_nowait(frame.tobytes())
		except queue.Full:
			self.dropped += 1

	def release(self):
		try:
			self.q.put(None, timeout=5)
		except queue.Full:
			self.proc.kill()
		self.th.join(30)
		try:
			self.proc.wait(timeout=30)
		except subprocess.TimeoutExpired:
			self.proc.kill()


def open_writer(path, fps, size):
	"""
"""
	d_ = os.path.dirname(os.path.abspath(path))
	try:
		os.makedirs(d_, exist_ok=True)
	except OSError:
		pass
	if not os.access(d_, os.W_OK):
		return None, ""
	if CFG["record_encoder"] == "auto" and "ffmpeg" not in _BAD_CODECS and shutil.which("ffmpeg"):
		for hw in ((True, False) if _ffmpeg_hw_ok() else (False,)):
			if hw and ("ffmpeg_hw" in _BAD_CODECS or size[0] > 1920 or size[1] > 1088):
				continue
			try:
				w = FfmpegWriter(path, fps, size, hw)
				time.sleep(0.2)
				if w.isOpened():
					STATE["recording_enc"] = "ffmpeg h264_v4l2m2m (hardware)" if hw else "ffmpeg x264"
					return w, "h264"
				w.release()
			except Exception:
				pass
			try:
				os.remove(path)
			except OSError:
				pass
		_BAD_CODECS.add("ffmpeg")
	for cc in ("avc1", "mp4v"):
		if cc in _BAD_CODECS:
			continue
		try:
			w = cv2.VideoWriter(path, cv2.VideoWriter_fourcc(*cc), fps, size)
		except Exception:
			w = None
		if w is not None and w.isOpened():
			STATE["recording_enc"] = "OpenCV " + cc
			return w, cc
		_BAD_CODECS.add(cc)
		if w is not None:
			w.release()
		try:
			os.remove(path)
		except OSError:
			pass
	return None, ""



STORE = {"fallback": False, "moving": False, "msg": ""}
_FS_OK = {"ext4", "ext3", "ext2", "btrfs", "xfs", "f2fs", "vfat", "exfat", "ntfs", "ntfs3", "fuseblk"}


def _mounts():
	out = []
	try:
		with open("/proc/mounts") as f:
			for line in f:
				p = line.split()
				if len(p) >= 3:
					out.append((p[0], p[1].replace("\\040", " "), p[2]))
	except OSError:
		pass
	return out


def _dev_kind(dev):
	d = os.path.basename(dev or "")
	if d.startswith("mmcblk"):
		return "sd"
	if d.startswith("nvme"):
		return "ssd"
	if d.startswith("sd"):
		return "usb"
	return "other"


def _mount_of(path):
	""
	path = os.path.realpath(path); best = ("", "/", "")
	for dev, mp, fs in _mounts():
		if (path == mp or path.startswith(mp.rstrip("/") + "/")) and len(mp) >= len(best[1]):
			best = (dev, mp, fs)
	return best


def storage_candidates():
	""
	root_dev = _mount_of("/")[0]
	out = []
	for dev, mp, fs in _mounts():
		if fs not in _FS_OK or not dev.startswith("/dev/") or mp in ("/", "/boot", "/boot/firmware") or dev == root_dev:
			continue
		if not (mp.startswith(("/media/", "/mnt/", "/srv/")) or _dev_kind(dev) in ("ssd", "usb")):
			continue
		try:
			du = shutil.disk_usage(mp)
		except OSError:
			continue
		out.append({"path": mp, "kind": _dev_kind(dev), "fs": fs, "free_gb": round(du.free / 1024 ** 3, 1),
					"total_gb": round(du.total / 1024 ** 3, 1), "writable": os.access(mp, os.W_OK), "fat": fs == "vfat"})
	return out


def storage_info():
	sysdev, _mp, _fs = _mount_of("/")
	rdev, rmp, rfs = _mount_of(rec_dir() if os.path.isdir(rec_dir()) else os.path.dirname(rec_dir()) or "/")
	return {"system": _dev_kind(sysdev), "rec": _dev_kind(rdev), "rec_mount": rmp, "rec_fs": rfs, "rec_dir": rec_dir(),
			"want": CFG["storage_path"], "fallback": STORE["fallback"], "moving": STORE["moving"], "msg": STORE["msg"],
			"candidates": storage_candidates()}


def storage_apply(start=False):
	""
	want = CFG["storage_path"].strip()
	if not want:
		CFG["record_dir"] = "recordings"; STORE["fallback"] = False; return True
	target = os.path.join(want, "MotionWatch", "recordings")
	ok = os.path.ismount(want) or os.path.isdir(want)
	if ok and want.startswith(("/media/", "/mnt/")):
		q = os.path.abspath(want)
		while q not in ("/", "/media", "/mnt") and not os.path.ismount(q):
			q = os.path.dirname(q)
		ok = q not in ("/", "/media", "/mnt")
	if ok:
		try:
			os.makedirs(target, exist_ok=True)
			probe = os.path.join(target, ".mw_probe")
			with open(probe, "w") as f:
				f.write("ok")
			os.remove(probe)
		except OSError:
			ok = False
	if ok:
		CFG["record_dir"] = target; STORE["fallback"] = False
		return True
	CFG["record_dir"] = "recordings"; STORE["fallback"] = True
	log_event("sys", f"Storage: drive {want} not found or not writable - recordings go to the memory card for now")
	return False


def storage_set(path, move=True):
	""
	path = str(path or "").strip()
	if path and not any(c["path"] == path for c in storage_candidates()):
		return False, "drive not found"
	if STORE["moving"]:
		return False, "already moving recordings - wait a moment"
	old = rec_dir()
	CFG["storage_path"] = path
	if not storage_apply():
		CFG["storage_path"] = ""; storage_apply()
		return False, "the drive cannot be written to"
	save_settings()
	new = rec_dir()
	log_event("sys", f"Storage: recordings now in {new}")
	if move and os.path.isdir(old) and os.path.realpath(old) != os.path.realpath(new):
		def run():
			STORE.update(moving=True, msg="moving recordings …"); n = 0
			try:
				for nm in os.listdir(old):
					src, dst = os.path.join(old, nm), os.path.join(new, nm)
					if nm.startswith(".") or os.path.exists(dst) or _is_live(nm, WATCH_REF.get("w")) or (nm == "loop" and LOOPREC is not None and LOOPREC.cur):
						continue
					try:
						shutil.move(src, dst); n += 1
					except (OSError, shutil.Error):
						pass
				STORE["msg"] = f"{n} files moved"
				log_event("sys", f"Storage: {n} files moved to {new}")
			finally:
				STORE["moving"] = False
		threading.Thread(target=run, daemon=True, name="storage-move").start()
	return True, ""


LOOP_RE = re.compile(r"^loop/(\d{4}-\d{2}-\d{2})/(\d{2})-(\d{2})\.mp4$")


def loop_dir():
	return os.path.join(rec_dir(), "loop")


class LoopRecorder:
	"""
"""
	SEG = 600

	def __init__(self):
		self.q = queue.Queue(maxsize=8); self.next_t = 0.0; self.wr = None; self.cur = ""; self.seg_end = 0.0
		self.size = None; self.last_clean = 0.0
		threading.Thread(target=self.loop, daemon=True, name="looprec").start()

	def feed(self, frame, t0):
		if not CFG["loop_on"] or frame is None or t0 < self.next_t:
			return
		self.next_t = t0 + 1.0 / max(1, int(CFG["loop_fps"]))
		try:
			self.q.put_nowait((frame.copy(), time.time()))
		except queue.Full:
			pass

	def _close(self):
		if self.wr is not None:
			try:
				self.wr.release()
			except Exception:
				pass
			LIVE_RECS.discard(self.cur)
		self.wr = None; self.cur = ""

	def loop(self):
		while True:
			try:
				self._step()
			except Exception as e:
				log_event("rec", f"Continuous recording: {type(e).__name__}: {e}"[:200])
				try:
					self._close()
				except Exception:
					self.wr = None
				time.sleep(30)

	def _step(self):
		beat("looprec", 120, "Continuous recording")
		if True:
			try:
				frame, t = self.q.get(timeout=5)
			except queue.Empty:
				if not CFG["loop_on"]:
					self._close()
				self._clean()
				return
			if not CFG["loop_on"]:
				self._close(); return
			h, w = frame.shape[:2]
			if w > 1280:
				frame = cv2.resize(frame, (1280, int(h * 1280 / w))); h, w = frame.shape[:2]
			if self.wr is None or t >= self.seg_end or self.size != (w, h):
				self._close()
				dt = datetime.fromtimestamp(t)
				start = dt.replace(minute=dt.minute - dt.minute % 10, second=0, microsecond=0)
				self.seg_end = start.timestamp() + self.SEG
				name = f"loop/{start:%Y-%m-%d}/{start:%H-%M}.mp4"
				path = os.path.join(rec_dir(), name)
				os.makedirs(os.path.dirname(path), exist_ok=True)
				k_ = 1
				while os.path.exists(path):
					name = f"loop/{start:%Y-%m-%d}/{start:%H-%M}_{k_}.mp4"; path = os.path.join(rec_dir(), name); k_ += 1
				wr, _codec = open_writer(path, max(1, int(CFG["loop_fps"])), (w, h))
				if wr is None:
					time.sleep(10); return
				self.wr, self.cur, self.size = wr, name, (w, h); LIVE_RECS.add(name)
			try:
				self.wr.write(frame)
			except Exception:
				self._close()
			self._clean()

	def _clean(self):
		now = time.time()
		if now - self.last_clean < 60:
			return
		self.last_clean = now
		keep = float(CFG["loop_hours"]) * 3600
		base = loop_dir()
		try:
			days = sorted(os.listdir(base))
		except OSError:
			return
		for d in days:
			dp = os.path.join(base, d)
			try:
				for n in os.listdir(dp):
					p = os.path.join(dp, n)
					if f"loop/{d}/{n}" != self.cur and now - os.path.getmtime(p) > keep:
						os.remove(p)
				if not os.listdir(dp) and not self.cur.startswith(f"loop/{d}/"):
					os.rmdir(dp)
			except OSError:
				pass
		try:
			while shutil.disk_usage(base).free < 1024 ** 3:
				files = sorted(glob.glob(os.path.join(base, "*", "*.mp4")))
				files = [f for f in files if not f.endswith(self.cur.split("/", 1)[-1])]
				if not files:
					break
				os.remove(files[0])
		except OSError:
			pass


LOOPREC = None


def loop_day(day):
	""
	out = {"day": day, "segments": [], "events": [], "days": []}
	try:
		out["days"] = sorted(os.listdir(loop_dir()), reverse=True)[:60]
	except OSError:
		pass
	if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", day or ""):
		return out
	dp = os.path.join(loop_dir(), day)
	try:
		names = sorted(os.listdir(dp))
	except OSError:
		names = []
	for n in names:
		m = re.fullmatch(r"(\d{2})-(\d{2})\.mp4", n)
		if not m:
			continue
		try:
			st = os.stat(os.path.join(dp, n))
		except OSError:
			continue
		name = f"loop/{day}/{n}"
		out["segments"].append({"name": name, "start": f"{m.group(1)}:{m.group(2)}", "size": st.st_size, "live": name in LIVE_RECS,
								"min": int(m.group(1)) * 60 + int(m.group(2))})
	stamp = day.replace("-", "")
	try:
		for n in os.listdir(rec_dir()):
			if stamp in n and n.endswith((".mp4", ".jpg")):
				dt = parse_stamp(n)
				if dt is not None and dt.strftime("%Y-%m-%d") == day:
					out["events"].append(dt.hour * 60 + dt.minute)
	except OSError:
		pass
	out["events"] = sorted(set(out["events"]))
	return out



EXT = {"proc": None, "ff": None, "msg": "", "port": None}


def ext_token():
	if not re.fullmatch(r"[A-Za-z0-9_-]{20,64}", CFG["ext_token"] or ""):
		CFG["ext_token"] = secrets.token_urlsafe(18); save_settings()
	return CFG["ext_token"]


def ext_new_token():
	CFG["ext_token"] = secrets.token_urlsafe(18); save_settings(); rtsp_restart()
	log_event("web", "Address for other programs renewed - the old one no longer works")


def ext_links(host=None):
	if not CFG["ext_on"]:
		return {"on": False}
	base = page_address(host).rstrip("/") if host or page_address() else f"http://<pi-ip>:{CFG['web_port']}"
	tok = ext_token()
	out = {"on": True, "mjpeg": f"{base}/x/{tok}/video.mjpg", "jpg": f"{base}/x/{tok}/snapshot.jpg", "rtsp": "", "rtsp_msg": EXT["msg"]}
	if CFG["rtsp_on"]:
		h = base.split("://", 1)[-1].split("/", 1)[0].rsplit(":", 1)[0]
		out["rtsp"] = f"rtsp://motionwatch:{tok}@{h}:{int(CFG['rtsp_port'])}/motionwatch"
	return out


def _mediamtx_bin():
	for p in (shutil.which("mediamtx"), os.path.join(DATA_DIR, "mediamtx", "mediamtx"), os.path.expanduser("~/mediamtx/mediamtx"), "/usr/local/bin/mediamtx"):
		if p and os.path.isfile(p) and os.access(p, os.X_OK):
			return p
	return None


def rtsp_stop():
	for k in ("ff", "proc"):
		p = EXT.get(k)
		if p is not None:
			try:
				p.terminate(); p.wait(timeout=5)
			except Exception:
				try:
					p.kill()
				except Exception:
					pass
		EXT[k] = None


def rtsp_restart():
	rtsp_stop()
	if CFG["rtsp_on"] and CFG["ext_on"]:
		threading.Thread(target=rtsp_start, daemon=True, name="rtsp").start()


def rtsp_start():
	""
	mtx = _mediamtx_bin()
	if not mtx:
		EXT["msg"] = "mediamtx is not installed (see the manual: RTSP)"; return
	if not shutil.which("ffmpeg"):
		EXT["msg"] = "ffmpeg is missing (sudo apt install ffmpeg)"; return
	tok = ext_token(); port = int(CFG["rtsp_port"])
	cfg_dir = os.path.join(DATA_DIR, "mediamtx"); os.makedirs(cfg_dir, exist_ok=True)
	yml = os.path.join(cfg_dir, "motionwatch.yml")
	with open(yml, "w") as f:
		f.write("logLevel: warn\nrtspAddress: :%d\nrtmp: no\nhls: no\nwebrtc: no\nsrt: no\napi: no\nmetrics: no\npprof: no\nplayback: no\n"
				"authInternalUsers:\n- user: any\n  pass:\n  ips: ['127.0.0.1/32', '::1/128']\n  permissions:\n  - action: publish\n"
				"- user: motionwatch\n  pass: %s\n  ips: []\n  permissions:\n  - action: read\n    path: motionwatch\n"
				"paths:\n  motionwatch:\n" % (port, tok))
	os.chmod(yml, 0o600)
	try:
		EXT["proc"] = subprocess.Popen([mtx, yml], stdout=subprocess.DEVNULL, stderr=subprocess.PIPE, cwd=cfg_dir)
	except OSError as e:
		EXT["msg"] = f"mediamtx: {e}"[:120]; return
	time.sleep(2)
	if EXT["proc"].poll() is not None:
		err = (EXT["proc"].stderr.read() or b"").decode(errors="replace").strip().splitlines()
		EXT["msg"] = ("mediamtx: " + (err[-1] if err else "stopped"))[:160]; EXT["proc"] = None; return
	src = f"http://127.0.0.1:{CFG['web_port']}/x/{tok}/video.mjpg"
	if WEB_OPTS.get("https"):
		src = src.replace("http://", "https://")
	cmd = ["ffmpeg", "-loglevel", "error", "-tls_verify", "0", "-f", "mjpeg", "-i", src, "-an", "-c:v", "libx264", "-preset", "ultrafast",
		   "-tune", "zerolatency", "-g", "30", "-pix_fmt", "yuv420p", "-f", "rtsp", "-rtsp_transport", "tcp", f"rtsp://127.0.0.1:{port}/motionwatch"]
	if not WEB_OPTS.get("https"):
		cmd.remove("-tls_verify"); cmd.remove("0")
	try:
		EXT["ff"] = subprocess.Popen(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
		EXT["msg"] = "running"
		log_event("web", f"RTSP video on port {port} (for recorders)")
	except OSError as e:
		EXT["msg"] = f"ffmpeg: {e}"[:120]


def rtsp_watch():
	""
	while True:
		time.sleep(15)
		want = CFG["rtsp_on"] and CFG["ext_on"]
		alive = EXT["proc"] is not None and EXT["proc"].poll() is None and EXT["ff"] is not None and EXT["ff"].poll() is None
		if want and not alive:
			rtsp_restart()
		elif not want and (EXT["proc"] or EXT["ff"]):
			rtsp_stop(); EXT["msg"] = ""


atexit.register(rtsp_stop)


def mem_info():
	""
	m = {}
	try:
		with open("/proc/meminfo") as f:
			for line in f:
				k, v = line.split(":", 1); m[k] = int(v.split()[0]) // 1024
	except (OSError, ValueError):
		return None
	tot = m.get("MemTotal") or 0; avail = m.get("MemAvailable", m.get("MemFree", 0))
	if not tot:
		return None
	return {"total": tot, "used": tot - avail, "pct": round((tot - avail) * 100.0 / tot, 1), "swap": (m.get("SwapTotal", 0) - m.get("SwapFree", 0))}


def rec_dir():
	return os.path.abspath(CFG["record_dir"])










TL_ALARM_KINDS = ("person", "alarm", "tamper")


def timeline_window(day=None, mode="night"):
	""
	try:
		d = datetime.strptime(str(day or "")[:10], "%Y-%m-%d")
	except ValueError:
		d = datetime.now()
	d = d.replace(hour=0, minute=0, second=0, microsecond=0)
	if mode == "day":
		return d, d + timedelta(days=1)
	return d - timedelta(hours=6), d + timedelta(hours=9)


def _tl_days(a, b):
	out, d = [], a.replace(hour=0, minute=0, second=0, microsecond=0)
	while d < b:
		out.append(d.strftime("%Y-%m-%d")); d += timedelta(days=1)
	return out


def _tl_log(a, b, limit=400):
	""
	import gzip
	files = []
	for day in _tl_days(a, b):
		try:
			files += sorted(os.path.join(log_dir(), f) for f in os.listdir(log_dir())
							if LOG_NAME_RE.match(f) and f[12:22] == day)
		except OSError:
			pass
	if os.path.isfile(LOG_FILE):
		files.append(LOG_FILE)
	sa, sb = a.strftime("%Y-%m-%d %H:%M:%S"), b.strftime("%Y-%m-%d %H:%M:%S")
	out, seen, rep_ = [], set(), {}
	for p in files:
		try:
			if p.endswith(".gz"):
				with gzip.open(p, "rt", encoding="utf-8", errors="replace") as f:
					lines = f.read().splitlines()
			else:
				with open(p, "rb") as f:
					f.seek(0, 2); size = f.tell(); f.seek(max(0, size - 6 * 1024 * 1024))
					lines = f.read().decode("utf-8", "replace").splitlines()
		except OSError:
			continue
		for ln in lines:
			m = LOG_LINE_RE.match(ln)
			if not m:
				continue
			ts = m.group(1) + " " + m.group(2)
			if not (sa <= ts < sb):
				continue
			kind, text = m.group(3), m.group(4)
			if kind == "status" or text.startswith(("Diary: ", "Recording started")):
				continue
			if not (kind in TL_ALARM_KINDS or log_important(kind, text)):
				continue
			key = (ts, kind, text)
			if key in seen:
				continue
			seen.add(key)
			try:
				t = datetime.strptime(ts, "%Y-%m-%d %H:%M:%S").timestamp()
			except ValueError:
				continue
			first = rep_.get((kind, text))
			if first is not None and kind not in TL_ALARM_KINDS:
				first["n"] = first.get("n", 1) + 1; first["t_last"] = t
				continue
			e = {"t": t, "type": "log", "kind": kind, "text": text[:300], "alarm": kind in TL_ALARM_KINDS}
			rep_[(kind, text)] = e
			out.append(e)
	out.sort(key=lambda x: x["t"])
	return out[-limit:]


def _tl_recordings(a, b):
	out, off = [], 0
	args = {"from": a.strftime("%Y-%m-%d"), "to": (b - timedelta(seconds=1)).strftime("%Y-%m-%d"), "sort": "old", "limit": 200}
	while off < 1000:
		args["offset"] = off
		try:
			r = list_recordings(args, WATCH_REF.get("w"))
		except Exception as e:
			log_event("sys", f"Timeline: recordings {e}"[:160])
			break
		for it in r.get("items") or []:
			if it.get("timelapse"):
				continue
			try:
				t = datetime.strptime(it["time"], "%Y-%m-%d %H:%M:%S")
			except (KeyError, ValueError):
				continue
			if a <= t < b:
				out.append({"t": t.timestamp(), "type": "rec", "name": it["name"], "kind": it["kind"], "snap": it.get("snap"),
							"dur": it.get("duration"), "persons": it.get("persons"), "false": it.get("false"), "fav": it.get("fav"),
							"src": it.get("source") or "", "live": bool(it.get("recording"))})
		off += 200
		if off >= int(r.get("total") or 0):
			break
	return out


def _tl_sightings(a, b, lang):
	sight_load()
	sa, sb = a.isoformat(timespec="seconds"), b.isoformat(timespec="seconds")
	with SIGHT_LOCK:
		lst = [dict(e) for e in SIGHT["list"] if sa <= e.get("start", "") < sb]
	out = []
	for e in lst:
		try:
			t = datetime.fromisoformat(e["start"]).timestamp()
		except ValueError:
			continue
		out.append({"t": t, "type": "sight", "id": e.get("id"), "label": e.get("label"), "name": tr_trigger(e.get("label", ""), lang),
					"kind": e.get("kind"), "dur": e.get("dur"), "img": e.get("img") or "", "conf": e.get("conf")})
	return out


def _tl_messages(a, b):
	ta, tb = a.timestamp(), b.timestamp()
	out = []
	for m in msglog_list(MSGLOG_MAX):
		t = float(m.get("t") or 0)
		if ta <= t < tb:
			out.append({"t": t, "type": "msg", "id": m.get("id"), "ev": m.get("ev"), "title": m.get("title"), "text": m.get("text"),
						"status": m.get("status"), "img": bool(m.get("img"))})
	return out


def _tl_series(a, b):
	""
	clim, wx = [], []
	for day in _tl_days(a, b):
		for row in climate_day(day):
			try:
				t = datetime.strptime(day + " " + str(row[0]), "%Y-%m-%d %H:%M")
			except (ValueError, TypeError, IndexError):
				continue
			if a <= t < b:
				r = list(row) + [None] * 6
				clim.append({"t": t.timestamp(), "temp": r[1], "hum": r[2], "cpu": r[4], "bat": r[5]})
		w = weather_day(day) or {}
		for hh, v in sorted((w.get("hourly") or {}).items()):
			try:
				t = datetime.strptime(day + " " + hh, "%Y-%m-%d %H")
			except ValueError:
				continue
			if a <= t < b and isinstance(v, list):
				v = list(v) + [None] * 5
				ic = ""
				try:
					ic = wmo_text(v[3])[0] if v[3] is not None else ""
				except Exception:
					pass
				wx.append({"t": t.timestamp(), "temp": v[0], "rain": v[1], "hum": v[2], "code": v[3], "gust": v[4], "icon": ic})
	return clim, wx


def timeline_build(day=None, mode="night", lang=None):
	L = norm_lang(lang) if lang else cur_lang()
	mode = "day" if mode == "day" else "night"
	a, b = timeline_window(day, mode)
	items = []
	for fn in (lambda: _tl_recordings(a, b), lambda: _tl_messages(a, b), lambda: _tl_sightings(a, b, L), lambda: _tl_log(a, b)):
		try:
			items += fn()
		except Exception as e:
			log_event("sys", f"Timeline: {type(e).__name__}: {e}"[:160])
	items.sort(key=lambda x: x["t"])
	try:
		clim, wx = _tl_series(a, b)
	except Exception:
		clim, wx = [], []
	cnt = {"rec": 0, "msg": 0, "sight": 0, "log": 0, "alarm": 0, "animal": 0, "false": 0}
	for it in items:
		cnt[it["type"]] += 1
		if it["type"] == "log" and it.get("alarm"):
			cnt["alarm"] += 1
		if it["type"] == "sight" and it.get("kind") == "animal":
			cnt["animal"] += 1
		if it["type"] == "rec" and it.get("false"):
			cnt["false"] += 1
	bats = [c["bat"] for c in clim if c.get("bat") is not None]
	temps = [c["temp"] for c in clim if c.get("temp") is not None] or [w["temp"] for w in wx if w.get("temp") is not None]
	return {"ok": True, "mode": mode, "day": a.strftime("%Y-%m-%d") if mode == "day" else (a + timedelta(hours=6)).strftime("%Y-%m-%d"),
			"start": a.timestamp(), "end": b.timestamp(), "now": time.time(), "items": items[-1500:], "climate": clim, "weather": wx,
			"count": cnt, "bat": {"first": bats[0], "last": bats[-1], "min": min(bats)} if bats else None,
			"temp": {"min": min(temps), "max": max(temps)} if temps else None,
			"env": bool(CFG.get("env_on")), "weather_on": bool(CFG.get("weather_on"))}


def timeline_text(tl, lang=None):
	""
	L = norm_lang(lang) if lang else cur_lang()
	out = []
	for it in tl["items"]:
		hm = datetime.fromtimestamp(it["t"]).strftime("%H:%M")
		ty = it["type"]
		if ty == "rec":
			s = ("🎬 " if it["kind"] == "video" else "📷 ") + tr("Recording", L) + (f" · {it['dur']:.0f} s" if it.get("dur") else "")
			if it.get("false"):
				s += " · " + tr("false alarm", L)
			out.append((hm, "rec", s, it))
		elif ty == "msg":
			out.append((hm, "msg", "✉ " + (it.get("title") or "MoveEye") + " – " + str(it.get("text") or "")[:120], it))
		elif ty == "sight":
			out.append((hm, "sight", ("🦊 " if it.get("kind") == "animal" else "👤 ") + str(it.get("name") or it.get("label")) +
						(f" · {it['dur']} s" if it.get("dur") else ""), it))
		else:
			out.append((hm, "alarm" if it.get("alarm") else "log", ("🚨 " if it.get("alarm") else "• ") + it["text"] +
						(f" (× {it['n']})" if it.get("n", 1) > 1 else ""), it))
	return out












WEEKREP = {"last": None}
WEEKDAYS_EN = ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday")
_WR_ALARM_EV = ("person", "tamper", "warm", "noise")
WR_CAUSES = {"animal": "Animal", "wind": "Wind / branches", "light": "Light / shadow", "rain": "Rain", "car": "Car", "other": "Other"}


def _wr_recs(a, b):
	""
	n, nf, causes = 0, 0, {}
	try:
		names = os.listdir(rec_dir())
	except OSError:
		names = []
	stems = {}
	for nm in names:
		st_, ext = os.path.splitext(nm)
		if ext.lower() in (".mp4", ".jpg") and REC_NAME_RE.match(nm):
			stems.setdefault(st_, nm if ext.lower() == ".mp4" else stems.get(st_, nm))
	for st_, nm in stems.items():
		dt = parse_stamp(nm)
		if dt is None or not (a <= dt < b):
			continue
		n += 1
		c = _read_sidecar(nm).get("false")
		if c:
			nf += 1; causes[c] = causes.get(c, 0) + 1
	return n, nf, causes


def _wr_tests(a, b):
	runs = [r for r in (TESTOPT.get("runs") or []) if a.timestamp() <= float(r.get("t") or 0) < b.timestamp() and r.get("score") is not None]
	if not runs:
		return {"n": 0}
	rep = [r.get("report") or {} for r in runs]
	pers = sum(int(x.get("persons") or 0) for x in rep); found = sum(int(x.get("persons_detected") or 0) for x in rep)
	return {"n": len(runs), "score": round(sum(float(r["score"]) for r in runs) / len(runs), 1),
			"found": found, "persons": pers, "rate": round(100.0 * found / pers) if pers else None,
			"fa": sum(int(x.get("false_alarms") or 0) for x in rep), "last": runs[-1].get("score"), "mw": runs[-1].get("mw")}


def _wr_sim(a, b):
	try:
		vs = simdiary_read(None, max(1, (datetime.now() - a).days + 2))
	except Exception:
		vs = []
	seen = rec = 0
	miss_kinds = {}
	for v in vs:
		try:
			t = float(v.get("t_in") or 0)
		except (TypeError, ValueError):
			continue
		if not (a.timestamp() <= t < b.timestamp()) or str(v.get("kind")) not in SIM_PERSON_KINDS or float(v.get("vis_s") or 0) < 2:
			continue
		seen += 1
		if v.get("detected"):
			rec += 1
		else:
			k = str(v.get("kind")); miss_kinds[k] = miss_kinds.get(k, 0) + 1
	return {"seen": seen, "rec": rec, "missed": seen - rec, "rate": round(100.0 * rec / seen) if seen else None,
			"miss_kinds": sorted(miss_kinds.items(), key=lambda kv: -kv[1])[:3]}


def _wr_msgs(a, b):
	ta, tb = a.timestamp(), b.timestamp()
	return sum(1 for m in msglog_list(MSGLOG_MAX) if ta <= float(m.get("t") or 0) < tb and m.get("ev") in _WR_ALARM_EV and m.get("status") != "test")


def _wr_trend(cur, prev, better_up=True):
	""
	if cur is None or prev is None:
		return ""
	d = cur - prev
	if abs(d) < 1e-9:
		return "→"
	return ("↑" if d > 0 else "↓") + (" ✓" if (d > 0) == better_up else " ⚠")


def weekrep_build(lang=None, now=None):
	""
	L = norm_lang(lang) if lang else cur_lang()
	now = now or datetime.now()
	a = now - timedelta(days=7); p = a - timedelta(days=7)
	T, Tp = _wr_tests(a, now), _wr_tests(p, a)
	R, Rp = _wr_recs(a, now), _wr_recs(p, a)
	S, Sp = _wr_sim(a, now), _wr_sim(p, a)
	M, Mp = _wr_msgs(a, now), _wr_msgs(p, a)
	weeks = []
	for i in range(5, -1, -1):
		e = now - timedelta(days=7 * i); s = e - timedelta(days=7)
		w = _wr_tests(s, e)
		weeks.append({"wk": s.strftime("%d.%m."), "score": w.get("score"), "n": w.get("n", 0)})
	lines = []
	if T["n"]:
		lines.append(trf("Test runs: {n}, score {s} {tr} (week before {p}), persons found {f} of {a}, false alarms {fa}", L,
						 n=T["n"], s=T["score"], tr=_wr_trend(T["score"], Tp.get("score")), p=Tp.get("score", "–"),
						 f=T["found"], a=T["persons"], fa=T["fa"]))
	else:
		lines.append(tr("Test runs: none this week", L))
	lines.append(trf("Recordings: {n} (week before {p}), marked as false alarm: {f} {tr}", L,
					 n=R[0], p=Rp[0], f=R[1], tr=_wr_trend(R[1], Rp[1], better_up=False)) +
				 ((" (" + ", ".join(f"{tr(WR_CAUSES.get(k, k), L)} {v}" for k, v in sorted(R[2].items(), key=lambda kv: -kv[1])) + ")") if R[2] else ""))
	lines.append(trf("Alarm messages: {n} (week before {p})", L, n=M, p=Mp))
	sim_on = bool(CFG.get("weekrep_sim", True))
	SW = weekrep_simweek(a, now, L) if sim_on else None
	if SW and SW["visits"]:
		lines.append(trf("Week in the simulator: {v} visits. Animals: {an}", L, v=SW["visits"], an=SW["animals"] or "–"))
	if sim_on and S["seen"]:
		lines.append(trf("Simulator diary: persons recognised {r} % ({a} of {b}) {tr}, missed {m}", L,
						 r=S["rate"], a=S["rec"], b=S["seen"], tr=_wr_trend(S["rate"], Sp.get("rate")), m=S["missed"]) +
					 ((" – " + ", ".join(f"{tr_trigger(k, L)} {v}" for k, v in S["miss_kinds"])) if S["miss_kinds"] else ""))
	tip, link = weekrep_tip(L, T, Tp, R, S, now)
	text = "\n".join(lines) + "\n💡 " + tip
	return {"t": now.isoformat(timespec="seconds"), "from": a.strftime("%d.%m."), "to": now.strftime("%d.%m."),
			"tests": T, "tests_prev": Tp, "recs": {"n": R[0], "false": R[1], "causes": R[2]}, "recs_prev": {"n": Rp[0], "false": Rp[1]},
			"msgs": M, "msgs_prev": Mp, "sim": S, "sim_prev": Sp, "simweek": SW, "with_sim": sim_on, "weeks": weeks, "lines": lines, "tip": tip, "link": link, "text": text,
			"on": bool(CFG.get("weekrep_on")), "day": CFG.get("weekrep_day"), "hour": int(CFG.get("weekrep_hour", 18)),
			"last": WEEKREP["last"]}


def weekrep_simweek(a, b, L=None):
	""
	try:
		st = simdiary_stats(max(1, (b - a).days))
	except Exception:
		return None
	vis = sum(int(x.get("visits") or 0) for x in st.get("days") or [])
	an = ", ".join(f"{tr_trigger(k['k'], L)} {k['n']}" for k in st.get("kinds") or [] if k.get("animal"))[:120]
	return {"visits": vis, "animals": an}


def weekrep_tip(L, T, Tp, R, S, now):
	""
	if R[1] >= 2:
		try:
			sg = fa_suggestions(L, 7)["suggestions"]
		except Exception:
			sg = []
		if sg:
			return trf("{n} false alarms this week. Suggestion: {s} (History → Recordings → false alarms)", L, n=R[1], s=sg[0]["text"]), "/recordings"
		return trf("{n} false alarms this week. Draw an ignore zone over what moves (trees, road) – tab Protection → Zones.", L, n=R[1]), "/zones"
	if S["missed"] >= 2 and CFG.get("weekrep_sim", True):
		return trf("In the simulator {n} persons were in the picture but not recognised. Run the test «Night» and the automatic optimization (Simulator → Testing → Tests).", L, n=S["missed"]), "/sim"
	if T["n"] and Tp.get("score") is not None and T["score"] <= Tp["score"] - 5:
		return tr("The test score went down. Look at what changed in the settings (Simulator → Testing → Tests, «undo»).", L), "/sim"
	if not T["n"]:
		return tr("No test run this week: switch on the nightly test run (Simulator → Testing → Tests) – then you see the trend here.", L), "/sim"
	if not R[0]:
		return tr("A quiet week. Check now and then that the camera still looks at the right place (Live).", L), "/"
	tips = ["Mark wrong alarms with «Was nothing» – MoveEye learns from them and suggests better settings.",
			"Star (★) important recordings: they are never deleted automatically.",
			"«Guard tonight» on the tab Protection sets everything for the night in one tap.",
			"The timeline (History → Timeline) shows a whole night at a glance."]
	return tr(tips[int(now.strftime("%V")) % len(tips)], L), "/timeline"


def weekrep_send(manual=False):
	r = weekrep_build()
	w = WATCH_REF.get("w")
	ok = False
	if w is not None and Notifier.configured() and CFG["notify_on"]:
		pub = CFG["public_url"].strip().rstrip("/")
		ok = bool(w.notifier.info(r["text"], pub + "/timeline" if pub else "", title="{name}: " + tr("Weekly detection report")))
	WEEKREP["last"] = {"t": datetime.now().isoformat(timespec="seconds"), "sent": ok, "manual": manual}
	log_event("sys", ("Weekly detection report sent" if ok else "Weekly detection report not sent (no push channel)") + (" (by hand)" if manual else ""))
	return r, ok


def weekrep_due(now):
	if not CFG.get("weekrep_on"):
		return False
	day = CFG.get("weekrep_day") if CFG.get("weekrep_day") in WEEKDAYS_EN else "Sunday"
	if now.weekday() != WEEKDAYS_EN.index(day) or now.hour < int(CFG.get("weekrep_hour", 18)) or now.hour > int(CFG.get("weekrep_hour", 18)) + 3:
		return False
	return CFG.get("weekrep_last") != now.strftime("%G-W%V")


def weekrep_loop():
	while True:
		time.sleep(60)
		try:
			now = datetime.now()
			if weekrep_due(now):
				CFG["weekrep_last"] = now.strftime("%G-W%V")
				save_settings()
				weekrep_send()
		except Exception as e:
			log_event("sys", f"Weekly detection report: {e}"[:150])


threading.Thread(target=weekrep_loop, daemon=True, name="weekrep").start()


