def guide_seen():
	try:
		v = json.loads((CFG.get("web_ui") or {}).get("mw-tips-seen") or "[]")
		return set(v) if isinstance(v, list) else set()
	except (TypeError, ValueError):
		return set()


def guide_level():
	lv = CFG.get("tips_level") or "normal"
	return TIPS_LEVELS.index(lv) if lv in TIPS_LEVELS else 2


def guide_tip_for(key):
	""
	if guide_level() == 0 or key in guide_seen():
		return None
	for k, lv, _v, te, xe, td, xd in GUIDE_TIPS:
		if k == key and lv <= guide_level():
			L = cur_lang()
			return (td, xd) if L == "de" else (tr(te, L), tr(xe, L))
	return None


def guide_mark_seen(key):
	s = guide_seen()
	if key in s:
		return
	s.add(key)
	CFG.setdefault("web_ui", {})["mw-tips-seen"] = json.dumps(sorted(s)[-400:])
	save_settings()


def guide_js(active):
	data = {"active": active, "level": guide_level(), "ver": APP_VERSION,
			"tips": [{"k": k, "l": lv, "v": v, "te": te, "xe": xe, "td": td, "xd": xd} for k, lv, v, te, xe, td, xd in GUIDE_TIPS],
			"ui": GUIDE_UI}
	g2 = {"page": g2_page_key(active), "tourAuto": bool(CFG.get("tours_auto", True)), "tourPages": sorted(G2_TOURS),
		  "setupDone": bool(CFG["setup_done"]), "guide": {k: (CFG.get("guide2") or {}).get(k) for k in ("mode", "paused", "finished", "step")},
		  "simple": bool(CFG.get("ui_simple")), "lock": bool(CFG.get("lock_on"))}
	return ("window.MW_GUIDE=" + json.dumps(data, ensure_ascii=False).replace("</", "<\\/") + ";\n"
			+ "window.MW_G2B=" + json.dumps(g2, ensure_ascii=False).replace("</", "<\\/") + ";\n" + GUIDE_JS + G2_LOADER_JS)


