def web_specs():
	""
	specs = {}
	for sec, key, label in TOGGLES:
		if key != "web_stream":
			specs[key] = {"type": "bool"}
	for sec, key, label, lo, hi, step in SLIDERS:
		specs[key] = {"type": "num", "min": lo, "max": hi, "step": step}
	return specs


SECTIONS_ON_SIM_PAGE = ("Simulator",)
SECTIONS_OWN_CONTENT = {"Security"}




def schema_for_admin():
	""
	try:
		from flask import g, has_request_context
		return (not has_request_context()) or getattr(g, "role", "admin") == "admin"
	except Exception:
		return True


def web_schema(lang=None, only=None):
	""
	out = []
	for sec in SECTIONS:
		if only is not None:
			if sec != only:
				continue
			hid = lambda k, s_=None: False
		else:
			if sec in SECTIONS_ON_SIM_PAGE:
				continue
			hid = simple_hidden
		if hid(None, sec):
			continue
		toggles = [{"key": k, "label": tr(l, lang), "value": bool(CFG.get(k))} for s, k, l in TOGGLES if s == sec and k != "web_stream" and not hid(k)]
		sliders = [{"key": k, "label": tr(l, lang), "min": lo, "max": hi, "step": st, "value": CFG.get(k)} for s, k, l, lo, hi, st in SLIDERS if s == sec and not hid(k)]
		texts = [x for x in web_texts(lang) if x["section"] == sec and not hid(x["key"])]
		if toggles or sliders or texts or (sec in SECTIONS_OWN_CONTENT and schema_for_admin()):
			out.append({"id": sec, "name": tr(sec, lang), "toggles": toggles, "sliders": sliders, "texts": texts})
	return out


def set_cfg(key, value):
	""
	spec = web_specs().get(key)
	if spec is None:
		return False, "unknown setting"
	if spec["type"] == "bool":
		CFG[key] = bool(value)
		if key == "update_unsigned":
			CFG["update_unsigned_t"] = time.time() if CFG[key] else 0.0
		sched_user_changed(key)
		save_settings()
		if key == "patrol":
			log_event("patrol", "Patrol switched ON (web)" if CFG[key] else "Patrol switched OFF (web)")
		_set_cfg_sim(key)
		return True, ""
	try:
		v = float(value)
	except (TypeError, ValueError):
		return False, "not a number"
	if not math.isfinite(v):
		return False, "not a number"
	v = max(spec["min"], min(spec["max"], v))
	v = round(round(v / spec["step"]) * spec["step"], 2)
	CFG[key] = int(round(v)) if isinstance(CFG[key], int) else float(v)
	save_settings()
	_set_cfg_sim(key)
	return True, ""


def _set_cfg_sim(key):
	""
	if key == "sim_autoupd" and CFG.get("sim_on") and sim_ready():
		threading.Thread(target=simupd_push, args=(bool(CFG["sim_autoupd"]),), daemon=True, name="simupd").start()















def servo_client(request, d=None):
	"""
"""
	import hashlib
	try:
		from flask import g
		user = str(getattr(g, "user", "") or "")
	except Exception:
		user = ""
	ua = str(request.headers.get("User-Agent") or "")
	ip = str(request.remote_addr or "?")
	if "Godot" in ua or "MoveEye-Sim" in ua:
		dev = tr("Simulator")
	else:
		dev = ("iPhone" if "iPhone" in ua else "iPad" if "iPad" in ua else "Android" if "Android" in ua else "Mac" if "Macintosh" in ua
			   else "Windows-PC" if "Windows" in ua else "Linux-PC" if "Linux" in ua else tr("Browser"))
	br = ("Edge" if "Edg/" in ua else "Firefox" if "Firefox/" in ua else "Chrome" if "Chrome/" in ua or "CriOS" in ua
		  else "Safari" if "Safari/" in ua else "")
	where = tr("this computer") if ip.startswith("127.") or ip == "::1" else "…" + (ip.split(".")[-1] if "." in ip else ip[-4:])
	label = dev + (" · " + br if br else "") + f" ({where})" + (" · " + user if user else "")
	if isinstance(d, dict) and d.get("via") == "pad":
		label += " 🎮"
	key = hashlib.sha1((ip + "|" + ua).encode("utf-8", "replace")).hexdigest()[:10]
	return key, label[:60]


def servo_client_state(request, lang=None):
	""
	key, label = servo_client(request)
	drv = servo_driver(lang)
	return {"blocked": servo_blocked(), "text": servo_blocked_text(lang), "estop": bool(CFG.get("servo_estop")),
			"estop_by": CFG.get("servo_estop_by") or "", "driver": drv, "me": key, "mine": bool(drv.get("key")) and drv.get("key") == key,
			"me_label": label, "moving": bool(SRV["moving"]), "deg": [round(x, 1) for x in servo_pos_deg()],

			"stop_btn": bool(CFG.get("servo_stop_btn", True)) and bool(globals().get("live_has_head", lambda: True)()),
			"sim": bool(CFG.get("sim_on"))}


