		@app.route("/api/audio/live")
		def api_audio_live():
			""
			if AUDIO is None or (AUDIO.proc is None and time.time() - AUDIO.sim_t > 3.0):
				return reply({"ok": False, "error": "no microphone"}, 404)
			q = AUDIO.listen()

			def gen():
				try:
					while True:
						try:
							yield q.get(timeout=1.0)
						except queue.Empty:
							if AUDIO.proc is None and not CFG["audio_in"] and time.time() - AUDIO.sim_t > 3.0:
								break
							yield bytes(AUDIO_CHUNK * 2)
				finally:
					AUDIO.unlisten(q)
			return Response(gen(), mimetype="application/octet-stream",
							headers={"Cache-Control": "no-store", "X-Audio-Rate": str(AUDIO_RATE), "X-Accel-Buffering": "no"})

