	ttk.Button(bf, text="▦ QR", command=lambda: qr_tk_dialog(win, key, tr("App key") + " «" + name + "»", True)).pack(side="left", padx=(0, 4))
	ttk.Button(bf, text=tr("Done"), command=win.destroy).pack(side="left", expand=True, fill="x")


