def sx_req_lang():
	"""
"""
	try:
		from flask import request
		q = str(request.args.get("lang") or "")[:2].lower()
		if q in LANGS:
			return q
		for part in str(request.headers.get("Accept-Language") or "").split(","):
			c = part.strip()[:2].lower()
			if c in LANGS:
				return c
			if c == "gs":
				return "de"
	except Exception:
		pass
	return cur_lang()


