def factory_backup_when(name):
	"""
"""
	m = _BACKUP_RE.match(str(name or ""))
	if not m:
		return None
	try:
		return datetime.strptime(m.group(1), "%Y%m%d-%H%M%S").strftime("%d.%m.%Y %H:%M")
	except ValueError:
		return None


def factory_backups():
	try:
		names = sorted((n for n in os.listdir(DATA_DIR) if _BACKUP_RE.match(n)), reverse=True)
	except OSError:
		names = []
	out = []
	for n in names:
		if len(out) >= 10:
			break
		when = factory_backup_when(n)
		if when is None:
			continue
		try:
			out.append({"name": n, "kb": max(1, os.path.getsize(os.path.join(DATA_DIR, n)) // 1024), "when": when})
		except OSError:
			pass
	return out


def factory_admin():
	"""
"""
	try:
		from flask import g
		return getattr(g, "role", "admin") == "admin" and not getattr(g, "appkey", None)
	except (ImportError, RuntimeError):
		return True


def factory_backup_path(name):
	n = os.path.basename(str(name or ""))
	p = os.path.join(DATA_DIR, n)
	return p if _BACKUP_RE.match(n) and os.path.isfile(p) else None


