def _help_sd(doc, lang):
	if '<section id="sdcard"' in doc:
		return doc
	i = doc.find('<section id="tips"')
	if i < 0:
		i = doc.find('<section id="privacy"')
	return doc[:i] + _HELP_SD[lang] + doc[i:] if i >= 0 else doc


