def _help_platzein(doc, lang):
	if '<section id="place"' in doc:
		return doc
	i = doc.find('<section id="tips"')
	if i < 0:
		i = doc.find('<section id="privacy"')
	return doc[:i] + _HELP_PLATZEIN[lang] + doc[i:] if i >= 0 else doc


