_PK_PH = re.compile(r"\{(\w+)(?::[^}]*)?\}")
_PK_SIM = re.compile(r"\s*\(🧪[^)]*\)|\s*🧪\s*")




_PK_MAP = re.compile(r"(?:https?://(?:www\.)?(?:openstreetmap\.org|osm\.org|maps\.google\.[a-z.]+|google\.[a-z.]+/maps|maps\.apple\.com)/\S*"
					 r"|geo:-?\d[\d.,;=a-z-]*)", re.I)


def push_map(p):
	""
	m = str(p.get("map") or "").strip()
	if m:
		return m
	if Notifier._event(p) not in ("info", "tamper"):
		return ""
	x = _PK_MAP.search(str(p.get("text") or ""))
	return x.group(0).rstrip(".,;") if x else ""


def _pk_nomap(text):
	""
	s = _PK_MAP.sub(" ", str(text or ""))
	labs = "|".join(re.escape(x) for x in dict.fromkeys((tr("Position"), "Position")))
	s = re.sub(r"(?:\s*[·,\-–]\s*|\s+)(?:" + labs + r")\s*:\s*$", "", s.rstrip())
	return s.rstrip(" :·-–,.")


def push_map_line():
	""
	return (("📍 " if CFG.get("msg_icons", True) else "") + pk_tr("Open map"))


def push_with_map(text, p, sep="\n"):
	""
	m = push_map(p)
	return (str(text or "") + sep + ("📍 " if CFG.get("msg_icons", True) else "") + m) if m else str(text or "")


def push_sms_text(title, text, p):
	""
	m = push_map(p)
	head = " ".join((str(title or "") + ": " + str(text or "")).split())
	if not m:
		return head
	room = 300 - len(m) - 1
	if len(head) > room:
		head = head[:max(0, room - 1)].rstrip() + "…"
	return (head + " " + m).strip()


def push_url_is_ntfy(url):
	""
	try:
		from urllib.parse import urlsplit
		host = urlsplit(str(url or "").strip()).hostname or ""
	except ValueError:
		return False
	host = host.lower().rstrip(".")


	if host in ("ntfy", "ntfy.sh", "ntfy-me.com") or host.endswith((".ntfy.sh", ".ntfy-me.com")):
		return True
	return host.startswith("ntfy.") or ".ntfy." in host


def pk_line(s, n=None):
	""
	n = n or PK_MAX
	s = " · ".join(x.strip() for x in str(s or "").splitlines() if x.strip())
	s = " ".join(re.sub(r"[\x00-\x1f\x7f]", " ", s).split())
	if len(s) <= n:
		return s
	cut = s[:n - 1]
	sp = cut.rfind(" ")
	return (cut[:sp] if sp > n * 0.6 else cut).rstrip(" ,;:-–·") + "…"


def pk_tr(text):
	"""
"""
	v = _HX_PK.get(text)
	L = cur_lang()
	if v is None or L == "en":
		return tr(text)
	return v[{"de": 0, "fr": 1, "it": 2, "rm": 3}.get(L, 0)] if L in ("de", "fr", "it", "rm") else text


def pk_trf(text, **kw):
	try:
		return pk_tr(text).format(**kw)
	except (KeyError, IndexError, ValueError):
		return text.format(**kw)


def _pk_tpl(t):
	""
	return (tr(t[0]) + t[1], t[0] + t[1]) if isinstance(t, tuple) else (tr(t), t)


def _pk_match(tpl, text):
	""
	parts = _PK_PH.split(tpl)
	rx = "^"
	for i, s_ in enumerate(parts):
		if i % 2 == 0:
			rx += re.escape(s_)
		else:
			rx += "(?P<%s>.+)" % s_ if (i == len(parts) - 2 and parts[-1] == "") else "(?P<%s>.+?)" % s_
	m = re.match(rx + ("" if parts[-1] == "" else ".*") + "$", text, re.S)
	return m.groupdict() if m else None


def _pk_fill(tpl, vals):
	return re.sub(r"\{(\w+)\}", lambda m: str(vals.get(m.group(1), "")).strip(), tpl)


def _pk_cut(text):
	""
	lines = [x.strip() for x in str(text or "").strip().splitlines() if x.strip()] or [""]
	s = lines[0]
	if s.endswith(":") and len(lines) > 1:
		return s + " " + " · ".join(lines[1:])
	for sep in (" - ", " – ", ". "):
		i = s.find(sep)
		if i >= 12:
			s = s[:i]
	return s


def push_kind(p):
	""
	ev = Notifier._event(p)
	text = _PK_SIM.sub(" ", str(p.get("text") or "")).strip()
	if push_map(p):
		text = _pk_nomap(text)
	raw = re.sub(r"^\{name\}\s*:\s*", "", str(p.get("info_title") or "")).strip()
	test = raw.startswith("[Test] ")
	raw = re.sub(r"^\[Test\]\s*", "", raw)
	raw = _PK_SIM.sub(" ", raw).strip()
	out = None
	for tpls, ic, ti, tx, cls, pic in PK_TEXTS:
		for t_ in tpls:
			for cand in dict.fromkeys(_pk_tpl(t_)):
				v = _pk_match(cand, text)
				if v is not None:
					out = {"ic": ic, "title": _pk_fill(pk_tr(ti), v), "text": _pk_fill(pk_tr(tx), v), "cls": cls, "pic": pic}
					break
			if out:
				break
		if out:
			break
	if out is None:
		for key, (ic, ti, cls, pic) in PK_TITLES.items():
			for k_ in dict.fromkeys((tr(key), key)):
				if raw == k_ or raw.startswith(k_ + " – "):
					out = {"ic": ic, "title": pk_tr(ti) + raw[len(k_):], "text": _pk_cut(text), "cls": cls, "pic": pic}
					break
			if out:
				break
	if out is None:
		ti = render_msg(raw, p).strip()
		tx = _pk_cut(text)
		if not ti:
			m = re.match(r"^([^:·\n]{3,30}):\s+(.+)$", tx)
			ti, tx = (m.group(1), m.group(2)) if m else (pk_tr("Note"), tx)
		out = {"ic": ev_icon(ev), "title": ti, "text": tx, "cls": "alarm" if ev == "tamper" else "info", "pic": False}
	m = re.match(r"^" + re.escape(out["title"]) + r"\s*:\s*", out["text"], re.I) if out["title"] else None
	if m and out["text"][m.end():]:
		rest = out["text"][m.end():]
		out["text"] = (rest[:1].upper() + rest[1:]) if " " in rest else rest
	if ev == "tamper":
		out["cls"] = "alarm"
	out["test"] = test
	return out


def push_show_name():
	"""


"""
	if CFG.get("fleet"):
		return True
	try:
		return bool(CFG.get("sim_on") and (_SIMHUB.get("d") or {}).get("dev2"))
	except NameError:
		return False


def push_long(p):
	"""
"""
	ev = Notifier._event(p)
	if ev in ("info", "tamper"):
		t_ = str(p.get("text") or "")
	else:
		kind = "person" if ev == "test" else ev
		t_ = render_msg(msg_template(kind, 1), dict(p, persons=max(1, int(p.get("persons") or 0))) if ev == "test" else p)
		if p.get("dist"):
			t_ += " · " + str(p["dist"])
	if p.get("more"):
		t_ += " " + trf("(+{n} more detections since the last message)", n=p["more"])
	if p.get("late"):
		t_ += " · " + trf("late - from {t} (the message could not be sent then)", t=str(p.get("time", ""))[11:16])
	return t_


def push_protect_on():
	"""
"""
	w = WATCH_REF.get("w")
	n = getattr(w, "notifier", None) if w is not None else None
	if n is None:
		return False
	try:
		return bool(n.info(tr("Protection on - alarms are active"), title="{name}: " + tr("Protection")))
	except Exception as e:
		log_event("sys", f"Protection on message: {type(e).__name__}"[:120])
		return False


def push_short(p):
	"""
"""
	ev = Notifier._event(p)
	icons = CFG.get("msg_icons", True)
	t_ = str(p.get("time") or "")
	hm = t_[11:16]
	if ev in ("info", "tamper"):
		k = push_kind(p)
		ic, title, parts = k["ic"], k["title"], [k["text"]]
		if push_show_name():
			title = ((CFG.get("device_name") or "").strip()[:20] or "MoveEye") + ": " + title
		title = ("[Test] " if k["test"] else "") + ((ic + " ") if icons and ic else "") + title
	else:
		kind = "person" if ev == "test" else ev
		pp = dict(p, persons=max(1, int(p.get("persons") or 0))) if ev == "test" else p
		own_t = str(CFG.get(f"msg_{kind}_title", "") or "").strip()
		own_x = str(CFG.get(f"msg_{kind}_text", "") or "").strip()
		n = int(pp.get("persons") or 0)
		title = render_msg(own_t, pp) if own_t else (pk_trf("{n} persons", n=n) if kind == "person" and n > 1 else pk_tr(PK_EVENT.get(kind, "Note")))
		if push_show_name() and not own_t:
			title = ((CFG.get("device_name") or "").strip()[:20] or "MoveEye") + ": " + title
		ic = ev_icon(kind)
		if icons and ic and not title.startswith(ic):
			title = ic + " " + title
		title = ("[Test] " + title) if ev == "test" else title
		if own_x:
			parts = [render_msg(own_x, pp)]
		else:
			parts = [hm]
			if ev == "test":
				parts.append(pk_tr("Test message"))
			elif kind == "person" and p.get("dist"):
				d = str(p["dist"])
				for h_ in (tr("Person") + ", ",):
					d = d[len(h_):] if d.startswith(h_) else d
				parts.append(d)
			elif kind == "prealarm":
				parts.append(pk_tr("pre-alarm"))
			elif kind == "warm":
				parts.append(pk_tr("thermal camera"))
			elif kind == "noise" and p.get("db") not in (None, ""):
				parts.append(f"{p['db']} dB")
		if own_x and p.get("dist"):
			parts.append(str(p["dist"]))
	if p.get("more"):
		parts.append(pk_trf("+{n} more", n=p["more"]))
	if p.get("late"):
		parts.append(pk_trf("late, from {t}", t=hm))
	title = pk_line(_PK_PH.sub("", render_msg(title, p)) if "{" in title else title, 60)
	text = pk_line(" · ".join(x for x in parts if x))
	return {"title": title, "text": text, "map": push_map(p)}


def push_frame_jpg():
	""
	try:
		w = WATCH_REF.get("w")
		fr = getattr(w, "frame_out", None) if w is not None else None
		if fr is None:
			return None
		h, w_ = fr.shape[:2]
		if w_ > 640:
			fr = cv2.resize(fr, (640, int(h * 640 / w_)), interpolation=cv2.INTER_AREA)
		ok, buf = cv2.imencode(".jpg", fr, [cv2.IMWRITE_JPEG_QUALITY, 75])
		return buf.tobytes() if ok else None
	except Exception:
		return None


_PK_HELD = {"t": 0.0}


def push_sim_hold(p):
	""
	if not CFG.get("sim_on") or CFG.get("sim_info_push") or Notifier._event(p) != "info":
		return False
	cls = push_kind(p)["cls"]
	if cls in ("alarm", "sim"):
		return False
	if cls in ("hw", "hw_batt") and "🧪" not in str(p.get("text") or "") + str(p.get("info_title") or ""):
		if not (cls == "hw_batt" and (STATE.get("battery") or {}).get("sim")):
			return False
	STATE["notify_status"] = "simulation: only alarms"
	if time.time() - _PK_HELD["t"] > 60:
		_PK_HELD["t"] = time.time()
		log_event("web", "Info message not sent to the phone (simulation: only alarms, switch «In the simulator: info messages to the phone»)")
	return True



