def fx_for_text(*texts):
	""
	s = " ".join(str(t or "") for t in texts).lower()
	if not s.strip():
		return None
	for e in fx_entries():
		for m in (e.get("quelle") or {}).get("meldung") or []:
			for v in {m, tr(m)}:
				if v and v.lower() in s:
					return e
	return None


def fx_push_line(e):
	""
	u = fx_url(e["id"])
	return ("\n🛠 " + fx_ui("help", None) + ": " + u) if u else ""


_alert_before_fx = Notifier.alert
